const rtdal009730Source0021 = "cnd_body_subscript_dim <- function(cnd, ...) {\n  arg <- append_arg(\"Subscript\", cnd$subscript_arg)\n\n  dim <- length(dim(cnd$i))\n  if (dim < 2) {\n    abort(\n      \"Internal error: Unexpected dimensionality in `cnd_body_subcript_dim()`.\"\n    )\n  }\n  if (dim == 2) {\n    shape <- \"a matrix\"\n  } else {\n    shape <- \"an array\"\n  }\n\n  format_error_bullets(c(\n    x = glue::glue(\"{arg} must be a simple vector, not {shape}.\")\n  ))\n}"

const rtdal009730Source0022 = "cnd_subscript_element <- function(cnd, capital = FALSE) {\n  elt <- cnd$subscript_elt %||% \"element\"\n\n  if (!is_string(elt, c(\"element\", \"row\", \"column\", \"table\"))) {\n    abort(paste0(\n      \"Internal error: `cnd$subscript_elt` must be one of \",\n      \"`element`, `row`, `column` or `table`.\"\n    ))\n  }\n\n  if (capital) {\n    switch(\n      elt,\n      element = c(\"Element\", \"Elements\"),\n      row = c(\"Row\", \"Rows\"),\n      column = c(\"Column\", \"Columns\"),\n      table = c(\"Table\", \"Tables\")\n    )\n  } else {\n    switch(\n      elt,\n      element = c(\"element\", \"elements\"),\n      row = c(\"row\", \"rows\"),\n      column = c(\"column\", \"columns\"),\n      table = c(\"table\", \"tables\")\n    )\n  }\n}"

const rtdal009730Source0023 = "cnd_subscript_element_cli <- function(n, cnd, capital = FALSE) {\n  elt <- cnd$subscript_elt %||% \"element\"\n\n  if (!is_string(elt, c(\"element\", \"row\", \"column\", \"table\"))) {\n    abort(paste0(\n      \"Internal error: `cnd$subscript_elt` must be one of \",\n      \"`element`, `row`, `column` or `table`.\"\n    ))\n  }\n\n  if (capital) {\n    elt <- switch(\n      elt,\n      element = \"Element{?s}\",\n      row = \"Row{?s}\",\n      column = \"Column{?s}\",\n      table = \"Table{?s}\"\n    )\n  } else {\n    elt <- switch(\n      elt,\n      element = \"element{?s}\",\n      row = \"row{?s}\",\n      column = \"column{?s}\",\n      table = \"table{?s}\"\n    )\n  }\n\n  cli::pluralize(\"{n} \", elt)\n}"

const rtdal009730Source0025 = "cnd_subscript_action <- function(cnd, assign_to = TRUE) {\n  action <- cnd$subscript_action\n\n  if (is_null(action)) {\n    if (cnd_subscript_scalar(cnd)) {\n      action <- \"extract\"\n    } else {\n      action <- \"subset\"\n    }\n  }\n\n  if (!is_string(action, subscript_actions)) {\n    cli::cli_abort(\n      \"`cnd$subscript_action` must be one of {.or {.arg {subscript_actions}}}.\",\n      .internal = TRUE\n    )\n  }\n\n  if (assign_to && action == \"assign\") {\n    \"assign to\"\n  } else {\n    action\n  }\n}"

const rtdal009730Source0026 = `cnd_subscript_arg <- function(cnd, ...) {
  format_subscript_arg(cnd[["subscript_arg"]], ...)
}`

const rtdal009730Source0027 = `format_subscript_arg <- function(arg, capitalise = TRUE) {
  if (is_subscript_arg(arg)) {
    if (!is_string(arg)) {
      arg <- as_label(arg)
    }
    cli::format_inline("{.arg {arg}}")
  } else {
    if (capitalise) {
      "Subscript"
    } else {
      "subscript"
    }
  }
}`

