const rtdal009749Source0006 = "vctr_cast <- function(\n  x,\n  to,\n  ...,\n  x_arg = \"\",\n  to_arg = \"\",\n  call = caller_env()\n) {\n  # These are not strictly necessary, but make bootstrapping a new class\n  # a bit simpler\n  if (is.object(x)) {\n    if (is_same_type(x, to)) {\n      x\n    } else {\n      stop_incompatible_cast(\n        x,\n        to,\n        x_arg = x_arg,\n        to_arg = to_arg,\n        call = call\n      )\n    }\n  } else {\n    # FIXME: `vec_restore()` should only be called on proxies\n    vec_restore(x, to)\n  }\n}"

