const rtdal009749Source0029 = "as.data.frame2 <- function(x) {\n  # Unclass to avoid dispatching on `as.data.frame()` methods that break size\n  # invariants, like `as.data.frame.table()` (#913). This also prevents infinite\n  # recursion with shaped vctrs in `as.data.frame.vctrs_vctr()`.\n  x <- unclass(x)\n\n  out <- as.data.frame(x)\n\n  if (vec_dim_n(x) == 1) {\n    # 1D arrays are not stripped from their dimensions\n    out[[1]] <- as.vector(out[[1]])\n\n    # 1D arrays are auto-labelled with substitute()\n    names(out) <- \"V1\"\n  }\n\n  out\n}"

const rtdal009749Source0030 = `as.data.frame.vctrs_vctr <- function(
  x,
  row.names = NULL,
  optional = FALSE,
  ...,
  nm = paste(deparse(substitute(x), width.cutoff = 500L), collapse = " ")
) {
  force(nm)

  if (has_dim(x)) {
    return(as.data.frame2(x))
  }

  cols <- list(x)
  if (!optional) {
    names(cols) <- nm
  }

  new_data_frame(cols, n = vec_size(x))
}`

