const rtdal009753Source0017 = `obj_type <- function(x) {
  if (vec_is(x)) {
    vec_ptype_full(x)
  } else if (is.object(x)) {
    paste(class(x), collapse = "/")
  } else if (is_function(x)) {
    "function"
  } else {
    typeof(x)
  }
}`

const rtdal009753Source0018 = "new_opts <- function(x, opts, subclass = NULL, arg = NULL) {\n  if (!all(x %in% opts)) {\n    if (is_null(arg)) {\n      arg <- \"Argument\"\n    } else {\n      arg <- glue::glue(\"`{arg}`\")\n    }\n    opts <- encodeString(opts, quote = \"\\\"\")\n    opts <- glue::glue_collapse(opts, sep = \", \", last = \" or \")\n    abort(glue::glue(\"{arg} must be one of {opts}.\"))\n  }\n\n  structure(\n    set_names(opts %in% x, opts),\n    class = c(subclass, \"vctrs_opts\")\n  )\n}"

