const rtdal009762Source0011 = `expect_error_cnd <- function(
  object,
  class,
  message = NULL,
  ...,
  .fixed = TRUE
) {
  cnd <- expect_error(
    object,
    regexp = message,
    class = class[[1]],
    fixed = .fixed
  )
  expect_true(inherits_all(cnd, class))

  exp_fields <- list2(...)
  expect_true(is_empty(setdiff(!!names(exp_fields), names(cnd))))
  expect_equal(cnd[names(exp_fields)], exp_fields)
}`

