const rtdal009778Source0003 = `set_rownames_recursively <- function(x, i = NULL) {
  n <- vec_size(x)
  stopifnot(n <= length(letters))

  for (j in seq_along(x)) {
    if (is.data.frame(x[[j]])) {
      x[[j]] <- set_rownames_recursively(x[[j]], i = i)
    }
  }

  row.names(x) <- paste0(letters[seq_len(n)], i)
  x
}`

const rtdal009778Source0004 = "expect_waldo_equal <- function(type, act, exp, info, ...) {\n  comp <- waldo::compare(\n    act$val,\n    exp$val,\n    ...,\n    x_arg = \"actual\",\n    y_arg = \"expected\"\n  )\n  expect(\n    length(comp) == 0,\n    sprintf(\n      \"`actual` (%s) not %s to `expected` (%s).\\n\\n%s\",\n      act$lab,\n      type,\n      exp$lab,\n      paste0(comp, collapse = \"\\n\\n\")\n    ),\n    info = info\n  )\n\n  invisible(act$val)\n}"

