const rtdal009781Source0027 = `test_that("row names are preserved by vec_rbind()", {
  df1 <- mtcars[1:3, ]
  df2 <- mtcars[4:5, ]
  expect_identical(vec_rbind(df1, df2), mtcars[1:5, ])

  row.names(df2) <- NULL
  out <- mtcars[1:5, ]
  row.names(out) <- c(row.names(df1), "...4", "...5")
  expect_identical(vec_rbind(df1, df2), out)
})`

const rtdal009781Source0028 = `test_that("can assign row names in vec_rbind()", {
  df1 <- mtcars[1:3, ]
  df2 <- mtcars[4:5, ]

  expect_snapshot({
    (expect_error(
      vec_rbind(
        foo = df1,
        df2,
        .names_to = NULL
      ),
      "specification"
    ))
  })

  # Combination
  out <- vec_rbind(
    foo = df1,
    df2,
    .names_to = NULL,
    .name_spec = "{outer}_{inner}"
  )
  exp <- mtcars[1:5, ]
  row.names(exp) <- c(paste0("foo_", row.names(df1)), row.names(df2))
  expect_identical(out, exp)

  out <- vec_rbind(foo = df1, df2, .names_to = "id")
  exp <- mtcars[1:5, ]
  exp <- vec_cbind(id = c(rep("foo", 3), rep("", 2)), exp)
  expect_identical(out, exp)

  # Sequence
  out <- vec_rbind(
    foo = unrownames(df1),
    df2,
    bar = unrownames(mtcars[6, ]),
    .names_to = NULL,
    .name_spec = "{outer}_{inner}"
  )
  exp <- mtcars[1:6, ]
  row.names(exp) <- c(paste0("foo_", 1:3), row.names(df2), "bar")
  expect_identical(out, exp)

  out <- vec_rbind(
    foo = unrownames(df1),
    df2,
    bar = unrownames(mtcars[6, ]),
    .names_to = "id"
  )
  exp <- mtcars[1:6, ]
  exp <- vec_cbind(id = c(rep("foo", 3), rep("", 2), "bar"), exp)
  row.names(exp) <- c(paste0("...", 1:3), row.names(df2), "...6")
  expect_identical(out, exp)
})`

const rtdal009781Source0029 = "test_that(\"vec_rbind() takes the proxy and restores\", {\n  df <- foobar(data.frame(x = 1))\n\n  # This data frame subclass has an identity proxy and the restore\n  # method falls back to a bare data frame if `$x` has any missing values.\n  # In `vec_rbind()`, the `vec_init()` call will create a bare data frame,\n  # but at the end it is `vec_restore()`d to the right class.\n  local_methods(\n    vec_ptype2.vctrs_foobar.vctrs_foobar = function(x, y, ...) {\n      x\n    },\n    vec_cast.vctrs_foobar.vctrs_foobar = function(x, to, ...) {\n      x\n    },\n    vec_proxy.vctrs_foobar = function(x, ...) {\n      x\n    },\n    vec_restore.vctrs_foobar = function(x, to, ...) {\n      if (any(is.na(x$x))) {\n        new_data_frame(x)\n      } else {\n        vec_restore_default(x, to)\n      }\n    }\n  )\n\n  expect_identical(\n    vec_rbind(df, df),\n    foobar(data.frame(x = c(1, 1)))\n  )\n})"

const rtdal009781Source0030 = "test_that(\"vec_rbind() proxies before initializing\", {\n  df <- foobar(data.frame(x = 1))\n\n  # This data frame subclass doesn't allow `NA`s in columns.\n  # If initialization happened before proxying, it would try to\n  # create `NA` rows with `vec_init()`.\n  local_methods(\n    vec_ptype2.vctrs_foobar.vctrs_foobar = function(x, y, ...) {\n      x\n    },\n    vec_cast.vctrs_foobar.vctrs_foobar = function(x, to, ...) {\n      x\n    },\n    vec_proxy.vctrs_foobar = function(x, ...) {\n      new_data_frame(x)\n    },\n    vec_restore.vctrs_foobar = function(x, to, ...) {\n      if (any(is.na(x$x))) {\n        abort(\"`x` can't have NA values.\")\n      }\n      vec_restore_default(x, to)\n    }\n  )\n\n  expect_identical(\n    vec_rbind(df, df),\n    foobar(data.frame(x = c(1, 1)))\n  )\n})"

const rtdal009781Source0031 = `test_that("vec_rbind() requires a data frame proxy for data frame ptypes", {
  df <- foobar(data.frame(x = 1))

  local_methods(
    vec_ptype2.vctrs_foobar.vctrs_foobar = function(x, y, ...) x,
    vec_cast.vctrs_foobar.vctrs_foobar = function(x, to, ...) x,
    vec_proxy.vctrs_foobar = function(x, ...) 1
  )

  expect_error(
    vec_rbind(df, df),
    "Can't fill a data frame that doesn't have a data frame proxy"
  )
})`

