const rtdal009781Source0075 = `test_that("vec_rbind() falls back to c() if S3 method is available", {
  x <- foobar(1, foo = 1)
  y <- foobar(2, bar = 2)

  x_df <- data_frame(x = x)
  y_df <- data_frame(x = y)

  expect_error(vec_rbind(x_df, y_df), class = "vctrs_error_incompatible_type")
  expect_error(vec_c(x_df, y_df), class = "vctrs_error_incompatible_type")
  expect_error(
    list_unchop(list(x_df, y_df), indices = list(1, 2)),
    class = "vctrs_error_incompatible_type"
  )

  with_c_method <- function(expr) {
    with_methods(
      c.vctrs_foobar = function(...) quux(NextMethod()),
      expr
    )
  }

  out <- with_c_method(vec_rbind(x_df, y_df))
  exp <- data_frame(x = quux(c(1, 2)))
  expect_identical(out, exp)

  expect_identical(with_c_method(vec_c(x_df, y_df)), exp)
  expect_identical(
    with_c_method(list_unchop(list(x_df, y_df), indices = list(1, 2))),
    exp
  )

  # Fallback is used with data frame subclasses, with or without
  # ptype2 method
  foo_df <- foobaz(x_df)
  bar_df <- foobaz(y_df)

  out <- with_c_method(vec_rbind(foo_df, bar_df))
  exp <- foobaz(data_frame(x = quux(c(1, 2))))
  expect_identical(out, exp)

  expect_identical(with_c_method(vec_c(foo_df, bar_df)), exp)
  expect_identical(
    with_c_method(list_unchop(list(foo_df, bar_df), indices = list(1, 2))),
    exp
  )

  with_hybrid_methods <- function(expr, cast = TRUE) {
    methods <- list(
      c.vctrs_foobar = function(...) quux(NextMethod()),
      vec_ptype2.vctrs_foobaz.vctrs_foobaz = function(...) {
        foobaz(df_ptype2(...))
      },
      vec_cast.vctrs_foobaz.vctrs_foobaz = if (cast) {
        function(...) foobaz(df_cast(...))
      }
    )
    with_methods(expr, !!!compact(methods))
  }

  expect_equal(
    with_hybrid_methods(
      cast = FALSE,
      vec_rbind(foo_df, bar_df)
    ),
    foobaz(data_frame(x = quux(c(1, 2))))
  )

  # Falls back to data frame because there is no ptype2/cast methods
  out <- with_hybrid_methods(vec_rbind(foo_df, bar_df))
  exp <- foobaz(data_frame(x = quux(c(1, 2))))
  expect_identical(out, exp)

  expect_identical(with_hybrid_methods(vec_c(foo_df, bar_df)), exp)
  expect_identical(
    with_hybrid_methods(list_unchop(
      list(foo_df, bar_df),
      indices = list(1, 2)
    )),
    exp
  )

  wrapper_x_df <- data_frame(x = x_df)
  wrapper_y_df <- data_frame(x = y_df)

  out <- with_c_method(vec_rbind(wrapper_x_df, wrapper_y_df))
  exp <- data_frame(x = data_frame(x = quux(c(1, 2))))
  expect_identical(out, exp)

  expect_identical(with_c_method(vec_c(wrapper_x_df, wrapper_y_df)), exp)
  expect_identical(
    with_c_method(list_unchop(
      list(wrapper_x_df, wrapper_y_df),
      indices = list(1, 2)
    )),
    exp
  )
})`

const rtdal009781Source0076 = "test_that(\"c() fallback works with unspecified columns\", {\n  local_methods(\n    c.vctrs_foobar = function(...) foobar(NextMethod()),\n    `[.vctrs_foobar` = function(x, i, ...) {\n      foobar(NextMethod(), dispatched = TRUE)\n    }\n  )\n\n  out <- vec_rbind(\n    data_frame(x = foobar(1)),\n    data_frame(y = foobar(2))\n  )\n  expect_identical(\n    out,\n    data_frame(\n      x = foobar(c(1, NA), dispatched = TRUE),\n      y = foobar(c(NA, 2), dispatched = TRUE)\n    )\n  )\n})"

const rtdal009781Source0077 = "test_that(\"c() fallback works with vctrs-powered data frame subclass\", {\n  local_methods(\n    c.vctrs_quux = function(...) quux(vec_paste0(NextMethod(), \"-c\")),\n    `[.vctrs_quux` = function(x, i, ...) quux(vec_paste0(NextMethod(), \"-[\"))\n  )\n  local_foobar_df_methods()\n\n  ### Joint case\n  df1 <- foobar(data_frame(x = quux(1:3)))\n  df2 <- data_frame(x = quux(4:5))\n\n  out <- vctrs::vec_rbind(df1, df2)\n  exp <- foobar(data_frame(x = quux(paste0(1:5, \"-c\"))))\n  expect_identical(out, exp)\n\n  out <- vctrs::vec_rbind(df2, df1)\n  exp <- foobar(data_frame(x = quux(paste0(c(4:5, 1:3), \"-c\"))))\n  expect_identical(out, exp)\n\n  ### Disjoint case\n  df1 <- foobar(data_frame(x = quux(1:3)))\n  df2 <- data.frame(y = 4:5)\n\n  out <- vctrs::vec_rbind(df1, df2)\n  exp <- foobar(data_frame(\n    x = quux(c(paste0(1:3, \"-c-[\"), paste0(c(NA, NA), \"-[\"))),\n    y = c(rep(NA, 3), 4:5)\n  ))\n  expect_identical(out, exp)\n\n  out <- vctrs::vec_rbind(df2, df1)\n  exp <- foobar(data_frame(\n    y = c(4:5, rep(NA, 3)),\n    x = quux(c(paste0(c(NA, NA), \"-[\"), paste0(1:3, \"-c-[\")))\n  ))\n  expect_identical(out, exp)\n})"

