const rtdal009782Source0002 = `test_that("zero length input returns NULL", {
  expect_equal(vec_c(), NULL)
  expect_equal(vec_c(NULL), NULL)
  expect_equal(vec_c(NULL, ), NULL)
  expect_equal(vec_c(NULL, NULL), NULL)
})`

const rtdal009782Source0003 = `test_that("NULL is idempotent", {
  expect_equal(vec_c(NULL, 1L), 1L)
  expect_equal(vec_c(1L, NULL), 1L)
})`

const rtdal009782Source0004 = `test_that("NA is idempotent", {
  expect_equal(vec_c(NA, 1L), c(NA, 1L))
  expect_equal(vec_c(NA, "x"), c(NA, "x"))
  expect_equal(vec_c(NA, factor("x")), factor(c(NA, "x")))
  expect_equal(vec_c(NA, new_date(0)), new_date(c(NA, 0)))
  expect_equal(vec_c(NA, new_datetime(0)), new_datetime(c(NA, 0)))
  expect_equal(vec_c(NA, new_duration(0)), new_duration(c(NA, 0)))
})`

const rtdal009782Source0005 = `test_that("NA is logical if no other types intervene", {
  expect_equal(vec_c(logical()), logical())
  expect_equal(vec_c(NA), NA)
  expect_equal(vec_c(NA, NA), c(NA, NA))
})`

const rtdal009782Source0006 = `test_that("different types are coerced to common", {
  expect_equal(vec_c(TRUE, 1L, 1), c(1, 1, 1))
  expect_equal(vec_c(TRUE, 2:4), 1:4)
})`

const rtdal009782Source0007 = `test_that("specified .ptypes do not allow more casts", {
  expect_error(
    vec_c(TRUE, .ptype = character()),
    class = "vctrs_error_incompatible_type"
  )
})`

const rtdal009782Source0008 = `test_that("common type failure uses error call and error arg (#1641, #1692)", {
  expect_snapshot(error = TRUE, {
    vec_c("x", 1, .error_call = call("foo"), .error_arg = "arg")
  })
  expect_snapshot(error = TRUE, {
    vec_c(
      "x",
      .ptype = integer(),
      .error_call = call("foo"),
      .error_arg = "arg"
    )
  })
})`

const rtdal009782Source0009 = "test_that(\"common type failure uses positional errors\", {\n  expect_snapshot({\n    # Looking for `..1` and `a`\n    (expect_error(vec_c(1, a = \"x\", 2)))\n\n    # Directed cast should also produce positional errors (#1690)\n    (expect_error(vec_c(1, a = \"x\", 2, .ptype = double(), .error_arg = \"arg\")))\n\n    # Lossy cast\n    (expect_error(vec_c(1, a = 2.5, .ptype = integer())))\n  })\n})"

const rtdal009782Source0010 = `test_that("combines outer an inner names", {
  expect_equal(vec_c(x = 1), c(x = 1))
  expect_equal(vec_c(c(x = 1)), c(x = 1))

  expect_equal(vec_c(c(x = 1:2)), c(x1 = 1, x2 = 2))
  expect_error(vec_c(y = c(x = 1)), "Please supply")
})`

const rtdal009782Source0011 = `test_that("can bind data.frame columns", {
  df <- data.frame(x = NA, y = 1:2)
  df$x <- data.frame(a = 1:2)

  expected <- data.frame(x = NA, y = c(1:2, 1:2))
  expected$x <- data.frame(a = c(1:2, 1:2))

  expect_equal(vec_c(df, df), expected)
})`

const rtdal009782Source0012 = "test_that(\"vec_c() handles matrices\", {\n  m <- matrix(1:4, nrow = 2)\n  dimnames(m) <- list(c(\"foo\", \"bar\"), c(\"baz\", \"quux\"))\n\n  # FIXME: `vec_ptype_common(m, m)` doesn't return dimension names\n  exp <- matrix(c(1:2, 1:2, 3:4, 3:4), nrow = 4)\n  rownames(exp) <- c(\"foo\", \"bar\", \"foo\", \"bar\")\n\n  expect_identical(vec_c(m, m), exp)\n\n  expect_error(vec_c(outer = m), \"Please supply\")\n})"

const rtdal009782Source0013 = `test_that("vec_c() includes index in argument tag", {
  df1 <- tibble(x = tibble(y = tibble(z = 1)))
  df2 <- tibble(x = tibble(y = tibble(z = "a")))

  expect_snapshot(error = TRUE, vec_c(df1, df2))
  expect_snapshot(error = TRUE, vec_c(df1, df1, df2))
  expect_snapshot(error = TRUE, vec_c(foo = df1, bar = df2))
})`

const rtdal009782Source0014 = `test_that("vec_c() handles record classes", {
  local_rational_class()

  out <- vec_c(rational(1, 2), 1L, NA)

  expect_true(vec_is(out, rational(1, 2)))
  expect_size(out, 3)
  expect_identical(
    vec_proxy(out),
    data.frame(n = c(1L, 1L, NA), d = c(2L, 1L, NA))
  )
})`

const rtdal009782Source0015 = `test_that("can mix named and unnamed vectors (#271)", {
  expect_identical(vec_c(c(a = 1), 2), c(a = 1, 2))
  expect_identical(vec_c(0, c(a = 1), 2, b = 3), c(0, a = 1, 2, b = 3))
})`

const rtdal009782Source0016 = `test_that("preserves names when inputs are cast to a common type (#1690)", {
  expect_named(vec_c(c(a = 1), .ptype = integer()), "a")
  expect_named(
    vec_c(foo = c(a = 1), .ptype = integer(), .name_spec = "{outer}_{inner}"),
    "foo_a"
  )
  expect_named(
    vec_c(foo = c(a = 1), .ptype = integer(), .name_spec = "inner"),
    "a"
  )
})`

const rtdal009782Source0017 = "test_that(\"vec_c() repairs names\", {\n  local_name_repair_quiet()\n\n  # Default minimal repair\n  expect_named(vec_c(a = 1, a = 2, `_` = 3), c(\"a\", \"a\", \"_\"))\n  out <- vec_c(!!!set_names(1, NA))\n  expect_named(out, \"\")\n\n  expect_named(\n    vec_c(a = 1, a = 2, `_` = 3, .name_repair = \"unique\"),\n    c(\"a...1\", \"a...2\", \"_\")\n  )\n  expect_error(\n    vec_c(a = 1, a = 2, `_` = 3, .name_repair = \"check_unique\"),\n    class = \"vctrs_error_names_must_be_unique\"\n  )\n\n  expect_named(\n    vec_c(a = 1, a = 2, `_` = 3, .name_repair = \"universal\"),\n    c(\"a...1\", \"a...2\", \"._\")\n  )\n\n  expect_named(vec_c(a = 1, a = 2, .name_repair = ~ toupper(.)), c(\"A\", \"A\"))\n})"

const rtdal009782Source0018 = `test_that("vec_c() can repair names quietly", {
  local_name_repair_verbose()

  expect_snapshot({
    res_unique <- vec_c(x = TRUE, x = 0, .name_repair = "unique_quiet")
    res_universal <- vec_c(
      "if" = TRUE,
      "in" = 0,
      .name_repair = "universal_quiet"
    )
  })
  expect_named(res_unique, c("x...1", "x...2"))
  expect_named(res_universal, c(".if", ".in"))
})`

const rtdal009782Source0019 = `test_that("vec_c() doesn't use outer names for data frames (#524)", {
  x <- data.frame(inner = 1)
  expect_equal(vec_c(outer = x), x)

  a <- data.frame(x = 1L)
  b <- data.frame(x = 2L)
  expect_equal(vec_c(foo = a, bar = b), data.frame(x = 1:2))
})`

const rtdal009782Source0020 = `test_that("vec_c() preserves row names and inner names", {
  x <- data.frame(a = 1, row.names = "r1")
  y <- data.frame(a = 2, row.names = "r2")
  expect_equal(rownames(vec_c(x, y)), c("r1", "r2"))
  expect_equal(rownames(vec_c(x, x)), c("r1...1", "r1...2"))

  vec_x <- set_names(1:3, letters[1:3])
  vec_y <- c(FOO = 4L)
  oo_x <- set_names(
    as.POSIXlt(c("2020-01-01", "2020-01-02", "2020-01-03")),
    letters[1:3]
  )
  oo_y <- as.POSIXlt(c(FOO = "2020-01-04"))
  df_x <- new_data_frame(list(x = 1:3), row.names = letters[1:3])
  df_y <- new_data_frame(list(x = 4L), row.names = "d")
  mat_x <- matrix(1:3, 3, dimnames = list(letters[1:3]))
  mat_y <- matrix(4L, 1, dimnames = list("d"))
  nested_x <- new_data_frame(
    list(df = df_x, mat = mat_x, vec = vec_x, oo = oo_x),
    row.names = c("foo", "bar", "baz")
  )
  nested_y <- new_data_frame(
    list(df = df_y, mat = mat_y, vec = vec_y, oo = oo_y),
    row.names = c("quux")
  )

  nested_out <- vec_c(nested_x, nested_y)
  expect_identical(row.names(nested_out), c("foo", "bar", "baz", "quux"))
  expect_identical(row.names(nested_out$df), c("a", "b", "c", "d"))
  expect_identical(row.names(nested_out$mat), c("a", "b", "c", "d"))
  expect_identical(names(nested_out$vec), c("a", "b", "c", "FOO"))
  expect_identical(names(nested_out$oo), c("a", "b", "c", "FOO"))
})`

const rtdal009782Source0021 = `test_that("vec_c() outer names work with proxied objects", {
  x <- as.POSIXlt(new_datetime(0))
  exp <- set_names(x, "outer")
  expect_equal(vec_c(outer = x), exp)

  named_x <- set_names(x, "inner")
  exp <- set_names(named_x, "outer_inner")
  expect_error(vec_c(outer = named_x), "Please supply")
  expect_equal(vec_c(outer = named_x, .name_spec = "{outer}_{inner}"), exp)

  xs <- as.POSIXlt(new_datetime(c(0, 1)))
  exp <- set_names(xs, c("outer_1", "outer_2"))
  expect_error(vec_c(outer = xs), "Please supply")
  expect_equal(vec_c(outer = xs, .name_spec = "{outer}_{inner}"), exp)
})`

const rtdal009782Source0022 = `test_that("vec_c() works with simple homogeneous foreign S3 classes", {
  expect_identical(vec_c(foobar(1), foobar(2)), vec_c(foobar(c(1, 2))))
  expect_identical(vec_c(NULL, foobar(1), foobar(2)), vec_c(foobar(c(1, 2))))
})`

