const rtdal009782Source0038 = "test_that(\"base c() fallback handles unspecified chunks\", {\n  local_methods(\n    c.vctrs_foobar = function(...) {\n      x <- NextMethod()\n\n      # Should not be passed any unspecified chunks\n      if (anyNA(x)) {\n        abort(\"tilt\")\n      }\n\n      foobar(x)\n    },\n    `[.vctrs_foobar` = function(x, i, ...) {\n      # Return a quux to detect dispatch\n      quux(NextMethod())\n    }\n  )\n\n  out <- vec_c(foobar(1:2), rep(NA, 2))\n  expect_identical(out, quux(c(1:2, NA, NA)))\n\n  out <- vec_c(rep(NA, 2), foobar(1:2), NA)\n  expect_identical(out, quux(c(NA, NA, 1:2, NA)))\n})"

const rtdal009782Source0039 = `test_that("can zap outer names from a name-spec (#1215)", {
  zap_outer_spec <- function(outer, inner) if (is_character(inner)) inner

  expect_null(
    names(vec_c(a = 1:2, .name_spec = zap_outer_spec))
  )
  expect_identical(
    names(vec_c(a = 1:2, c(foo = 3L), .name_spec = zap_outer_spec)),
    c("", "", "foo")
  )

  expect_null(
    names(list_unchop(
      list(a = 1:2),
      indices = list(1:2),
      name_spec = zap_outer_spec
    ))
  )
  expect_identical(
    names(list_unchop(
      list(a = 1:2, c(foo = 3L)),
      indices = list(1:2, 3),
      name_spec = zap_outer_spec
    )),
    c("", "", "foo")
  )

  # These days it is more efficient to use a name-spec of "inner" (#1988)
  expect_identical(
    vec_c(a = 1:2, .name_spec = zap_outer_spec),
    vec_c(a = 1:2, .name_spec = "inner")
  )
  expect_identical(
    vec_c(a = 1:2, c(foo = 3L), .name_spec = zap_outer_spec),
    vec_c(a = 1:2, c(foo = 3L), .name_spec = "inner")
  )
  expect_identical(
    list_unchop(list(a = 1:2), indices = list(1:2), name_spec = zap_outer_spec),
    list_unchop(list(a = 1:2), indices = list(1:2), name_spec = "inner")
  )
  expect_identical(
    list_unchop(
      list(a = 1:2, c(foo = 3L)),
      indices = list(1:2, 3),
      name_spec = zap_outer_spec
    ),
    list_unchop(
      list(a = 1:2, c(foo = 3L)),
      indices = list(1:2, 3),
      name_spec = "inner"
    )
  )
})`

