const rtdal009783Source0001 = `test_that("works with data frames", {
  conditions <- list(
    c(FALSE, TRUE, FALSE, FALSE),
    c(TRUE, TRUE, FALSE, FALSE),
    c(FALSE, TRUE, FALSE, TRUE)
  )
  values <- list(
    data_frame(x = 1, y = 2),
    data_frame(x = 3, y = 4),
    data_frame(x = 3:6, y = 4:7)
  )

  out <- vec_case_when(conditions, values)

  expect_identical(
    out,
    data_frame(
      x = c(3, 1, NA, 6),
      y = c(4, 2, NA, 7)
    )
  )
})`

const rtdal009783Source0002 = "test_that(\"first `TRUE` case wins\", {\n  conditions <- list(\n    c(TRUE, FALSE),\n    c(TRUE, TRUE),\n    c(TRUE, TRUE)\n  )\n  values <- list(\n    1,\n    2,\n    3\n  )\n\n  expect_identical(\n    vec_case_when(conditions, values),\n    c(1, 2)\n  )\n})"

const rtdal009783Source0003 = "test_that(\"can replace missing values by catching with `is.na()`\", {\n  x <- c(1:3, NA)\n\n  conditions <- list(\n    x <= 1,\n    x <= 2,\n    is.na(x)\n  )\n  values <- list(\n    1,\n    2,\n    0\n  )\n\n  expect_identical(\n    vec_case_when(conditions, values),\n    c(1, 2, NA, 0)\n  )\n})"

const rtdal009783Source0004 = "test_that(\"Unused logical `NA` can still be cast to `values` ptype\", {\n  # Requires that casting happen before recycling, because it recycles\n  # to size zero, resulting in a logical rather than an unspecified.\n  expect_identical(\n    vec_case_when(list(TRUE, FALSE), list(\"x\", NA)),\n    \"x\"\n  )\n  expect_identical(\n    vec_case_when(list(FALSE, TRUE), list(\"x\", NA)),\n    NA_character_\n  )\n})"

const rtdal009783Source0005 = "test_that(\"`conditions` inputs can be size zero\", {\n  expect_identical(\n    vec_case_when(\n      list(logical(), logical()),\n      list(1, 2)\n    ),\n    numeric()\n  )\n\n  expect_snapshot(error = TRUE, {\n    vec_case_when(list(logical()), list(1:2))\n  })\n})"

const rtdal009783Source0006 = "test_that(\"retains inner names of `values` inputs\", {\n  value1 <- c(x = 1, y = 2)\n  value2 <- c(z = 3, w = 4)\n\n  out <- vec_case_when(\n    list(c(TRUE, FALSE), c(TRUE, TRUE)),\n    list(a = value1, b = value2)\n  )\n\n  expect_named(out, c(\"x\", \"w\"))\n})"

