const rtdal009783Source0008 = "test_that(\"`values` are cast to their common type\", {\n  expect_identical(vec_case_when(list(FALSE, TRUE), list(1, 2L)), 2)\n  expect_identical(vec_case_when(list(FALSE, TRUE), list(1, NA)), NA_real_)\n\n  expect_snapshot(error = TRUE, {\n    vec_case_when(list(FALSE, TRUE), list(1, \"x\"))\n  })\n})"

const rtdal009783Source0009 = "test_that(\"`values` must be size 1 or same size as the `conditions`\", {\n  expect_identical(\n    vec_case_when(\n      list(c(TRUE, TRUE)),\n      list(1)\n    ),\n    c(1, 1)\n  )\n  expect_identical(\n    vec_case_when(\n      list(c(TRUE, FALSE), c(TRUE, TRUE)),\n      list(c(1, 2), c(3, 4))\n    ),\n    c(1, 4)\n  )\n\n  expect_snapshot(error = TRUE, {\n    vec_case_when(\n      list(c(TRUE, FALSE, TRUE, TRUE)),\n      list(1:3)\n    )\n  })\n})"

const rtdal009783Source0010 = "test_that(\"Unhandled `NA` are given a value of `default`\", {\n  expect_identical(\n    vec_case_when(list(NA), list(1)),\n    NA_real_\n  )\n\n  expect_identical(\n    vec_case_when(list(NA), list(1), default = 2),\n    2\n  )\n\n  expect_identical(\n    vec_case_when(\n      list(\n        c(FALSE, NA, TRUE, FALSE),\n        c(NA, FALSE, TRUE, FALSE)\n      ),\n      list(\n        2,\n        3\n      ),\n      default = 4\n    ),\n    c(4, 4, 2, 4)\n  )\n})"

const rtdal009783Source0011 = "test_that(\"`NA` is overridden by any `TRUE` values\", {\n  x <- c(1, 2, NA, 3)\n  expect <- c(\"one\", \"not_one\", \"missing\", \"not_one\")\n\n  # `TRUE` overriding before the `NA`\n  conditions <- list(\n    is.na(x),\n    x == 1\n  )\n  values <- list(\n    \"missing\",\n    \"one\"\n  )\n  expect_identical(\n    vec_case_when(\n      conditions,\n      values,\n      default = \"not_one\"\n    ),\n    expect\n  )\n\n  # `TRUE` overriding after the `NA`\n  conditions <- list(\n    x == 1,\n    is.na(x)\n  )\n  values <- list(\n    \"one\",\n    \"missing\"\n  )\n  expect_identical(\n    vec_case_when(\n      conditions,\n      values,\n      default = \"not_one\"\n    ),\n    expect\n  )\n})"

const rtdal009783Source0012 = "test_that(\"works when there is a used `default` and no missing values\", {\n  expect_identical(\n    vec_case_when(list(c(TRUE, FALSE)), list(1), default = 3:4),\n    c(1, 4)\n  )\n})"

const rtdal009783Source0013 = "test_that(\"works when there are missing values but no `default`\", {\n  expect_identical(vec_case_when(list(c(TRUE, NA)), list(1)), c(1, NA))\n})"

const rtdal009783Source0014 = "test_that(\"A `NULL` `default` fills in with missing values\", {\n  expect_identical(\n    vec_case_when(list(c(TRUE, FALSE, FALSE)), list(1)),\n    c(1, NA, NA)\n  )\n})"

