const rtdal009783Source0016 = "test_that(\"`default` is initialized correctly in the logical / unspecified case\", {\n  # i.e. `vec_ptype(NA)` is unspecified but the result should be finalized to logical\n  expect_identical(vec_case_when(list(FALSE), list(NA)), NA)\n})"

const rtdal009783Source0017 = "test_that(\"`default` can be vectorized, and is sliced to fit as needed\", {\n  out <- vec_case_when(\n    list(\n      c(FALSE, TRUE, FALSE, TRUE, FALSE),\n      c(FALSE, TRUE, FALSE, FALSE, TRUE)\n    ),\n    list(\n      1:5,\n      6:10\n    ),\n    default = 11:15\n  )\n\n  expect_identical(out, c(11L, 2L, 13L, 4L, 10L))\n})"

