const rtdal009783Source0031 = "test_that(\"0 `conditions` result depends on `size` and `default` and `ptype`\", {\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list()\n    ),\n    unspecified()\n  )\n\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      size = 0\n    ),\n    unspecified()\n  )\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      size = 2\n    ),\n    unspecified(2)\n  )\n\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      default = integer()\n    ),\n    integer()\n  )\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      default = 1L\n    ),\n    integer()\n  )\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      ptype = integer()\n    ),\n    integer()\n  )\n\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      size = 2L,\n      default = 1L\n    ),\n    c(1L, 1L)\n  )\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      size = 2L,\n      default = 1:2\n    ),\n    c(1L, 2L)\n  )\n  expect_identical(\n    vec_case_when(\n      conditions = list(),\n      values = list(),\n      size = 2L,\n      ptype = integer()\n    ),\n    c(NA_integer_, NA_integer_)\n  )\n})"

