const rtdal009783Source0038 = `test_that("named inputs show up in the error message", {
  expect_snapshot(error = TRUE, {
    vec_case_when(list(x = 1.5), list(1))
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(x = 1.5), list(1), conditions_arg = "foo")
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(x = 1.5), list(1), conditions_arg = "")
  })

  expect_snapshot(error = TRUE, {
    vec_case_when(list(x = TRUE, y = c(TRUE, FALSE)), list(1, 2))
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(
      list(x = TRUE, y = c(TRUE, FALSE)),
      list(1, 2),
      conditions_arg = "foo"
    )
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(
      list(x = TRUE, y = c(TRUE, FALSE)),
      list(1, 2),
      conditions_arg = ""
    )
  })

  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE, FALSE), list(1, x = "y"))
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE, FALSE), list(1, x = "y"), values_arg = "foo")
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE, FALSE), list(1, x = "y"), values_arg = "")
  })

  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE), list(NULL))
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE), list(x = NULL))
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE), list(NULL), values_arg = "foo")
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE), list(x = NULL), values_arg = "foo")
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE), list(NULL), values_arg = "")
  })
  expect_snapshot(error = TRUE, {
    vec_case_when(list(TRUE), list(x = NULL), values_arg = "")
  })
})`

const rtdal009783Source0039 = "test_that(\"proof that `ptype` finalization is important\", {\n  # Imagine you have an input logical vector you are remapping\n  # and it happens to only have `NA`s\n  x <- c(NA, NA)\n  conditions <- list(x %in% NA)\n  values <- list(FALSE)\n\n  # If no `ptype` finalization happened, then `ptype = x` would result in\n  # `unspecified` being the output type and these would error. `list_combine()`\n  # now does `ptype` finalization when an explicit `ptype` is provided, so this\n  # works.\n  expect_identical(\n    vec_case_when(conditions, values, default = x, ptype = x),\n    c(FALSE, FALSE)\n  )\n  expect_identical(\n    vec_replace_when(x, conditions, values),\n    c(FALSE, FALSE)\n  )\n})"

const rtdal009783Source0040 = "test_that(\"`unmatched` errors are correct\", {\n  conditions <- list(\n    c(TRUE, FALSE, TRUE, FALSE, FALSE, NA, NA, NA, TRUE),\n    c(FALSE, TRUE, TRUE, FALSE, NA, FALSE, NA, TRUE, NA)\n  )\n  values <- list(\n    1,\n    2\n  )\n  expect_snapshot(error = TRUE, {\n    vec_case_when(conditions, values, unmatched = \"error\")\n  })\n})"

