const rtdal009794Source0001 = `test_that("expands the first column slowest by default", {
  x <- 1:4
  y <- 1:3
  z <- 1:2

  expect_identical(
    vec_expand_grid(x = x, y = y, z = z),
    data_frame(
      x = vec_rep(vec_rep_each(x, times = 6), times = 1),
      y = vec_rep(vec_rep_each(y, times = 2), times = 4),
      z = vec_rep(vec_rep_each(z, times = 1), times = 12)
    )
  )
})`

const rtdal009794Source0002 = "test_that(\"can expand the first column fastest with `.vary`\", {\n  x <- 1:4\n  y <- 1:3\n  z <- 1:2\n\n  expect_identical(\n    vec_expand_grid(x = x, y = y, z = z, .vary = \"fastest\"),\n    data_frame(\n      x = vec_rep(vec_rep_each(x, times = 1), times = 6),\n      y = vec_rep(vec_rep_each(y, times = 4), times = 2),\n      z = vec_rep(vec_rep_each(z, times = 12), times = 1)\n    )\n  )\n})"

const rtdal009794Source0003 = `test_that("size 0 elements force a size 0 result", {
  expect_identical(
    vec_expand_grid(x = 1:3, y = integer(), z = 1:2),
    data_frame(x = integer(), y = integer(), z = integer())
  )

  expect_identical(
    vec_expand_grid(x = integer()),
    data_frame(x = integer())
  )
})`

const rtdal009794Source0004 = "test_that(\"returns 1 row and 0 cols with no input\", {\n  # Because `prod(integer()) == 1L`\n  expect_identical(vec_expand_grid(), data_frame(.size = 1L))\n})"

const rtdal009794Source0005 = "test_that(\"drops `NULL` values\", {\n  expect_identical(\n    vec_expand_grid(NULL, NULL),\n    vec_expand_grid()\n  )\n\n  # And that happens before all names checks\n  expect_identical(\n    vec_expand_grid(x = 1:2, x = NULL, y = 1:3, NULL),\n    vec_expand_grid(x = 1:2, y = 1:3)\n  )\n})"

const rtdal009794Source0006 = `test_that("works with data frame inputs", {
  x <- data_frame(a = 1:2, b = 2:3)
  y <- 1:3

  expect_identical(
    vec_expand_grid(x = x, y = y),
    data_frame(
      x = vec_rep(vec_rep_each(x, times = 3), times = 1),
      y = vec_rep(vec_rep_each(y, times = 1), times = 2),
    )
  )
})`

const rtdal009794Source0007 = "test_that(\"`.name_repair` isn't affected by `.vary`\", {\n  expect <- vec_as_names(c(\"a\", \"b\", \"a\", \"z\"), repair = \"unique_quiet\")\n\n  expect_named(\n    vec_expand_grid(\n      a = 1,\n      b = 2,\n      a = 3,\n      z = 4,\n      .vary = \"slowest\",\n      .name_repair = \"unique_quiet\"\n    ),\n    expect\n  )\n  expect_named(\n    vec_expand_grid(\n      a = 1,\n      b = 2,\n      a = 3,\n      z = 4,\n      .vary = \"fastest\",\n      .name_repair = \"unique_quiet\"\n    ),\n    expect\n  )\n})"

const rtdal009794Source0008 = "test_that(\"can use `.name_repair`\", {\n  expect_identical(\n    vec_expand_grid(a = 1:2, a = 2:3, .name_repair = \"minimal\"),\n    data_frame(\n      a = c(1L, 1L, 2L, 2L),\n      a = c(2L, 3L, 2L, 3L),\n      .name_repair = \"minimal\"\n    )\n  )\n})"

const rtdal009794Source0009 = `test_that("inputs must be named", {
  expect_snapshot(error = TRUE, {
    vec_expand_grid(1)
  })
  expect_snapshot(error = TRUE, {
    vec_expand_grid(x = 1, 2, y = 3)
  })
})`

const rtdal009794Source0010 = `test_that("catches duplicate names by default", {
  expect_snapshot(error = TRUE, {
    vec_expand_grid(a = 1, a = 2)
  })
})`

const rtdal009794Source0011 = `test_that("errors on non vectors and mentions the element name", {
  expect_snapshot(error = TRUE, {
    vec_expand_grid(y = environment())
  })
})`

const rtdal009794Source0012 = "test_that(\"can adjust the `.error_call`\", {\n  my_expand_grid <- function() {\n    vec_expand_grid(x = environment(), .error_call = current_env())\n  }\n\n  expect_snapshot(error = TRUE, {\n    my_expand_grid()\n  })\n})"

const rtdal009794Source0013 = "test_that(\"errors nicely when expansion results in a size larger than `R_len_t`\", {\n  # Windows 32-bit doesn't support long vectors of this size, and the\n  # intermediate `r_ssize` will be too large\n  skip_if(.Machine$sizeof.pointer < 8L, message = \"No long vector support\")\n\n  x <- seq_len((2^31 - 1) / 2)\n  y <- 1:3\n\n  expect_snapshot(error = TRUE, {\n    vec_expand_grid(x = x, y = y)\n  })\n})"

const rtdal009794Source0014 = "test_that(\"errors nicely when expansion results in a size larger than `R_xlen_t`\", {\n  # Windows 32-bit doesn't support long vectors of this size, and the\n  # intermediate `r_ssize` will be too large\n  skip_if(.Machine$sizeof.pointer < 8L, message = \"No long vector support\")\n\n  x <- seq_len(2^31 - 1)\n\n  expect_snapshot(error = TRUE, transform = scrub_internal_error_line_number, {\n    vec_expand_grid(x = x, y = x)\n  })\n})"

const rtdal009794Source0015 = "test_that(\"validates `.vary`\", {\n  expect_snapshot(error = TRUE, {\n    vec_expand_grid(.vary = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    vec_expand_grid(.vary = \"x\")\n  })\n})"

