const rtdal009796Source0001 = `test_that("works with empty input", {
  x <- integer()

  expect_identical(vec_fill_missing(x, direction = "down"), x)
  expect_identical(vec_fill_missing(x, direction = "up"), x)
  expect_identical(vec_fill_missing(x, direction = "downup"), x)
  expect_identical(vec_fill_missing(x, direction = "updown"), x)
  expect_identical(vec_fill_missing(x, direction = "downup", max_fill = 1), x)
  expect_identical(vec_fill_missing(x, direction = "updown", max_fill = 1), x)
})`

const rtdal009796Source0002 = `test_that("works with data frames with rows but no columns", {
  x <- new_data_frame(n = 2L)

  expect_identical(vec_fill_missing(x, direction = "down"), x)
  expect_identical(vec_fill_missing(x, direction = "up"), x)
  expect_identical(vec_fill_missing(x, direction = "downup"), x)
  expect_identical(vec_fill_missing(x, direction = "updown"), x)
  expect_identical(vec_fill_missing(x, direction = "downup", max_fill = 1), x)
  expect_identical(vec_fill_missing(x, direction = "updown", max_fill = 1), x)
})`

const rtdal009796Source0003 = `test_that("vectors with all missing values are left unchanged", {
  x <- c(NA, NA, NA)

  expect_identical(vec_fill_missing(x, direction = "down"), x)
  expect_identical(vec_fill_missing(x, direction = "up"), x)
  expect_identical(vec_fill_missing(x, direction = "downup"), x)
  expect_identical(vec_fill_missing(x, direction = "updown"), x)
  expect_identical(vec_fill_missing(x, direction = "downup", max_fill = 1), x)
  expect_identical(vec_fill_missing(x, direction = "updown", max_fill = 1), x)
})`

const rtdal009796Source0004 = "test_that(\"`NA_real_` and `NaN` are both considered missing\", {\n  expect_identical(\n    vec_fill_missing(c(1, NA_real_, NaN)),\n    c(1, 1, 1)\n  )\n})"

const rtdal009796Source0005 = `test_that("missings are filled correctly", {
  x <- c(NA, 1, NA, 2, NA, NA)

  expect_identical(vec_fill_missing(x, "down"), c(NA, 1, 1, 2, 2, 2))
  expect_identical(vec_fill_missing(x, "up"), c(1, 1, 2, 2, NA, NA))
  expect_identical(vec_fill_missing(x, "downup"), c(1, 1, 1, 2, 2, 2))
  expect_identical(vec_fill_missing(x, "updown"), c(1, 1, 2, 2, 2, 2))
})`

const rtdal009796Source0006 = "test_that(\"`max_fill` limits the sequential fill amount\", {\n  x <- c(NA, NA, 1, NA, NA, NA, 3, NA, NA)\n\n  expect_identical(\n    vec_fill_missing(x, \"down\", max_fill = 1),\n    c(NA, NA, 1, 1, NA, NA, 3, 3, NA)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"downup\", max_fill = 1),\n    c(NA, 1, 1, 1, NA, NA, 3, 3, NA)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"down\", max_fill = 2),\n    c(NA, NA, 1, 1, 1, NA, 3, 3, 3)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"downup\", max_fill = 2),\n    c(1, 1, 1, 1, 1, NA, 3, 3, 3)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"up\", max_fill = 1),\n    c(NA, 1, 1, NA, NA, 3, 3, NA, NA)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"updown\", max_fill = 1),\n    c(NA, 1, 1, NA, NA, 3, 3, 3, NA)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"up\", max_fill = 2),\n    c(1, 1, 1, NA, 3, 3, 3, NA, NA)\n  )\n  expect_identical(\n    vec_fill_missing(x, \"updown\", max_fill = 2),\n    c(1, 1, 1, NA, 3, 3, 3, 3, 3)\n  )\n})"

const rtdal009796Source0007 = `test_that("fills data frames", {
  df <- data_frame(x = c(NA, NA, NA, 2), y = c(NA, 1, NA, 3))

  expect_identical(vec_fill_missing(df, "down"), vec_slice(df, c(1, 2, 2, 4)))
  expect_identical(vec_fill_missing(df, "up"), vec_slice(df, c(2, 2, 4, 4)))
})`

const rtdal009796Source0008 = `test_that("can fill rcrd types", {
  x <- new_rcrd(list(x = c(1, NA, NA), y = c(1, 2, NA)))

  expect_identical(vec_fill_missing(x, "down"), vec_slice(x, c(1, 2, 2)))
  expect_identical(vec_fill_missing(x, "up"), vec_slice(x, c(1, 2, 3)))
  expect_identical(vec_fill_missing(x, "updown"), vec_slice(x, c(1, 2, 2)))
})`

const rtdal009796Source0009 = "test_that(\"validates `direction`\", {\n  expect_error(vec_fill_missing(1, 1), \"`direction` must be one of\")\n  expect_error(vec_fill_missing(1, \"foo\"), \"`direction` must be one of\")\n})"

