const rtdal009799Source0001 = "test_that(\"`condition` must be a condition vector\", {\n  # No scalars\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = lm(1 ~ 1),\n    true = 1,\n    false = 2\n  )\n\n  # No casting\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = 1,\n    true = 1,\n    false = 2\n  )\n\n  # No objects\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = structure(TRUE, class = \"foo\"),\n    true = 1,\n    false = 2\n  )\n\n  # No dim\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = array(TRUE),\n    true = 1,\n    false = 2\n  )\n})"

const rtdal009799Source0002 = "test_that(\"`true`, `false`, and `missing` must be vectors\", {\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = lm(1 ~ 1),\n      false = 2,\n      missing = 0\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = 1,\n      false = lm(1 ~ 1),\n      missing = 0\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = 1,\n      false = 2,\n      missing = lm(1 ~ 1)\n    )\n  })\n})"

const rtdal009799Source0003 = "test_that(\"`true`, `false`, and `missing` must recycle to size of `condition`\", {\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = TRUE,\n    true = c(1, 2),\n    false = 2,\n    missing = 0\n  )\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = TRUE,\n    true = 1,\n    false = c(1, 2),\n    missing = 0\n  )\n  expect_snapshot_vec_if_else(\n    error = TRUE,\n    condition = TRUE,\n    true = 1,\n    false = 2,\n    missing = c(1, 2)\n  )\n})"

const rtdal009799Source0004 = "test_that(\"all combinations of `true`, `false`, and `missing` recycling (including names) are tested\", {\n  # 8 combinations\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1L),\n    false = set_names(7L),\n    missing = set_names(13L),\n    expect = set_names(int(1, 7, 13, 13, 1, 7))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1:6),\n    false = set_names(7L),\n    missing = set_names(13L),\n    expect = set_names(int(1, 7, 13, 13, 5, 7))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1L),\n    false = set_names(7:12),\n    missing = set_names(13L),\n    expect = set_names(int(1, 8, 13, 13, 1, 12))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1L),\n    false = set_names(7L),\n    missing = set_names(13:18),\n    expect = set_names(int(1, 7, 15, 16, 1, 7))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1:6),\n    false = set_names(7:12),\n    missing = set_names(13L),\n    expect = set_names(int(1, 8, 13, 13, 5, 12))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1:6),\n    false = set_names(7L),\n    missing = set_names(13:18),\n    expect = set_names(int(1, 7, 15, 16, 5, 7))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1L),\n    false = set_names(7:12),\n    missing = set_names(13:18),\n    expect = set_names(int(1, 8, 15, 16, 1, 12))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1:6),\n    false = set_names(7:12),\n    missing = set_names(13:18),\n    expect = set_names(int(1, 8, 15, 16, 5, 12))\n  )\n})"

const rtdal009799Source0005 = "test_that(\"not all of `true`, `false`, and `missing` must be named\", {\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = 1L,\n    false = set_names(7L),\n    missing = set_names(13L),\n    expect = set_names(int(1, 7, 13, 13, 1, 7), c(\"\", \"7\", \"13\", \"13\", \"\", \"7\"))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1L),\n    false = 7L,\n    missing = set_names(13L),\n    expect = set_names(int(1, 7, 13, 13, 1, 7), c(\"1\", \"\", \"13\", \"13\", \"1\", \"\"))\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),\n    true = set_names(1L),\n    false = set_names(7L),\n    missing = 13L,\n    expect = set_names(int(1, 7, 13, 13, 1, 7), c(\"1\", \"7\", \"\", \"\", \"1\", \"7\"))\n  )\n})"

const rtdal009799Source0006 = `test_that("names are retained even with casting", {
  expect_named(
    vec_if_else(
      condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),
      true = set_names(1L),
      false = set_names(7L),
      missing = set_names(13L),
      ptype = double()
    ),
    as.character(c(1, 7, 13, 13, 1, 7))
  )

  # Generic
  expect_named(
    vec_if_else(
      condition = c(TRUE, FALSE, NA, NA, TRUE, FALSE),
      true = set_names(new_date(1)),
      false = set_names(new_date(7)),
      missing = set_names(new_date(13)),
      ptype = new_datetime(tzone = "UTC")
    ),
    as.character(new_date(c(1, 7, 13, 13, 1, 7)))
  )
})`

const rtdal009799Source0007 = "test_that(\"`ptype` overrides common type\", {\n  expect_identical(\n    vec_if_else(\n      condition = TRUE,\n      true = 1,\n      false = 2,\n      missing = 0,\n      ptype = integer()\n    ),\n    1L\n  )\n  # Generic\n  expect_identical(\n    vec_if_else(\n      condition = TRUE,\n      true = new_date(0),\n      false = new_date(1),\n      missing = new_date(2),\n      ptype = new_datetime(tzone = \"UTC\")\n    ),\n    new_datetime(0, tzone = \"UTC\")\n  )\n\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = 1.5,\n      false = 2,\n      missing = 0,\n      ptype = integer()\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = 1,\n      false = 2.5,\n      missing = 0,\n      ptype = integer()\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = 1,\n      false = 2,\n      missing = 0.5,\n      ptype = integer()\n    )\n  })\n\n  # Generic\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = 1,\n      false = new_date(2),\n      missing = new_date(0),\n      ptype = new_date()\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = new_date(1),\n      false = 2,\n      missing = new_date(0),\n      ptype = new_date()\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      condition = TRUE,\n      true = new_date(1),\n      false = new_date(2),\n      missing = 0,\n      ptype = new_date()\n    )\n  })\n})"

const rtdal009799Source0008 = "test_that(\"gives expected output with `true` and `false`\", {\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, TRUE),\n    true = c(1, 2, 3),\n    false = c(4, 5, 6),\n    expect = c(1, 5, 3)\n  )\n})"

const rtdal009799Source0009 = "test_that(\"gives expected output with `missing`\", {\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA),\n    true = c(1, 2, 3),\n    false = c(4, 5, 6),\n    expect = c(1, 5, NA)\n  )\n  expect_identical_vec_if_else(\n    condition = c(TRUE, FALSE, NA),\n    true = c(1, 2, 3),\n    false = c(4, 5, 6),\n    missing = c(7, 8, 9),\n    expect = c(1, 5, 9)\n  )\n})"

const rtdal009799Source0010 = `test_that("works with arrays of all types", {
  mat <- as.matrix

  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(lgl(TRUE, FALSE, NA)),
      mat(lgl(FALSE, TRUE, FALSE))
    ),
    mat(lgl(TRUE, TRUE, NA))
  )
  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(int(1, 2, 3)),
      mat(int(4, 5, 6))
    ),
    mat(int(1, 5, 3))
  )
  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(dbl(1, 2, 3)),
      mat(dbl(4, 5, 6))
    ),
    mat(dbl(1, 5, 3))
  )
  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(cpl(1, 2, 3)),
      mat(cpl(4, 5, 6))
    ),
    mat(cpl(1, 5, 3))
  )
  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(as.raw(c(1, 2, 3))),
      mat(as.raw(c(4, 5, 6)))
    ),
    mat(as.raw(c(1, 5, 3)))
  )
  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(chr("1", "2", "3")),
      mat(chr("4", "5", "6"))
    ),
    mat(chr("1", "5", "3"))
  )
  expect_identical(
    vec_if_else(
      c(TRUE, FALSE, TRUE),
      mat(list(1, 2, 3)),
      mat(list(4, 5, 6))
    ),
    mat(list(1, 5, 3))
  )
})`

const rtdal009799Source0011 = `test_that("missing value fall through is right for all atomic types", {
  expect_identical(vec_if_else(NA, TRUE, TRUE), NA)
  expect_identical(vec_if_else(NA, 1L, 1L), NA_integer_)
  expect_identical(vec_if_else(NA, 1, 1), NA_real_)
  expect_identical(
    vec_if_else(NA, cpl(1), cpl(1)),
    complex(real = NA, imaginary = NA)
  )
  expect_identical(vec_if_else(NA, as.raw(1), as.raw(1)), as.raw(0))
  expect_identical(vec_if_else(NA, "1", "1"), NA_character_)
  expect_identical(vec_if_else(NA, list(1), list(1)), list(NULL))
})`

const rtdal009799Source0012 = "test_that(\"extraneous attributes on `true`, `false`, and `missing` are dropped\", {\n  # We do not consider these as part of the `ptype`!\n  expect_identical(\n    vec_if_else(\n      condition = c(TRUE, FALSE, TRUE, NA),\n      true = structure(1:4, foo = \"bar\"),\n      false = structure(5:8, foo = \"bar\"),\n      missing = structure(9:12, foo = \"bar\")\n    ),\n    int(1, 6, 3, 12)\n  )\n})"

const rtdal009799Source0013 = "test_that(\"`ptype` is finalized before being used\", {\n  # Without `vec_ptype_final()`, this could result in `unspecified()` as the `ptype`\n  expect_identical(vec_if_else(TRUE, TRUE, FALSE, ptype = NA), TRUE)\n\n  # We try not to leak <unspecified> when we can help it\n  expect_identical(vec_if_else(TRUE, TRUE, FALSE, ptype = unspecified(1)), TRUE)\n})"

const rtdal009799Source0014 = "test_that(\"`vec_ptype2()`'s `left` is always set\", {\n  # This used to result in `left` being unset, so we'd hit an unreachable state\n  expect_identical(\n    vec_if_else(\n      condition = FALSE,\n      true = TRUE,\n      false = NA,\n      missing = FALSE\n    ),\n    NA\n  )\n})"

const rtdal009799Source0015 = `test_that("scalar true and false are vectorised", {
  x <- c(TRUE, TRUE, FALSE, FALSE)
  expect_equal(vec_if_else(x, 1, 2), c(1, 1, 2, 2))
})`

const rtdal009799Source0016 = `test_that("vector true and false are ok", {
  x <- c(-1, 0, 1)

  expect_equal(vec_if_else(x < 0, x, 0), c(-1, 0, 0))
  expect_equal(vec_if_else(x > 0, x, 0), c(0, 0, 1))
})`

const rtdal009799Source0017 = `test_that("missing values are missing", {
  expect_equal(vec_if_else(c(TRUE, NA, FALSE), -1, 1), c(-1, NA, 1))
})`

const rtdal009799Source0018 = `test_that("works with lists", {
  x <- list(1, 2, 3)

  expect_equal(
    vec_if_else(c(TRUE, TRUE, FALSE), x, list(NULL)),
    list(1, 2, NULL)
  )
})`

const rtdal009799Source0019 = `test_that("works with data frames", {
  true <- tibble(x = 1, y = 2)
  false <- tibble(x = 3, y = 4)

  expect_identical(
    vec_if_else(c(TRUE, FALSE, NA, TRUE), true, false),
    vec_c(true, false, NA, true)
  )
})`

const rtdal009799Source0020 = `test_that("works with vctrs rcrd types", {
  true <- new_rcrd(list(x = 1, y = 2))
  false <- new_rcrd(list(x = 3, y = 4))

  expect_identical(
    vec_if_else(c(TRUE, FALSE, NA, TRUE), true, false),
    vec_c(true, false, NA, true)
  )
})`

const rtdal009799Source0021 = "test_that(\"takes the common type of `true` and `false` (tidyverse/dplyr#6243)\", {\n  expect_identical(vec_if_else(TRUE, 1L, 1.5), 1)\n\n  expect_snapshot(error = TRUE, {\n    vec_if_else(TRUE, 1, \"x\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(\n      TRUE,\n      1,\n      \"x\",\n      true_arg = \"t\",\n      false_arg = \"f\",\n      error_call = current_env()\n    )\n  })\n})"

const rtdal009799Source0022 = "test_that(\"includes `missing` in the common type computation if used\", {\n  expect_identical(vec_if_else(TRUE, 1L, 2L, missing = 3), 1)\n\n  expect_snapshot(error = TRUE, {\n    vec_if_else(TRUE, 1, 2, missing = \"x\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(TRUE, 1L, 2, missing = \"x\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(TRUE, 1, 2L, missing = \"x\")\n  })\n})"

const rtdal009799Source0023 = "test_that(\"can recycle to size 0 `condition`\", {\n  expect_identical(vec_if_else(logical(), 1, 2, missing = 3), double())\n})"

const rtdal009799Source0024 = `test_that("accepts logical conditions with attributes (tidyverse/dplyr#6678)", {
  x <- structure(TRUE, label = "foo")
  expect_identical(vec_if_else(x, 1, 2), 1)
})`

const rtdal009799Source0025 = "test_that(\"`condition` must be logical (and isn't cast to logical!)\", {\n  expect_snapshot(error = TRUE, {\n    vec_if_else(1:10, 1, 2)\n  })\n})"

const rtdal009799Source0026 = "test_that(\"`true`, `false`, and `missing` must recycle to the size of `condition`\", {\n  x <- 1:3\n  bad <- 1:2\n\n  expect_snapshot(error = TRUE, {\n    vec_if_else(x < 2, bad, x)\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(x < 2, x, bad)\n  })\n  expect_snapshot(error = TRUE, {\n    vec_if_else(x < 2, x, x, missing = bad)\n  })\n})"

const rtdal009799Source0027 = `test_that("must have empty dots", {
  expect_snapshot(error = TRUE, {
    vec_if_else(TRUE, 1, 2, missing = 3, 4)
  })
})`

const rtdal009799Source0028 = "test_that(\"`ptype` overrides the common type\", {\n  expect_identical(vec_if_else(TRUE, 2, 1L, ptype = integer()), 2L)\n\n  expect_snapshot(error = TRUE, {\n    vec_if_else(TRUE, 1L, 2.5, ptype = integer())\n  })\n})"

