const rtdal009802Source0001 = "test_that(\"basic `list_combine()` works\", {\n  values <- list(1:2, 3:4)\n  indices <- list(c(4, 1), c(3, 2))\n  size <- 4\n\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    expect = c(2L, 4L, 3L, 1L)\n  )\n})"

const rtdal009802Source0002 = "test_that(\"`list_combine()` works with homogeneous fallback in `default`\", {\n  # This errors\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(foobar(1), 1),\n      indices = list(1, 2),\n      size = 2\n    )\n  })\n\n  # So this should too\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(foobar(1)),\n      indices = list(1),\n      size = 2,\n      default = 1\n    )\n  })\n})"

const rtdal009802Source0003 = "test_that(\"`list_combine()` returns `unspecified` to retain `size` invariant\", {\n  expect_identical(\n    list_combine(list(), indices = list(), size = 0),\n    unspecified()\n  )\n  expect_identical(\n    list_combine(list(), indices = list(), size = 1),\n    unspecified(1)\n  )\n  expect_identical(\n    list_combine(list(), indices = list(), size = 2),\n    unspecified(2)\n  )\n\n  # With only `NULL` elements, still no known `ptype`\n  expect_identical(\n    list_combine(list(NULL), indices = list(integer()), size = 0),\n    unspecified(0)\n  )\n  expect_identical(\n    list_combine(list(NULL), indices = list(integer()), size = 2),\n    unspecified(2)\n  )\n  expect_identical(\n    list_combine(list(NULL), indices = list(1:2), size = 2),\n    unspecified(2)\n  )\n\n  # Now ptype is known\n  expect_identical(\n    list_combine(\n      list(NULL),\n      indices = list(integer()),\n      ptype = numeric(),\n      size = 1\n    ),\n    vec_init(numeric(), n = 1)\n  )\n})"

const rtdal009802Source0004 = "test_that(\"`NULL`s are removed after computing `default`'s index\", {\n  expect_identical_list_combine(\n    x = list(1:2, NULL, 7:8),\n    indices = list(1:2, 5:6, 7:8),\n    size = 8,\n    default = 0L,\n    expect = int(1, 2, 0, 0, NA, NA, 7, 8)\n  )\n})"

const rtdal009802Source0005 = "test_that(\"can combine factors\", {\n  fctr1 <- factor(\"z\")\n  fctr2 <- factor(c(\"x\", \"y\"))\n\n  x <- list(fctr1, fctr2)\n  indices <- list(2, c(3, 1))\n\n  # levels are in the order they are seen!\n  expect <- factor(c(\"y\", \"z\", \"x\"), levels = c(\"z\", \"x\", \"y\"))\n\n  expect_identical(list_combine(x, indices = indices, size = 3), expect)\n\n  # With `default`, the `default` is added in as the last item\n  default <- factor(\"w\")\n  expect <- factor(c(\"y\", \"z\", \"x\"), levels = c(\"z\", \"x\", \"y\", \"w\"))\n  expect_identical(\n    list_combine(x, indices = indices, size = 3, default = default),\n    expect\n  )\n})"

const rtdal009802Source0006 = "test_that(\"preserves names when inputs are cast to a common type (#1689)\", {\n  expect_named(\n    list_combine(\n      list(c(a = 1)),\n      indices = list(1),\n      ptype = integer(),\n      size = 1\n    ),\n    \"a\"\n  )\n  expect_named(\n    list_combine(\n      list(c(a = 1)),\n      indices = list(TRUE),\n      ptype = integer(),\n      size = 1\n    ),\n    \"a\"\n  )\n\n  # With `default`\n  expect_named(\n    list_combine(\n      list(c(a = 1)),\n      indices = list(1),\n      default = c(b = 0),\n      ptype = integer(),\n      size = 2\n    ),\n    c(\"a\", \"b\")\n  )\n  expect_named(\n    list_combine(\n      list(c(a = 1)),\n      indices = list(c(TRUE, FALSE)),\n      default = c(b = 0),\n      ptype = integer(),\n      size = 2\n    ),\n    c(\"a\", \"b\")\n  )\n\n  # With name spec\n  name_spec <- \"{outer}_{inner}\"\n  expect_named(\n    list_combine(\n      list(foo = c(a = 1)),\n      indices = list(1),\n      size = 1,\n      ptype = integer(),\n      name_spec = name_spec\n    ),\n    \"foo_a\"\n  )\n  expect_named(\n    list_combine(\n      list(foo = c(a = 1)),\n      indices = list(1),\n      default = c(b = 0),\n      ptype = integer(),\n      name_spec = name_spec,\n      size = 2\n    ),\n    c(\"foo_a\", \"b\")\n  )\n  expect_named(\n    list_combine(\n      list(foo = c(a = 1)),\n      indices = list(c(TRUE, FALSE)),\n      default = c(b = 0),\n      ptype = integer(),\n      name_spec = name_spec,\n      size = 2\n    ),\n    c(\"foo_a\", \"b\")\n  )\n\n  # When `x` elements are recycled, names are also recycled\n  x <- list(c(a = 1), c(b = 2))\n  expect_named(\n    list_combine(\n      x,\n      indices = list(1:2, 3:4),\n      size = 4,\n      ptype = integer()\n    ),\n    c(\"a\", \"a\", \"b\", \"b\")\n  )\n  expect_named(\n    list_combine(\n      x,\n      indices = list(\n        c(TRUE, TRUE, FALSE, FALSE),\n        c(FALSE, FALSE, TRUE, TRUE)\n      ),\n      size = 4,\n      ptype = integer()\n    ),\n    c(\"a\", \"a\", \"b\", \"b\")\n  )\n\n  # When `default` elements are recycled, names are also recycled\n  expect_named(\n    list_combine(\n      list(c(a = 1), c(b = 2)),\n      indices = list(1, 3),\n      default = c(c = 0),\n      ptype = integer(),\n      size = 4\n    ),\n    c(\"a\", \"c\", \"b\", \"c\")\n  )\n  expect_named(\n    list_combine(\n      list(c(a = 1), c(b = 2)),\n      indices = list(\n        c(TRUE, FALSE, FALSE, FALSE),\n        c(FALSE, FALSE, TRUE, FALSE)\n      ),\n      default = c(c = 0),\n      ptype = integer(),\n      size = 4\n    ),\n    c(\"a\", \"c\", \"b\", \"c\")\n  )\n})"

const rtdal009802Source0007 = `test_that("not all inputs have to be named", {
  x <- list(c(a = 1), 2, c(c = 3))
  indices <- list(2, 1, 3)

  expect_identical_list_combine(
    x = x,
    indices = indices,
    size = 3,
    expect = set_names(c(2, 1, 3), c("", "a", "c"))
  )
  expect_identical_list_combine(
    x = x,
    indices = indices,
    size = 4,
    default = 0,
    expect = set_names(c(2, 1, 3, 0), c("", "a", "c", ""))
  )
})`

const rtdal009802Source0008 = `test_that("list_combine() keeps data frame row names", {
  df1 <- data.frame(x = 1:2, row.names = c("r1", "r2"))
  df2 <- data.frame(x = 3:4, row.names = c("r3", "r4"))
  x <- list(df1, df2)
  indices <- list(c(3, 1), c(2, 4))

  result <- list_combine(x, indices = indices, size = sum(lengths(indices)))
  expect <- c("r2", "r3", "r1", "r4")
  expect_identical(vec_names(result), expect)

  default <- data.frame(x = 0L, row.names = "d")
  result <- list_combine(x, indices = indices, size = 5, default = default)
  expect <- c("r2", "r3", "r1", "r4", "d")
  expect_identical(vec_names(result), expect)

  # With casting
  ptype <- data.frame(x = double())
  default <- data.frame(x = 0L, row.names = "d")
  result <- list_combine(
    x = x,
    indices = indices,
    size = 5,
    default = default,
    ptype = ptype
  )
  expect <- c("r2", "r3", "r1", "r4", "d")
  expect_identical(vec_names(result), expect)
  expect_type(result$x, "double")
})`

const rtdal009802Source0009 = `test_that("df-col row names are repaired silently", {
  df1 <- data_frame(x = new_data_frame(list(a = 1), row.names = "inner"))
  df2 <- data_frame(x = new_data_frame(list(a = 2), row.names = "inner"))
  x <- list(df1, df2)
  indices <- list(1, 2)
  expect_silent({
    result <- list_combine(x, indices = indices, size = 2)
  })
  expect_identical(vec_names(result$x), c("inner...1", "inner...2"))

  default <- data_frame(x = new_data_frame(list(a = 0), row.names = "inner"))
  expect_silent({
    result <- list_combine(x, indices = indices, size = 3, default = default)
  })
  expect_identical(
    vec_names(result$x),
    c("inner...1", "inner...2", "inner...3")
  )
})`

const rtdal009802Source0010 = "test_that(\"name repair is respected and happens after ordering according to `indices`\", {\n  local_name_repair_quiet()\n\n  x <- list(c(a = 1), c(a = 2))\n\n  indices <- list(2, 1)\n  expect_named(list_combine(x, indices = indices, size = 2), c(\"a\", \"a\"))\n  expect_named(\n    list_combine(x, indices = indices, size = 2, name_repair = \"unique\"),\n    c(\"a...1\", \"a...2\")\n  )\n\n  # With `default`\n  indices <- list(3, 1)\n  default <- c(a = 0)\n  expect_named(\n    list_combine(x, indices = indices, size = 3, default = default),\n    c(\"a\", \"a\", \"a\")\n  )\n  expect_named(\n    list_combine(\n      x,\n      indices = indices,\n      size = 3,\n      default = default,\n      name_repair = \"unique\"\n    ),\n    c(\"a...1\", \"a...2\", \"a...3\")\n  )\n})"

const rtdal009802Source0011 = "test_that(\"list_combine() works with simple homogeneous foreign S3 classes\", {\n  expect_identical(\n    list_combine(\n      list(foobar(1), foobar(2)),\n      indices = list(1, 2),\n      size = 2\n    ),\n    vec_c(foobar(c(1, 2)))\n  )\n\n  # With `default`\n  expect_identical(\n    list_combine(\n      list(foobar(1), foobar(2)),\n      indices = list(3, 1),\n      size = 4,\n      default = foobar(0)\n    ),\n    vec_c(foobar(c(2, 0, 1, 0)))\n  )\n})"

const rtdal009802Source0012 = "test_that(\"list_combine() fails with complex foreign S3 classes\", {\n  expect_snapshot(error = TRUE, {\n    x <- structure(foobar(1), attr_foo = \"foo\")\n    y <- structure(foobar(2), attr_bar = \"bar\")\n    list_combine(list(x, y), indices = list(1, 2), size = 2)\n  })\n  expect_snapshot(error = TRUE, {\n    x <- structure(foobar(1), attr_foo = \"foo\")\n    y <- structure(foobar(2), attr_bar = \"bar\")\n    list_combine(\n      list(x, y),\n      indices = list(1, 2),\n      size = 2,\n      error_call = call(\"foo\"),\n      x_arg = \"arg\"\n    )\n  })\n\n  # Want this to mention `default` by name\n  expect_snapshot(error = TRUE, {\n    x <- structure(foobar(1), attr_foo = \"foo\")\n    default <- structure(foobar(2), attr_foo = \"bar\")\n    list_combine(\n      list(x),\n      indices = list(1),\n      size = 2,\n      default = default\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    x <- structure(foobar(1), attr_foo = \"foo\")\n    default <- structure(foobar(2), attr_foo = \"bar\")\n    list_combine(\n      list(x),\n      indices = list(1),\n      size = 2,\n      default = default,\n      default_arg = \"d\"\n    )\n  })\n})"

const rtdal009802Source0013 = `test_that("list_combine() fails with complex foreign S4 classes", {
  expect_snapshot({
    joe <- .Counts(c(1L, 2L), name = "Joe")
    jane <- .Counts(3L, name = "Jane")
    (expect_error(
      list_combine(list(joe, jane), indices = list(1:2, 3), size = 3),
      class = "vctrs_error_incompatible_type"
    ))
    (expect_error(
      list_combine(
        list(joe, jane),
        indices = list(1:2, 3),
        size = 3,
        error_call = call("foo"),
        x_arg = "arg"
      ),
      class = "vctrs_error_incompatible_type"
    ))
  })
})`

const rtdal009802Source0014 = "test_that(\"list_combine() falls back to c() if S3 method is available\", {\n  # Check off-by-one error\n  expect_error(\n    list_combine(\n      list(foobar(1), \"\", foobar(2)),\n      indices = list(1, 2, 3),\n      size = 3\n    ),\n    class = \"vctrs_error_incompatible_type\"\n  )\n\n  # Fallback when the class implements `c()`\n  method_foobar <- function(...) {\n    xs <- list(...)\n    xs <- map(xs, unclass)\n    res <- exec(\"c\", !!!xs)\n    foobar(res)\n  }\n\n  local_methods(\n    c.vctrs_foobar = method_foobar\n  )\n  expect_identical(\n    list_combine(list(foobar(1), foobar(2)), indices = list(1, 2), size = 2),\n    foobar(c(1, 2))\n  )\n  expect_identical(\n    list_combine(list(foobar(1), foobar(2)), indices = list(2, 1), size = 2),\n    foobar(c(2, 1))\n  )\n  expect_identical(\n    list_combine(\n      list(NULL, foobar(1), NULL, foobar(2)),\n      indices = list(integer(), 1, integer(), 2),\n      size = 2\n    ),\n    foobar(c(1, 2))\n  )\n\n  # OOB error is respected\n  expect_error(\n    list_combine(\n      list(foobar(1), foobar(2)),\n      indices = list(1, 3),\n      size = 2\n    ),\n    class = \"vctrs_error_subscript_oob\"\n  )\n\n  # Unassigned locations results in missing values.\n  # Repeated assignment uses the last assigned value.\n  expect_identical(\n    list_combine(\n      list(foobar(c(1, 2)), foobar(3)),\n      indices = list(c(1, 3), 1),\n      size = 3\n    ),\n    foobar(c(3, NA, 2))\n  )\n  expect_identical(\n    list_combine(\n      list(foobar(c(1, 2)), foobar(3)),\n      indices = list(c(2, NA), NA),\n      size = 3\n    ),\n    foobar(c(NA, 1, NA))\n  )\n\n  # Respects `default`\n  expect_identical(\n    list_combine(\n      list(foobar(c(1, 2)), foobar(3)),\n      indices = list(c(1, 3), 1),\n      default = foobar(0),\n      size = 4\n    ),\n    foobar(c(3, 0, 2, 0))\n  )\n  expect_identical(\n    list_combine(\n      list(foobar(c(1, 2)), foobar(3)),\n      indices = list(c(1, 3), 1),\n      default = foobar(c(4, 5, 6, 7)),\n      size = 4\n    ),\n    foobar(c(3, 5, 2, 7))\n  )\n\n  # Names are kept\n  expect_identical(\n    list_combine(\n      list(foobar(c(x = 1, y = 2)), foobar(c(x = 1))),\n      indices = list(c(2, 1), 3),\n      size = 3\n    ),\n    foobar(c(y = 2, x = 1, x = 1))\n  )\n  expect_identical(\n    list_combine(\n      list(foobar(c(x = 1, y = 2)), foobar(c(x = 1))),\n      indices = list(c(2, 1), 3),\n      size = 5,\n      default = foobar(c(default = 0))\n    ),\n    foobar(c(y = 2, x = 1, x = 1, default = 0, default = 0))\n  )\n\n  # Recycles to the size of index\n  expect_identical(\n    list_combine(\n      list(foobar(1), foobar(2)),\n      indices = list(c(1, 3), 2),\n      size = 3\n    ),\n    foobar(c(1, 2, 1))\n  )\n  expect_identical(\n    list_combine(\n      list(foobar(1), foobar(2)),\n      indices = list(c(1, 2), integer()),\n      size = 2\n    ),\n    foobar(c(1, 1))\n  )\n  expect_snapshot({\n    (expect_error(\n      list_combine(\n        list(foobar(1), foobar(2)),\n        indices = list(c(1, 3), integer()),\n        size = 2\n      ),\n      class = \"vctrs_error_subscript_oob\"\n    ))\n  })\n  expect_snapshot({\n    x <- list(foobar(1:2))\n    indices <- list(1:3)\n    (expect_error(list_combine(x, indices = indices, size = 3)))\n    (expect_error(list_combine(\n      x,\n      indices = indices,\n      size = 3,\n      x_arg = \"arg\",\n      error_call = call(\"foo\")\n    )))\n  })\n\n  method_vctrs_c_fallback <- function(...) {\n    xs <- list(...)\n    xs <- map(xs, unclass)\n    res <- exec(\"c\", !!!xs)\n    structure(res, class = \"vctrs_c_fallback\")\n  }\n\n  # Registered fallback\n  s3_register(\"base::c\", \"vctrs_c_fallback\", method_vctrs_c_fallback)\n  expect_identical(\n    list_combine(\n      list(\n        structure(1, class = \"vctrs_c_fallback\"),\n        structure(2, class = \"vctrs_c_fallback\")\n      ),\n      indices = list(2, 1),\n      size = 2\n    ),\n    structure(c(2, 1), class = \"vctrs_c_fallback\")\n  )\n\n  # Don't fallback for S3 lists which are treated as scalars by default\n  expect_error(\n    list_combine(\n      list(foobar(list(1)), foobar(list(2))),\n      indices = list(1, 2),\n      size = 2\n    ),\n    class = \"vctrs_error_scalar_type\"\n  )\n})"

const rtdal009802Source0015 = "test_that(\"list_combine() falls back to c() if S3 method is available and respects `default`\", {\n  # Fallback when the class implements `c()`\n  method_foobar <- function(...) {\n    xs <- list(...)\n    xs <- map(xs, unclass)\n    res <- exec(\"c\", !!!xs)\n    foobar(res)\n  }\n\n  local_methods(\n    c.vctrs_foobar = method_foobar\n  )\n\n  # Respects `default`\n  expect_identical(\n    list_combine(\n      list(foobar(c(1, 2)), foobar(3)),\n      indices = list(c(1, 3), 1),\n      default = foobar(0),\n      size = 4\n    ),\n    foobar(c(3, 0, 2, 0))\n  )\n  expect_identical(\n    list_combine(\n      list(foobar(c(1, 2)), foobar(3)),\n      indices = list(c(1, 3), 1),\n      default = foobar(c(4, 5, 6, 7)),\n      size = 4\n    ),\n    foobar(c(3, 5, 2, 7))\n  )\n\n  # Names are kept\n  expect_identical(\n    list_combine(\n      list(foobar(c(x = 1, y = 2)), foobar(c(x = 1))),\n      indices = list(c(2, 1), 3),\n      size = 3\n    ),\n    foobar(c(y = 2, x = 1, x = 1))\n  )\n  expect_identical(\n    list_combine(\n      list(foobar(c(x = 1, y = 2)), foobar(c(x = 1))),\n      indices = list(c(2, 1), 3),\n      size = 5,\n      default = foobar(c(default = 0))\n    ),\n    foobar(c(y = 2, x = 1, x = 1, default = 0, default = 0))\n  )\n})"

const rtdal009802Source0016 = "test_that(\"list_combine() falls back for S4 classes with a registered c() method\", {\n  joe <- .Counts(c(1L, 2L), name = \"Joe\")\n  jane <- .Counts(3L, name = \"Jane\")\n  expect_snapshot({\n    (expect_error(\n      list_combine(list(joe, 1, jane), indices = list(c(1, 2), 3, 4), size = 4),\n      class = \"vctrs_error_incompatible_type\"\n    ))\n  })\n  local_c_counts()\n  expect_identical(\n    list_combine(list(joe, jane), indices = list(c(1, 3), 2), size = 3),\n    .Counts(c(1L, 3L, 2L), name = \"Dispatched\")\n  )\n  expect_identical(\n    list_combine(\n      list(NULL, joe, jane),\n      indices = list(integer(), c(1, 3), 2),\n      size = 3\n    ),\n    .Counts(c(1L, 3L, 2L), name = \"Dispatched\")\n  )\n  # Unassigned locations results in missing values.\n  # Repeated assignment uses the last assigned value.\n  expect_identical(\n    list_combine(list(joe, jane), indices = list(c(1, 3), 1), size = 3),\n    .Counts(c(3L, NA, 2L), name = \"Dispatched\")\n  )\n  expect_identical(\n    list_combine(list(joe, jane), indices = list(c(2, NA), NA), size = 3),\n    .Counts(c(NA, 1L, NA), name = \"Dispatched\")\n  )\n\n  # `default` is respected\n  default <- .Counts(0L, name = \"Unknown\")\n\n  expect_identical(\n    list_combine(\n      list(joe, jane),\n      indices = list(c(1, 3), 1),\n      default = default,\n      size = 5\n    ),\n    .Counts(c(3L, 0L, 2L, 0L, 0L), name = \"Dispatched\")\n  )\n})"

const rtdal009802Source0017 = "test_that(\"can ignore names in `list_combine()` by providing a `zap()` name-spec (#232)\", {\n  expect_snapshot({\n    (expect_error(\n      list_combine(\n        list(a = c(b = 1:2)),\n        indices = list(1:2),\n        size = 2\n      )\n    ))\n    (expect_error(\n      list_combine(\n        list(a = c(b = 1:2)),\n        indices = list(1:2),\n        size = 2,\n        error_call = call(\"foo\")\n      )\n    ))\n  })\n\n  expect_identical(\n    list_combine(\n      list(a = c(b = 1:2), b = 3L),\n      indices = list(1:2, 3),\n      size = 3,\n      name_spec = zap()\n    ),\n    1:3\n  )\n  expect_identical(\n    list_combine(\n      list(a = c(foo = 1:2), b = c(bar = 3L)),\n      indices = list(2:1, 3),\n      size = 3,\n      name_spec = zap()\n    ),\n    c(2L, 1L, 3L)\n  )\n  expect_identical(\n    list_combine(\n      list(a = c(foo = 1:2), b = c(bar = 3L)),\n      indices = list(2:1, 3),\n      default = c(baz = 0L),\n      size = 4,\n      name_spec = zap()\n    ),\n    c(2L, 1L, 3L, 0L)\n  )\n\n  expect_snapshot({\n    x <- list(a = c(b = c(\"a\", \"b\")), b = 3L)\n    (expect_error(\n      list_combine(\n        x,\n        indices = list(1:2, 3),\n        size = 3,\n        name_spec = zap()\n      ),\n      class = \"vctrs_error_incompatible_type\"\n    ))\n\n    x <- list(a = c(foo = 1:2), b = c(bar = \"\"))\n    (expect_error(\n      list_combine(\n        x,\n        indices = list(2:1, 3),\n        size = 3,\n        name_spec = zap()\n      ),\n      class = \"vctrs_error_incompatible_type\"\n    ))\n  })\n})"

const rtdal009802Source0018 = `test_that("list_combine() falls back to c() methods (#1120)", {
  expect_error(
    list_combine(
      list(foobar(1), foobar(2, class = "foo")),
      indices = list(1, 2),
      size = 2
    ),
    class = "vctrs_error_incompatible_type"
  )
  local_methods(
    c.vctrs_foobar = function(...) {
      out <- NextMethod()
      paste0(rep_along(out, "dispatched"), seq_along(out))
    }
  )
  # Homogeneous subclasses
  xs <- list(foobar(1), foobar(2, class = "foo"))
  expect_identical(
    list_combine(xs, indices = list(2, 1), size = 2),
    c("dispatched2", "dispatched1")
  )
  expect_identical(
    list_combine(xs, indices = list(3, 1), size = 4, default = foobar(0)),
    c("dispatched2", "dispatched3", "dispatched1", "dispatched4")
  )

  # Different subclasses
  xs <- list(
    foobar(c(x = 1, y = 2), class = "foo"),
    foobar(c(x = 1), foo = 1)
  )
  expect_identical(
    list_combine(xs, indices = list(c(2, 1), 3), size = 3),
    c("dispatched2", "dispatched1", "dispatched3")
  )
  expect_identical(
    list_combine(xs, indices = list(c(4, 1), 3), size = 5, default = foobar(0)),
    c("dispatched2", "dispatched4", "dispatched3", "dispatched1", "dispatched5")
  )
})`

