const rtdal009802Source0026 = "test_that(\"`...` must be empty\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(list(1, 2), indices = list(1, 2), size = 2, \"foo\")\n  })\n})"

const rtdal009802Source0027 = "test_that(\"list_combine() `default` is inserted correctly\", {\n  xs <- list(\"a\", \"b\")\n  indices <- list(1, 3)\n\n  expect_identical_list_combine(\n    x = xs,\n    indices = indices,\n    size = 4,\n    default = \"c\",\n    expect = c(\"a\", \"c\", \"b\", \"c\")\n  )\n})"

const rtdal009802Source0028 = "test_that(\"list_combine() `default` is inserted correctly with data frames\", {\n  xs <- list(\n    data.frame(a = 1:2, b = 1:2),\n    data.frame(a = 3L, b = 3L)\n  )\n  indices <- list(1:2, 5)\n\n  expect_identical(\n    list_combine(\n      x = xs,\n      indices = indices,\n      size = 6,\n      default = data.frame(a = 0L, b = NA_integer_)\n    ),\n    data.frame(\n      a = int(1, 2, 0, 0, 3, 0),\n      b = int(1, 2, NA, NA, 3, NA)\n    )\n  )\n})"

const rtdal009802Source0029 = "test_that(\"list_combine() `default` is inserted correctly when there are duplicate indices\", {\n  xs <- list(\"a\", \"b\", \"c\")\n  indices <- list(1, 1, 3)\n\n  expect_identical_list_combine(\n    x = xs,\n    indices = indices,\n    size = 4,\n    default = \"d\",\n    expect = c(\"b\", \"d\", \"c\", \"d\")\n  )\n})"

const rtdal009802Source0030 = "test_that(\"list_combine() `default` is inserted correctly when it is the size of `size`\", {\n  xs <- list(\"2\", \"4\")\n  indices <- list(2, 4)\n\n  default <- letters[1:5]\n\n  expect_identical_list_combine(\n    x = xs,\n    indices = indices,\n    size = 5,\n    default = default,\n    expect = c(\"a\", \"2\", \"c\", \"4\", \"e\")\n  )\n})"

const rtdal009802Source0031 = "test_that(\"list_combine() `default` is correctly not used when all spots are filled\", {\n  xs <- list(\"a\", \"b\", \"c\")\n  indices <- list(1, 2, 3)\n\n  expect_identical_list_combine(\n    x = xs,\n    indices = indices,\n    size = 3,\n    default = \"d\",\n    expect = c(\"a\", \"b\", \"c\")\n  )\n})"

const rtdal009802Source0032 = "test_that(\"list_combine() `default` names work correctly with `name_spec`\", {\n  xs <- list(x = c(a = \"a\"), y = c(b = \"b\"), z = c(c = \"c\"))\n  indices <- list(1, 3, NA)\n\n  expect_identical(\n    list_combine(\n      xs,\n      indices = indices,\n      size = 5,\n      default = c(d = \"d\"),\n      name_spec = \"{outer}_{inner}\"\n    ),\n    c(x_a = \"a\", d = \"d\", y_b = \"b\", d = \"d\", d = \"d\")\n  )\n})"

const rtdal009802Source0033 = "test_that(\"list_combine() `size` type is validated\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(list(1), indices = list(1), size = \"x\")\n  })\n})"

const rtdal009802Source0034 = "test_that(\"list_combine() `indices` are validated against `size`\", {\n  # TODO: Not the best error message here\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1),\n    indices = list(3),\n    size = 2\n  )\n})"

const rtdal009802Source0035 = "test_that(\"list_combine() `default` vector check is done\", {\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1),\n    indices = list(1),\n    size = 1,\n    default = lm(1 ~ 1),\n    default_arg = \"d\"\n  )\n})"

const rtdal009802Source0036 = "test_that(\"list_combine() `default` size check is done\", {\n  # Must be size 1, or same size as `size`\n  expect_identical_list_combine(\n    x = list(1),\n    indices = list(2),\n    size = 3,\n    default = 0,\n    default_arg = \"d\",\n    expect = c(0, 1, 0)\n  )\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1L),\n    indices = list(1),\n    size = 1,\n    default = 1:2,\n    default_arg = \"d\"\n  )\n})"

const rtdal009802Source0037 = "test_that(\"list_combine() `default` is taken into account when computing `ptype`\", {\n  expect_identical(\n    list_combine(\n      list(1L),\n      indices = list(1),\n      size = 2,\n      default = 1.5,\n      default_arg = \"d\"\n    ),\n    c(1, 1.5)\n  )\n\n  # `default` is not in output, but helps determine output type!\n  expect_identical(\n    list_combine(\n      list(1L),\n      indices = list(1),\n      size = 1,\n      default = 1.5,\n      default_arg = \"d\"\n    ),\n    1\n  )\n\n  # Empty `xs` and `indices`, but `default` is provided and determines type,\n  # which would otherwise be <unspecified>\n  expect_identical_list_combine(\n    x = list(),\n    indices = list(),\n    size = 2,\n    default = 0,\n    default_arg = \"d\",\n    expect = c(0, 0)\n  )\n\n  # Computed `ptype` among `xs` isn't compatible with `default`\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(x = 1),\n      indices = list(1),\n      size = 2,\n      default = \"a\",\n      default_arg = \"d\"\n    )\n  })\n\n  # Provided `ptype` isn't compatible with `default`\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(x = 1L),\n      indices = list(1),\n      size = 2,\n      default = 1.5,\n      default_arg = \"d\",\n      ptype = integer()\n    )\n  })\n})"

const rtdal009802Source0038 = "test_that(\"list_combine() works with data frame `default` with fallback columns\", {\n  x <- list(\n    data_frame(a = foobar(1:2), b = 3:4, c = foobar(5:6)),\n    data_frame(a = foobar(3L), b = 5L, c = foobar(7L))\n  )\n  indices <- list(\n    c(3, NA),\n    2\n  )\n  default <- data_frame(a = foobar(0L), b = 0L, c = foobar(-1L))\n\n  expect_identical(\n    list_combine(\n      x = x,\n      indices = indices,\n      size = 5,\n      default = default\n    ),\n    data_frame(\n      a = foobar(int(0, 3, 1, 0, 0)),\n      b = int(0, 5, 3, 0, 0),\n      c = foobar(int(-1, 7, 5, -1, -1))\n    )\n  )\n\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = x,\n        indices = indices,\n        size = 5,\n        default = default\n      ),\n      data_frame(\n        a = foobar_c(int(0, 3, 1, 0, 0)),\n        b = int(0, 5, 3, 0, 0),\n        c = foobar_c(int(-1, 7, 5, -1, -1))\n      )\n    )\n  })\n})"

const rtdal009802Source0039 = "test_that(\"list_combine() `unmatched = 'error'` doesn't error when all locations are covered\", {\n  expect_identical_list_combine(\n    x = list(1:3),\n    indices = list(1:3),\n    size = 3,\n    unmatched = \"error\",\n    expect = 1:3\n  )\n  expect_identical_list_combine(\n    x = list(1:3),\n    indices = list(c(TRUE, TRUE, TRUE)),\n    size = 3,\n    unmatched = \"error\",\n    expect = 1:3\n  )\n})"

const rtdal009802Source0040 = "test_that(\"list_combine() `unmatched = 'error'` doesn't error in the empty case\", {\n  expect_identical(\n    list_combine(list(), indices = list(), size = 0, unmatched = \"error\"),\n    unspecified()\n  )\n})"

const rtdal009802Source0041 = "test_that(\"list_combine() `unmatched = 'error'` errors with unmatched `indices` when `size` is used\", {\n  expect_snapshot(error = TRUE, {\n    # Duplicates result in unmatched locations\n    list_combine(\n      list(1, 1),\n      indices = list(1, 1),\n      size = 2,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    # `NA` results in unmatched locations\n    list_combine(\n      list(1, 1),\n      indices = list(1, NA),\n      size = 2,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    # `NA` results in unmatched locations\n    list_combine(\n      list(1:9, 1:9),\n      indices = list(\n        c(TRUE, FALSE, NA, TRUE, FALSE, NA, TRUE, FALSE, NA),\n        c(TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, NA, NA, NA)\n      ),\n      size = 9,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    # Unused location\n    list_combine(\n      list(1, 3),\n      indices = list(1, 3),\n      size = 3,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    # Unused location\n    list_combine(\n      list(1, 1),\n      indices = list(c(TRUE, FALSE), c(TRUE, FALSE)),\n      size = 2,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(),\n      indices = list(),\n      size = 2,\n      unmatched = \"error\"\n    )\n  })\n})"

const rtdal009802Source0042 = "test_that(\"list_combine() `unmatched = 'error'` errors pluralize correctly\", {\n  expect_snapshot(error = TRUE, {\n    # One location\n    list_combine(\n      list(1, 3),\n      indices = list(1, 3),\n      size = 3,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    # Two locations\n    list_combine(\n      list(1, 3),\n      indices = list(1, 3),\n      size = 4,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    # Many locations\n    list_combine(\n      list(1, 3),\n      indices = list(1, 3),\n      size = 100,\n      unmatched = \"error\"\n    )\n  })\n})"

const rtdal009802Source0043 = "test_that(\"list_combine() `unmatched = 'error'` error classes are as expected\", {\n  cnd <- catch_cnd(list_combine(\n    list(1, 3),\n    indices = list(1, 3),\n    size = 3,\n    unmatched = \"error\"\n  ))\n  expect_true(inherits_all(\n    cnd,\n    c(\"vctrs_error_combine_unmatched\", \"vctrs_error_combine\")\n  ))\n})"

const rtdal009802Source0044 = "test_that(\"list_combine() `unmatched = 'error'` can't be set when `default` is also set\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      default = 1,\n      size = 1,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      default = 1,\n      size = 1,\n      unmatched = \"error\",\n      default_arg = \".default\",\n      error_call = quote(foo())\n    )\n  })\n})"

const rtdal009802Source0045 = "test_that(\"list_combine() `unmatched` is validated\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      unmatched = \"e\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      unmatched = c(\"a\", \"b\")\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      unmatched = NA_character_\n    )\n  })\n\n  # With error call\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      unmatched = \"e\",\n      error_call = quote(foo())\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      unmatched = c(\"a\", \"b\"),\n      error_call = quote(foo())\n    )\n  })\n})"

const rtdal009802Source0046 = "test_that(\"list_combine() `multiple` is validated\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      multiple = \"a\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      multiple = c(\"a\", \"b\")\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      multiple = NA_character_\n    )\n  })\n\n  # With error call\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      multiple = \"a\",\n      error_call = quote(foo())\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      list(1),\n      indices = list(1),\n      size = 1,\n      multiple = c(\"a\", \"b\"),\n      error_call = quote(foo())\n    )\n  })\n})"

const rtdal009802Source0047 = "test_that(\"`NA` indices are considered unmatched locations\", {\n  # The `NA` index is considered \"unmatched\". It's the same as providing a\n  # logical index with an `NA` in it, like indices in this case of: list(c(TRUE,\n  # FALSE, FALSE), c(FALSE, NA, TRUE)) We consider that `NA` to be unmatched,\n  # and running vec_as_location on that gives the same index as this.\n  expect_identical_list_combine(\n    x = list(1L, 2:3),\n    indices = list(1, c(NA, 3)),\n    size = 3,\n    default = 0L,\n    expect = c(1L, 0L, 3L)\n  )\n  expect_identical_list_combine(\n    x = list(1L, 2:3),\n    indices = list(c(TRUE, FALSE, FALSE), c(FALSE, NA, TRUE)),\n    size = 3,\n    default = 0L,\n    expect = c(1L, 0L, 3L)\n  )\n\n  # Which means this errors\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      x = list(1, 2:3),\n      indices = list(1, c(NA, 3)),\n      size = 3,\n      unmatched = \"error\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      x = list(1, 2:3),\n      indices = list(c(TRUE, FALSE, FALSE), c(FALSE, NA, TRUE)),\n      size = 3,\n      unmatched = \"error\"\n    )\n  })\n})"

const rtdal009802Source0048 = "test_that(\"`indices` corresponding to `NULL` values are considered matched\", {\n  # These are considered \"matched\" but there is nothing to put there,\n  # so `NA` ends up in the slot\n  expect_identical_list_combine(\n    x = list(1, NULL),\n    indices = list(1, c(2, 3)),\n    size = 3,\n    default = 0,\n    expect = c(1, NA, NA)\n  )\n  expect_identical_list_combine(\n    x = list(1, NULL),\n    indices = list(c(TRUE, FALSE, FALSE), c(FALSE, TRUE, TRUE)),\n    size = 3,\n    default = 0,\n    expect = c(1, NA, NA)\n  )\n\n  # Which means this is not an error\n  expect_identical_list_combine(\n    x = list(1, NULL),\n    indices = list(1, c(2, 3)),\n    size = 3,\n    unmatched = \"error\",\n    expect = c(1, NA, NA)\n  )\n  expect_identical_list_combine(\n    x = list(1, NULL),\n    indices = list(c(TRUE, FALSE, FALSE), c(FALSE, TRUE, TRUE)),\n    size = 3,\n    unmatched = \"error\",\n    expect = c(1, NA, NA)\n  )\n})"

const rtdal009802Source0049 = "test_that(\"`x` must be a list\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(1, indices = list(1), size = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(\n      1,\n      indices = list(1),\n      size = 1,\n      error_call = call(\"foo\"),\n      x_arg = \"arg\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(data.frame(x = 1), indices = list(1), size = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(array(list(1)), indices = list(1), size = 1)\n  })\n})"

const rtdal009802Source0050 = "test_that(\"`indices` must be a list\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(list(1), indices = 1, size = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(list(1), indices = 1, size = 1, error_call = call(\"foo\"))\n  })\n  expect_snapshot(error = TRUE, {\n    list_combine(list(1), indices = data.frame(x = 1), size = 1)\n  })\n})"

const rtdal009802Source0051 = "test_that(\"`indices` has a restricted type\", {\n  expect_error(\n    list_combine(list(1), indices = list(\"x\"), size = 1),\n    class = \"vctrs_error_subscript_type\"\n  )\n  expect_error(\n    list_combine(list(1), indices = list(quote(name)), size = 1),\n    class = \"vctrs_error_subscript_type\"\n  )\n})"

const rtdal009802Source0052 = "test_that(\"`x` and `indices` must be lists of the same size\", {\n  expect_snapshot(error = TRUE, {\n    list_combine(list(1, 2), indices = list(1), size = 1)\n  })\n})"

const rtdal009802Source0053 = `test_that("can combine with an AsIs list (#1463)", {
  x <- I(list(1, 2))
  expect_identical(list_combine(x, indices = list(1, 2), size = 2), c(1, 2))
})`

