const rtdal009802Source0076 = "test_that(\"preserves names when inputs are cast to a common type (#1689)\", {\n  expect_named(\n    list_combine(\n      list(c(a = 1)),\n      indices = list(1),\n      size = 1,\n      ptype = integer()\n    ),\n    \"a\"\n  )\n\n  # With `default`\n  expect_named(\n    list_combine(\n      list(c(a = 1)),\n      indices = list(1),\n      default = c(b = 0),\n      ptype = integer(),\n      size = 2\n    ),\n    c(\"a\", \"b\")\n  )\n\n  # With name spec\n  name_spec <- \"{outer}_{inner}\"\n  expect_named(\n    list_combine(\n      list(foo = c(a = 1)),\n      ptype = integer(),\n      name_spec = name_spec,\n      indices = list(1),\n      size = 1\n    ),\n    \"foo_a\"\n  )\n  expect_named(\n    list_combine(\n      list(foo = c(a = 1)),\n      indices = list(1),\n      default = c(b = 0),\n      ptype = integer(),\n      name_spec = name_spec,\n      size = 2\n    ),\n    c(\"foo_a\", \"b\")\n  )\n\n  # When `x` elements are recycled, names are also recycled\n  x <- list(c(a = 1), c(b = 2))\n  indices <- list(1:2, 3:4)\n  expect_named(\n    list_combine(x, indices = indices, size = 4, ptype = integer()),\n    c(\"a\", \"a\", \"b\", \"b\")\n  )\n\n  # When `default` elements are recycled, names are also recycled\n  expect_named(\n    list_combine(\n      list(c(a = 1), c(b = 2)),\n      indices = list(1, 3),\n      default = c(c = 0),\n      ptype = integer(),\n      size = 4\n    ),\n    c(\"a\", \"c\", \"b\", \"c\")\n  )\n})"

const rtdal009802Source0077 = "test_that(\"individual data frame columns retain vector names\", {\n  df1 <- data_frame(x = c(a = 1, b = 2))\n  df2 <- data_frame(x = c(c = 3))\n\n  x <- list(df1, df2)\n  indices <- list(c(1, 2), 3)\n\n  result <- list_combine(x, indices = indices, size = 3)\n\n  expect_named(result$x, c(\"a\", \"b\", \"c\"))\n\n  # Names should be identical to equivalent `vec_c()` call\n  expect_identical(\n    list_combine(x, indices = indices, size = 3),\n    vec_c(!!!x)\n  )\n})"

