const rtdal009802Source0080 = "test_that(\"df-cols: when assigning to the same location, names are continually overwritten (#2019)\", {\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = c(a = 1, b = 2), y = c(\"foo\", \"bar\")),\n        data_frame(x = c(c = 0), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"last\"\n    ),\n    data_frame(\n      x = c(c = 0, b = 2),\n      y = c(\"baz\", \"bar\")\n    )\n  )\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = c(a = 1, b = 2), y = c(\"foo\", \"bar\")),\n        data_frame(x = c(c = 0), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"first\"\n    ),\n    data_frame(\n      x = c(a = 1, b = 2),\n      y = c(\"foo\", \"bar\")\n    )\n  )\n\n  # Homogenous fallback\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = foobar(c(a = 1, b = 2)), y = c(\"foo\", \"bar\")),\n        data_frame(x = foobar(c(c = 0)), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"last\"\n    ),\n    data_frame(\n      x = foobar(c(c = 0, b = 2)),\n      y = c(\"baz\", \"bar\")\n    )\n  )\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = foobar(c(a = 1, b = 2)), y = c(\"foo\", \"bar\")),\n        data_frame(x = foobar(c(c = 0)), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"first\"\n    ),\n    data_frame(\n      x = foobar(c(a = 1, b = 2)),\n      y = c(\"foo\", \"bar\")\n    )\n  )\n\n  # `c()` fallback\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = list(\n          data_frame(x = foobar(c(a = 1, b = 2)), y = c(\"foo\", \"bar\")),\n          data_frame(x = foobar(c(c = 0)), y = \"baz\")\n        ),\n        indices = list(\n          c(1, 2),\n          1\n        ),\n        size = 2,\n        multiple = \"last\"\n      ),\n      data_frame(\n        x = foobar_c(c(c = 0, b = 2)),\n        y = c(\"baz\", \"bar\")\n      )\n    )\n  })\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = list(\n          data_frame(x = foobar(c(a = 1, b = 2)), y = c(\"foo\", \"bar\")),\n          data_frame(x = foobar(c(c = 0)), y = \"baz\")\n        ),\n        indices = list(\n          c(1, 2),\n          1\n        ),\n        size = 2,\n        multiple = \"first\"\n      ),\n      data_frame(\n        x = foobar_c(c(a = 1, b = 2)),\n        y = c(\"foo\", \"bar\")\n      )\n    )\n  })\n})"

