const rtdal009802Source0082 = "test_that(\"df-cols: when assigning to the same location, names are cleared as needed (#2019)\", {\n  # - 1st element has names\n  # - 2nd element doesn't have names, so `\"\"` is used as the name to overwrite\n  #   the names written when inserting the 1st element\n  # - Reversed for `multiple = \"first\"`\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = c(a = 1, b = 2), y = c(\"foo\", \"bar\")),\n        data_frame(x = 0, y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"last\"\n    ),\n    data_frame(\n      x = set_names(c(0, 2), c(\"\", \"b\")),\n      y = c(\"baz\", \"bar\")\n    )\n  )\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = c(1, 2), y = c(\"foo\", \"bar\")),\n        data_frame(x = c(c = 0), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"first\"\n    ),\n    data_frame(\n      x = set_names(c(1, 2), c(\"\", \"\")),\n      y = c(\"foo\", \"bar\")\n    )\n  )\n\n  # Homogenous fallback\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = foobar(c(a = 1, b = 2)), y = c(\"foo\", \"bar\")),\n        data_frame(x = foobar(0), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"last\"\n    ),\n    data_frame(\n      x = foobar(set_names(c(0, 2), c(\"\", \"b\"))),\n      y = c(\"baz\", \"bar\")\n    )\n  )\n  expect_identical(\n    list_combine(\n      x = list(\n        data_frame(x = foobar(c(1, 2)), y = c(\"foo\", \"bar\")),\n        data_frame(x = foobar(c(c = 0)), y = \"baz\")\n      ),\n      indices = list(\n        c(1, 2),\n        1\n      ),\n      size = 2,\n      multiple = \"first\"\n    ),\n    data_frame(\n      x = foobar(set_names(c(1, 2), c(\"\", \"\"))),\n      y = c(\"foo\", \"bar\")\n    )\n  )\n\n  # `c()` fallback\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = list(\n          data_frame(x = foobar(c(a = 1, b = 2)), y = c(\"foo\", \"bar\")),\n          data_frame(x = foobar(0), y = \"baz\")\n        ),\n        indices = list(\n          c(1, 2),\n          1\n        ),\n        size = 2,\n        multiple = \"last\"\n      ),\n      data_frame(\n        x = foobar_c(set_names(c(0, 2), c(\"\", \"b\"))),\n        y = c(\"baz\", \"bar\")\n      )\n    )\n  })\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = list(\n          data_frame(x = foobar(c(1, 2)), y = c(\"foo\", \"bar\")),\n          data_frame(x = foobar(c(c = 0)), y = \"baz\")\n        ),\n        indices = list(\n          c(1, 2),\n          1\n        ),\n        size = 2,\n        multiple = \"first\"\n      ),\n      data_frame(\n        x = foobar_c(set_names(c(1, 2), c(\"\", \"\"))),\n        y = c(\"foo\", \"bar\")\n      )\n    )\n  })\n})"

