const rtdal009802Source0084 = "test_that(\"name repair is respected and happens after ordering according to `indices`\", {\n  local_name_repair_quiet()\n\n  x <- list(c(a = 1), c(a = 2))\n\n  indices <- list(2, 1)\n  expect_named(list_combine(x, indices = indices, size = 2), c(\"a\", \"a\"))\n  expect_named(\n    list_combine(x, indices = indices, size = 2, name_repair = \"unique\"),\n    c(\"a...1\", \"a...2\")\n  )\n\n  # With `default`\n  indices <- list(3, 1)\n  default <- c(a = 0)\n  expect_named(\n    list_combine(x, indices = indices, size = 3, default = default),\n    c(\"a\", \"a\", \"a\")\n  )\n  expect_named(\n    list_combine(\n      x,\n      indices = indices,\n      size = 3,\n      default = default,\n      name_repair = \"unique\"\n    ),\n    c(\"a...1\", \"a...2\", \"a...3\")\n  )\n})"

const rtdal009802Source0085 = `test_that("list_combine() can repair names quietly", {
  local_name_repair_verbose()

  x <- c(x = "a", x = "b", x = "c")
  indices <- list(2, c(3, 1))
  expect_snapshot({
    res <- list_combine(
      vec_chop(x, indices = indices),
      indices = indices,
      size = 3,
      name_repair = "unique_quiet"
    )
  })
  expect_named(res, c("x...1", "x...2", "x...3"))

  x <- c("if" = "a", "in" = "b", "for" = "c")
  indices <- list(2, c(3, 1))
  expect_snapshot({
    res <- list_combine(
      vec_chop(x, indices = indices),
      indices = indices,
      size = 3,
      name_repair = "universal_quiet"
    )
  })
  expect_named(res, c(".if", ".in", ".for"))
})`

