const rtdal009802Source0091 = "test_that(\"list_combine() supports named `indices` (#2095)\", {\n  # Particularly in the fallback case where we have to `vec_c()` the `indices`\n\n  # With outer names on `indices`:\n  expect_identical_list_combine(\n    x = list(c(\"a\", \"b\")),\n    indices = list(a = c(1, 2)),\n    size = 2,\n    expect = c(\"a\", \"b\")\n  )\n  expect_identical_list_combine(\n    x = list(c(\"a\", \"b\", \"c\", \"d\")),\n    indices = list(a = c(FALSE, TRUE, FALSE, TRUE)),\n    size = 4,\n    slice_x = TRUE,\n    expect = c(NA, \"b\", NA, \"d\")\n  )\n\n  # With outer and inner names on `indices`:\n  expect_identical_list_combine(\n    x = list(c(\"a\", \"b\"), c(\"c\", \"d\")),\n    indices = list(a = c(x = 1, y = 2), b = c(x = 3, y = 4)),\n    size = 4,\n    expect = c(\"a\", \"b\", \"c\", \"d\")\n  )\n  expect_identical_list_combine(\n    x = list(c(\"a\", \"b\", \"c\", \"d\"), c(\"e\", \"f\", \"g\", \"h\")),\n    indices = list(\n      a = c(w = FALSE, x = TRUE, y = FALSE, z = TRUE),\n      b = c(w = FALSE, x = FALSE, y = TRUE, z = FALSE)\n    ),\n    size = 4,\n    slice_x = TRUE,\n    expect = c(NA, \"b\", \"g\", \"d\")\n  )\n})"

const rtdal009802Source0092 = "test_that(\"`list_combine()` with `slice_x = FALSE`\", {\n  values <- list(1:2, 3:4)\n  size <- 4\n\n  indices <- list(\n    c(TRUE, FALSE, FALSE, TRUE),\n    c(FALSE, TRUE, TRUE, FALSE)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    expect = int(1, 3, 4, 2)\n  )\n\n  indices <- list(\n    c(1, 4),\n    c(2, 3)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    expect = int(1, 3, 4, 2)\n  )\n})"

const rtdal009802Source0093 = "test_that(\"`list_combine()` with `slice_x = FALSE` / recycling\", {\n  values <- list(1L, 2L)\n  size <- 4\n\n  indices <- list(\n    c(TRUE, FALSE, FALSE, TRUE),\n    c(FALSE, TRUE, TRUE, FALSE)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    expect = int(1, 2, 2, 1)\n  )\n\n  indices <- list(\n    c(1, 4),\n    c(2, 3)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    expect = int(1, 2, 2, 1)\n  )\n})"

const rtdal009802Source0094 = "test_that(\"`list_combine()` with `slice_x = TRUE`\", {\n  values <- list(1:4, 5:8)\n  size <- 4\n\n  indices <- list(\n    c(TRUE, FALSE, FALSE, TRUE),\n    c(FALSE, TRUE, TRUE, FALSE)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    slice_x = TRUE,\n    expect = int(1, 6, 7, 4)\n  )\n\n  indices <- list(\n    c(1, 4),\n    c(2, 3)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    slice_x = TRUE,\n    expect = int(1, 6, 7, 4)\n  )\n})"

const rtdal009802Source0095 = "test_that(\"`list_combine()` with `slice_x = TRUE` / recycling\", {\n  values <- list(1L, 2L)\n  size <- 4\n\n  indices <- list(\n    c(TRUE, FALSE, FALSE, TRUE),\n    c(FALSE, TRUE, TRUE, FALSE)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    slice_x = TRUE,\n    expect = int(1, 2, 2, 1)\n  )\n\n  indices <- list(\n    c(1, 4),\n    c(2, 3)\n  )\n  expect_identical_list_combine(\n    x = values,\n    indices = indices,\n    size = size,\n    slice_x = TRUE,\n    expect = int(1, 2, 2, 1)\n  )\n})"

const rtdal009802Source0096 = "test_that(\"`list_combine()` with logical `indices` checks `indices` size\", {\n  values <- list(1L, 2L)\n  indices <- list(\n    c(TRUE, FALSE, FALSE, TRUE),\n    c(FALSE, TRUE, TRUE, FALSE)\n  )\n  size <- 5\n\n  # This isn't the most obvious error but it is hard to know how to do better.\n  # Ideally it would report a size error for `indices`, right now it falls\n  # through to `list_as_locations()` which doesn't allow logical indices.\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = values,\n    indices = indices,\n    size = size\n  )\n})"

const rtdal009802Source0097 = "test_that(\"`multiple` can let first index win\", {\n  x <- list(\n    1:3,\n    4:6\n  )\n  indices <- list(\n    c(1, 2, 3),\n    c(2, 3, 4)\n  )\n  size <- 4\n\n  expect_identical_list_combine(\n    x = x,\n    indices = indices,\n    size = size,\n    multiple = \"first\",\n    expect = int(1, 2, 3, 6)\n  )\n  expect_identical_list_combine(\n    x = x,\n    indices = indices,\n    size = size,\n    multiple = \"last\",\n    expect = int(1, 4, 5, 6)\n  )\n})"

const rtdal009802Source0098 = "test_that(\"`multiple` works with data frames\", {\n  x <- list(\n    data_frame(a = 1:3, b = foobar(4:6), c = foobar(c(7, 8, 9))),\n    data_frame(a = 4:6, b = foobar(7:9), c = foobar(c(10, 11, 12)))\n  )\n  indices <- list(\n    c(1, 2, 3),\n    c(2, 3, 4)\n  )\n  size <- 4\n\n  # Normal and homogeneous fallback mixed\n  expect_identical(\n    list_combine(\n      x = x,\n      indices = indices,\n      size = size,\n      multiple = \"first\"\n    ),\n    data_frame(\n      a = int(1, 2, 3, 6),\n      b = foobar(int(4, 5, 6, 9)),\n      c = foobar(dbl(7, 8, 9, 12))\n    )\n  )\n\n  # Normal and `c()` fallback mixed\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = x,\n        indices = indices,\n        size = size,\n        multiple = \"first\"\n      ),\n      data_frame(\n        a = int(1, 2, 3, 6),\n        b = foobar_c(int(4, 5, 6, 9)),\n        c = foobar_c(dbl(7, 8, 9, 12))\n      )\n    )\n  })\n})"

const rtdal009802Source0099 = "test_that(\"`multiple` works with data frame columns\", {\n  x <- list(\n    data_frame(\n      a = 1:3,\n      b = data_frame(x = c(\"a\", \"b\", \"c\"), y = foobar(4:6)),\n      c = foobar(c(7, 8, 9))\n    ),\n    data_frame(\n      a = 4:6,\n      b = data_frame(x = c(\"d\", \"e\", \"f\"), y = foobar(7:9)),\n      c = foobar(c(10, 11, 12))\n    )\n  )\n  indices <- list(\n    c(1, 2, 3),\n    c(2, 3, 4)\n  )\n  size <- 4\n\n  # Normal and homogeneous fallback mixed\n  expect_identical(\n    list_combine(\n      x = x,\n      indices = indices,\n      size = size,\n      multiple = \"first\"\n    ),\n    data_frame(\n      a = int(1, 2, 3, 6),\n      b = data_frame(\n        x = c(\"a\", \"b\", \"c\", \"f\"),\n        y = foobar(int(4, 5, 6, 9))\n      ),\n      c = foobar(dbl(7, 8, 9, 12))\n    )\n  )\n\n  # Normal and `c()` fallback mixed\n  with_c_foobar({\n    expect_identical(\n      list_combine(\n        x = x,\n        indices = indices,\n        size = size,\n        multiple = \"first\"\n      ),\n      data_frame(\n        a = int(1, 2, 3, 6),\n        b = data_frame(\n          x = c(\"a\", \"b\", \"c\", \"f\"),\n          y = foobar_c(int(4, 5, 6, 9))\n        ),\n        c = foobar_c(dbl(7, 8, 9, 12))\n      )\n    )\n  })\n})"

const rtdal009802Source0100 = "test_that(\"`multiple` shows correctly indexed errors\", {\n  # In fallback, reversal happens after recycling and slicing\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:2, 3L),\n    indices = list(1:3, 4),\n    size = 4,\n    multiple = \"first\"\n  )\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:2, 3L),\n    indices = list(1:3, 4),\n    size = 4,\n    multiple = \"last\"\n  )\n\n  # If there is only 1 issue in `x` sizes, they report consistently\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:4, 3:5),\n    indices = list(1:3, 4),\n    size = 4,\n    slice_x = TRUE,\n    multiple = \"first\"\n  )\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:4, 3:5),\n    indices = list(1:3, 4),\n    size = 4,\n    slice_x = TRUE,\n    multiple = \"last\"\n  )\n\n  # If there are multiple `x` issues, because we reverse the iteration\n  # order in the main path in the `multiple = \"first\"` case, we end up\n  # reporting the last problem first, while the fallback case still\n  # reports the fist problem first. The indices in the error are correct\n  # in both cases, so this inconsistency is allowed.\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:2, 3:5),\n    indices = list(1:3, 4),\n    size = 4,\n    slice_x = TRUE,\n    multiple = \"first\"\n  )\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:2, 3:5),\n    indices = list(1:3, 4),\n    size = 4,\n    slice_x = TRUE,\n    multiple = \"last\"\n  )\n})"

const rtdal009802Source0101 = "test_that(\"`multiple` also applies to names\", {\n  expect_identical_list_combine(\n    x = list(c(a = 1, b = 2), c(c = 3)),\n    indices = list(1:2, 2),\n    size = 2,\n    multiple = \"first\",\n    expect = c(a = 1, b = 2)\n  )\n  expect_identical_list_combine(\n    x = list(c(a = 1, b = 2), c(c = 3)),\n    indices = list(1:2, 2),\n    size = 2,\n    multiple = \"last\",\n    expect = c(a = 1, c = 3)\n  )\n})"

const rtdal009802Source0102 = "test_that(\"`multiple` doesn't affect `default`\", {\n  expect_identical_list_combine(\n    x = list(1:2, 4L),\n    indices = list(c(1, 4), 4),\n    size = 5,\n    multiple = \"first\",\n    default = 0L,\n    expect = int(1, 0, 0, 2, 0)\n  )\n  expect_identical_list_combine(\n    x = list(1:2, 4L),\n    indices = list(c(1, 4), 4),\n    size = 5,\n    multiple = \"last\",\n    default = 0L,\n    expect = int(1, 0, 0, 4, 0)\n  )\n})"

const rtdal009802Source0103 = "test_that(\"`multiple` doesn't apply WITHIN a single index\", {\n  # You always get the last value within a single index vector.\n  # That possibly makes `multiple = \"first\"` a little confusing,\n  # but `multiple` is mostly useful with logical vectors anyways\n  # (case_when() style approach), so it doesn't matter much.\n  expect_identical_list_combine(\n    x = list(1:2, 3:4),\n    indices = list(c(1, 1), c(1, 1)),\n    size = 1,\n    multiple = \"first\",\n    expect = 2L\n  )\n  expect_identical_list_combine(\n    x = list(1:2, 3:4),\n    indices = list(c(1, 1), c(1, 1)),\n    size = 1,\n    multiple = \"last\",\n    expect = 4L\n  )\n})"

const rtdal009802Source0104 = "test_that(\"`compact_seq()` work as `indices`\", {\n  expect_identical_list_combine(\n    x = list(1:3, 4:5),\n    indices = list(compact_seq(2, 3), compact_seq(0, 2)),\n    size = 5,\n    expect = int(4:5, 1:3)\n  )\n  expect_identical_list_combine(\n    x = list(1:3, 4L),\n    indices = list(compact_seq(2, 3), 1),\n    size = 5,\n    expect = int(4, NA, 1:3)\n  )\n})"

const rtdal009802Source0105 = "test_that(\"`compact_seq()` `indices` work with `unmatched`\", {\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:2, 4:5),\n    indices = list(compact_seq(3, 2), compact_seq(0, 2)),\n    size = 5,\n    unmatched = \"error\"\n  )\n  expect_snapshot_list_combine(\n    error = TRUE,\n    x = list(1:2, 4L),\n    indices = list(compact_seq(3, 2), 1),\n    size = 5,\n    unmatched = \"error\"\n  )\n})"

const rtdal009802Source0106 = "test_that(\"`compact_seq()` `indices` work with `default`\", {\n  expect_identical_list_combine(\n    x = list(1:2, 4:5),\n    indices = list(compact_seq(3, 2), compact_seq(0, 2)),\n    size = 5,\n    default = 0L,\n    expect = int(4:5, 0L, 1:2)\n  )\n  expect_identical_list_combine(\n    x = list(1:2, 4L),\n    indices = list(compact_seq(3, 2), 1),\n    size = 5,\n    default = 0L,\n    expect = int(4L, 0L, 0L, 1:2)\n  )\n})"

