const rtdal009804Source0008 = "test_that(\"NULLs are ignored when unchopped with other vectors\", {\n  expect_identical(\n    list_unchop(list(\"a\", NULL, \"b\")),\n    c(\"a\", \"b\")\n  )\n  expect_identical(\n    list_unchop(list(\"a\", NULL, \"b\"), indices = list(2, integer(), 1)),\n    c(\"b\", \"a\")\n  )\n\n  # Homogeneous fallback\n  expect_identical(\n    list_unchop(list(foobar(\"a\"), NULL, foobar(\"b\"))),\n    foobar(c(\"a\", \"b\"))\n  )\n  expect_identical(\n    list_unchop(\n      list(foobar(\"a\"), NULL, foobar(\"b\")),\n      indices = list(2, integer(), 1)\n    ),\n    foobar(c(\"b\", \"a\"))\n  )\n  expect_identical(\n    list_unchop(\n      list(foobar(\"a\"), NULL, foobar(\"b\")),\n      indices = list(2, 3, 1)\n    ),\n    foobar(c(\"b\", \"a\", NA))\n  )\n\n  # Homoegeneous fallback (`NULL` at front)\n  expect_identical(\n    list_unchop(list(NULL, foobar(\"a\"), foobar(\"b\"))),\n    foobar(c(\"a\", \"b\"))\n  )\n  expect_identical(\n    list_unchop(\n      list(NULL, foobar(\"a\"), foobar(\"b\")),\n      indices = list(integer(), 2, 1)\n    ),\n    foobar(c(\"b\", \"a\"))\n  )\n  expect_identical(\n    list_unchop(\n      list(NULL, foobar(\"a\"), foobar(\"b\")),\n      indices = list(3, 2, 1)\n    ),\n    foobar(c(\"b\", \"a\", NA))\n  )\n\n  # `c()` fallback\n  with_c_foobar({\n    expect_identical(\n      list_unchop(list(foobar(\"a\"), NULL, foobar(\"b\"))),\n      foobar_c(c(\"a\", \"b\"))\n    )\n    expect_identical(\n      list_unchop(\n        list(foobar(\"a\"), NULL, foobar(\"b\")),\n        indices = list(2, integer(), 1)\n      ),\n      foobar_c(c(\"b\", \"a\"))\n    )\n    expect_identical(\n      list_unchop(\n        list(foobar(\"a\"), NULL, foobar(\"b\")),\n        indices = list(2, 3, 1)\n      ),\n      foobar_c(c(\"b\", \"a\", NA))\n    )\n  })\n\n  # `c()` fallback (`NULL` at front)\n  with_c_foobar({\n    expect_identical(\n      list_unchop(list(NULL, foobar(\"a\"), foobar(\"b\"))),\n      foobar_c(c(\"a\", \"b\"))\n    )\n    expect_identical(\n      list_unchop(\n        list(NULL, foobar(\"a\"), foobar(\"b\")),\n        indices = list(integer(), 2, 1)\n      ),\n      foobar_c(c(\"b\", \"a\"))\n    )\n    expect_identical(\n      list_unchop(\n        list(NULL, foobar(\"a\"), foobar(\"b\")),\n        indices = list(3, 2, 1)\n      ),\n      foobar_c(c(\"b\", \"a\", NA))\n    )\n  })\n})"

const rtdal009804Source0009 = "test_that(\"can use a `NULL` element with a corresponding index\", {\n  # We've determined this is the behavior we are locked to in `list_unchop()`,\n  # but in `list_combine()` we return `unspecified(2)` here because the user\n  # also specifies a `size`, making this less ambiguous.\n  expect_null(list_unchop(list(NULL), indices = list(1:2)))\n\n  expect_identical(\n    list_unchop(list(NULL), indices = list(1:2), ptype = integer()),\n    c(NA_integer_, NA_integer_)\n  )\n\n  x <- list(\"a\", NULL, c(\"b\", \"c\"))\n  indices <- list(3L, c(1L, 4L), c(2L, 5L))\n  expect_identical(list_unchop(x, indices = indices), c(NA, \"b\", \"a\", NA, \"c\"))\n})"

