const rtdal009804Source0039 = "test_that(\"missing values propagate\", {\n  indices <- list(c(NA_integer_, NA_integer_), c(NA_integer_, 3))\n\n  expect_identical(\n    list_unchop(\n      list(1, 2),\n      indices = indices\n    ),\n    c(NA, NA, 2, NA)\n  )\n\n  # Homogenous fallback\n  expect_identical(\n    list_unchop(\n      list(foobar(1), foobar(2)),\n      indices = indices\n    ),\n    foobar(c(NA, NA, 2, NA))\n  )\n\n  # `c()` fallback\n  with_c_foobar({\n    expect_identical(\n      list_unchop(\n        list(foobar(1), foobar(2)),\n        indices = indices\n      ),\n      foobar_c(c(NA, NA, 2, NA))\n    )\n  })\n})"

