const rtdal009805Source0054 = "test_that(\"`condition` is validated\", {\n  expect_error(\n    vec_locate_matches(1, 2, condition = 1),\n    \"`condition` must be a character vector\"\n  )\n  expect_error(\n    vec_locate_matches(1, 2, condition = \"x\"),\n    'must only contain \"==\", \">\", \">=\", \"<\", or \"<=\"'\n  )\n  expect_error(\n    vec_locate_matches(1, 2, condition = c(\"==\", \"==\")),\n    \"must be length 1, or the same length as the number of columns of the input\"\n  )\n})"

