const rtdal009805Source0061 = `test_that("correctly gets first/last/any match when they come from different nesting containers", {
  needles <- data_frame(
    a = c(1, 8),
    b = c(2, 9)
  )
  haystack <- data_frame(
    a = c(6, 5, 0),
    b = c(6, 7, 1)
  )

  expect_identical(
    vec_locate_matches(needles, haystack, condition = "<", multiple = "first"),
    data_frame(needles = c(1L, 2L), haystack = c(1L, NA))
  )
  expect_identical(
    vec_locate_matches(needles, haystack, condition = "<", multiple = "last"),
    data_frame(needles = c(1L, 2L), haystack = c(2L, NA))
  )
  expect_identical(
    vec_locate_matches(needles, haystack, condition = "<", multiple = "any"),
    data_frame(needles = c(1L, 2L), haystack = c(2L, NA))
  )
  expect_identical(
    vec_locate_matches(
      needles,
      haystack,
      condition = "<",
      multiple = "first",
      remaining = NA_integer_
    ),
    data_frame(needles = c(1L, 2L, NA, NA), haystack = c(1L, NA, 2L, 3L))
  )
  expect_identical(
    vec_locate_matches(
      needles,
      haystack,
      condition = "<",
      multiple = "last",
      remaining = NA_integer_
    ),
    data_frame(needles = c(1L, 2L, NA, NA), haystack = c(2L, NA, 1L, 3L))
  )
  expect_identical(
    vec_locate_matches(
      needles,
      haystack,
      condition = "<",
      multiple = "any",
      remaining = NA_integer_
    ),
    data_frame(needles = c(1L, 2L, NA, NA), haystack = c(2L, NA, 1L, 3L))
  )
})`

const rtdal009805Source0062 = "test_that(\"`multiple` is validated\", {\n  expect_snapshot({\n    (expect_error(vec_locate_matches(1, 2, multiple = 1.5)))\n    (expect_error(vec_locate_matches(1, 2, multiple = c(\"first\", \"last\"))))\n    (expect_error(vec_locate_matches(1, 2, multiple = \"x\")))\n    # Uses internal error\n    (expect_error(vec_locate_matches(\n      1,\n      2,\n      multiple = \"x\",\n      error_call = call(\"fn\")\n    )))\n  })\n})"

