const rtdal009806Source0001 = `test_that("can detect different types of NA", {
  expect_true(vec_detect_missing(NA))
  expect_true(vec_detect_missing(NA_integer_))
  expect_true(vec_detect_missing(NA_real_))
  expect_true(vec_detect_missing(NA_complex_))
  expect_true(vec_detect_missing(complex(real = NA, imaginary = 1)))
  expect_true(vec_detect_missing(NaN))
  expect_true(vec_detect_missing(NA_character_))
  expect_true(vec_detect_missing(list(NULL)))
})`

const rtdal009806Source0002 = `test_that("can detect different types of NA in data frames", {
  # using multiple columns to prevent proxy unwrapping
  expect_true(vec_detect_missing(data.frame(x = NA, y = NA)))
  expect_true(vec_detect_missing(data.frame(x = NA_integer_, y = NA_integer_)))
  expect_true(vec_detect_missing(data.frame(x = NA_real_, y = NaN)))
  expect_true(vec_detect_missing(data.frame(x = NA_complex_, y = NA_complex_)))
  expect_true(vec_detect_missing(data.frame(
    x = complex(real = NA, imaginary = 1),
    y = complex(real = 1, imaginary = NA)
  )))
  expect_true(vec_detect_missing(data.frame(
    x = NA_character_,
    y = NA_character_
  )))
  expect_true(vec_detect_missing(new_data_frame(list(
    x = list(NULL),
    y = list(NULL)
  ))))
})`

const rtdal009806Source0003 = `test_that("raw vectors can never be NA", {
  expect_false(vec_detect_missing(raw(1)))
  expect_false(vec_detect_missing(data.frame(x = raw(1), y = raw(1))))
})`

const rtdal009806Source0004 = `test_that("vectorised over rows of a data frame", {
  df <- data.frame(x = c(1, 1, NA, NA), y = c(1, NA, 1, NA))
  expect_equal(vec_detect_missing(df), c(FALSE, FALSE, FALSE, TRUE))
})`

const rtdal009806Source0005 = `test_that("works recursively with data frame columns", {
  df <- data.frame(x = c(1, 1, NA, NA))
  df$df <- data.frame(y = c(NA, 1, 1, NA), z = c(1, NA, 1, NA))
  expect_equal(vec_detect_missing(df), c(FALSE, FALSE, FALSE, TRUE))
})`

const rtdal009806Source0006 = "test_that(\"0 row, N col data frame always returns `logical()` (#1585)\", {\n  expect_identical(vec_detect_missing(data_frame()), logical())\n  expect_identical(\n    vec_detect_missing(data_frame(x = integer(), y = double())),\n    logical()\n  )\n})"

const rtdal009806Source0007 = "test_that(\">0 row, 0 col data frame always returns `TRUE` for each row (#1585)\", {\n  # `vec_detect_missing()` returns `TRUE` for each row because it (in theory) does\n  # `all()` on each row, and since there are 0 columns we get\n  # `all(logical()) == TRUE` for each row.\n  expect_identical(\n    vec_detect_missing(data_frame(.size = 2L)),\n    c(TRUE, TRUE)\n  )\n})"

const rtdal009806Source0008 = "test_that(\"works with `NULL` input (#1494)\", {\n  expect_identical(vec_detect_missing(NULL), logical())\n})"

const rtdal009806Source0009 = `test_that("can check for any missing with all base vector types", {
  expect_false(vec_any_missing(TRUE))
  expect_false(vec_any_missing(1L))
  expect_false(vec_any_missing(1))
  expect_false(vec_any_missing(complex(real = 1, imaginary = 1)))
  expect_false(vec_any_missing("1"))
  expect_false(vec_any_missing(list(1)))

  expect_true(vec_any_missing(c(TRUE, NA)))
  expect_true(vec_any_missing(c(1L, NA_integer_)))
  expect_true(vec_any_missing(c(1, NA_real_)))
  expect_true(vec_any_missing(complex(real = c(1, NA), imaginary = c(1, NA))))
  expect_true(vec_any_missing(c("1", NA_character_)))
  expect_true(vec_any_missing(list(1, NULL)))
})`

const rtdal009806Source0010 = `test_that("raw vectors can never be missing", {
  expect_false(vec_any_missing(raw(1)))
  expect_false(vec_any_missing(data.frame(x = raw(1), y = raw(1))))
})`

const rtdal009806Source0011 = "test_that(\"works with empty vectors\", {\n  # Like `any(logical())`\n  expect_false(vec_any_missing(integer()))\n})"

const rtdal009806Source0012 = `test_that("correctly detects complex missingness", {
  expect_false(vec_any_missing(complex(real = 1, imaginary = 1)))
  expect_true(vec_any_missing(complex(real = 1, imaginary = NA)))
  expect_true(vec_any_missing(complex(real = NA, imaginary = 1)))
  expect_true(vec_any_missing(complex(real = NA, imaginary = NA)))
})`

const rtdal009806Source0013 = `test_that("treats NaN as missing", {
  expect_true(vec_any_missing(NaN))
})`

const rtdal009806Source0014 = "test_that(\"works with `NULL` input\", {\n  expect_false(vec_any_missing(NULL))\n})"

const rtdal009806Source0015 = `test_that("entire row of a data frame must be missing", {
  df <- data.frame(x = c(1, 1, NA, NA), y = c(1, NA, 1, NA))
  expect_true(vec_any_missing(df))
  expect_false(vec_any_missing(df[-4, ]))
})`

const rtdal009806Source0016 = `test_that("works recursively with data frame columns", {
  df <- data.frame(x = c(1, 1, NA, NA))
  df$df <- data.frame(y = c(NA, 1, 1, NA), z = c(1, NA, 1, NA))
  expect_true(vec_any_missing(df))
  expect_false(vec_any_missing(df[-4, ]))
})`

const rtdal009806Source0017 = "test_that(\"0 row, N col data frame always returns `FALSE` (#1585)\", {\n  df <- data_frame()\n\n  expect_false(vec_any_missing(df))\n  expect_false(vec_any_missing(data_frame(x = integer(), y = double())))\n\n  # This is consistent with `vec_detect_missing()` returning `logical()` for 0 row\n  # data frames. Then `any(logical()) == FALSE` to get `vec_any_missing()`.\n  expect_identical(\n    vec_any_missing(df),\n    any(vec_detect_missing(df))\n  )\n})"

const rtdal009806Source0018 = "test_that(\">0 row, 0 col data frame always returns `TRUE` (#1585)\", {\n  df <- data_frame(.size = 2L)\n\n  expect_true(vec_any_missing(df))\n\n  # This is consistent with `vec_detect_missing()` returning `TRUE` for each row\n  # because it (in theory) does `all()` on each row, and since there are 0\n  # columns we get `all(logical()) == TRUE` for each row.\n  # Then `any(c(TRUE, TRUE)) == TRUE` to get `vec_any_missing()`.\n  expect_identical(\n    vec_any_missing(df),\n    any(vec_detect_missing(df))\n  )\n})"

