const rtdal009807Source0019 = "test_that(\"validate_unique() checks unique names\", {\n  expect_snapshot({\n    (expect_error(validate_unique(chr(NA)), \"`NA`\"))\n    (expect_error(\n      validate_unique(chr(\"\")),\n      class = \"vctrs_error_names_cannot_be_empty\"\n    ))\n    (expect_error(\n      validate_unique(chr(\"a\", \"a\")),\n      class = \"vctrs_error_names_must_be_unique\"\n    ))\n    (expect_error(\n      validate_unique(chr(\"..1\")),\n      class = \"vctrs_error_names_cannot_be_dot_dot\"\n    ))\n    (expect_error(\n      validate_unique(chr(\"...\")),\n      class = \"vctrs_error_names_cannot_be_dot_dot\"\n    ))\n  })\n})"

