const rtdal009807Source0030 = "test_that(\"vec_set_names() falls back to `names<-` with proxied objects\", {\n  x <- structure(1, class = \"foobar\")\n  exp <- set_names(x, \"a\")\n\n  expect_equal(vec_set_names(x, \"a\"), exp)\n\n  local_methods(`names<-.foobar` = function(x, value) \"fallback!\")\n  expect_equal(vec_set_names(x, \"a\"), \"fallback!\")\n})"

const rtdal009807Source0031 = "test_that(\"vec_set_names() falls back to `rownames<-` with shaped proxied objects\", {\n  x <- structure(1:2, dim = c(2L, 1L), class = \"foobar\")\n  names <- c(\"r1\", \"r2\")\n  exp <- x\n  rownames(exp) <- names\n\n  expect_equal(vec_set_names(x, names), exp)\n\n  # `rownames<-` is not generic, but eventually calls `dimnames<-` which is\n  local_methods(`dimnames<-.foobar` = function(x, value) \"fallback!\")\n  expect_equal(vec_set_names(x, names), \"fallback!\")\n})"

const rtdal009807Source0032 = `test_that("vec_set_names() can set NULL names", {
  x <- 1:2
  expect_equal(vec_set_names(x, NULL), x)

  x_named <- set_names(x)
  expect_equal(vec_set_names(x_named, NULL), x)

  x_mat <- as.matrix(x)
  expect_equal(vec_set_names(x_mat, NULL), x_mat)

  x_mat_named <- x_mat
  rownames(x_mat_named) <- c("1", "2")
  exp <- matrix(x_mat, dimnames = list(NULL, NULL))
  expect_equal(vec_set_names(x_mat_named, NULL), exp)
})`

