const rtdal009808Source0058 = `test_that("can be used in a data frame", {
  x <- c(1L, 1L, 1L, 2L, 1L)

  y <- complex(
    real = c(1L, 2L, 1L, 3L, 1L),
    imaginary = c(3L, 2L, 1L, 4L, 1L)
  )

  z <- c(1, 2, 5, 4, 3)

  # as second column
  df1 <- data.frame(x = x, y = y)

  # as first column
  df2 <- data.frame(y = y, x = x)

  # as second column with a third after it to break ties
  df3 <- data.frame(x = x, y = y, z = z)

  # Base R can't do radix sorting with complex
  expect_identical(vec_order_radix(df1), c(3L, 5L, 1L, 2L, 4L))
  expect_identical(vec_order_radix(df2), c(3L, 5L, 1L, 2L, 4L))
  expect_identical(vec_order_radix(df3), c(5L, 3L, 1L, 2L, 4L))
})`

const rtdal009808Source0059 = `test_that("can be used in a data frame when all group sizes are >1", {
  # https://github.com/tidyverse/dplyr/issues/7708

  # Group sizes of 3 (1L) and 2 (2L)
  x <- c(1L, 2L, 1L, 2L, 1L)

  y <- complex(
    # Group sizes of 3 (1L, 1L) and 2 (2L, 2L)
    real = c(1L, 2L, 1L, 2L, 1L),
    # This breaks ties within each group
    imaginary = c(3L, 2L, 2L, 4L, 1L)
  )

  df <- data.frame(x = x, y = y)

  expect_identical(vec_order_radix(df), c(5L, 3L, 1L, 2L, 4L))
})`

const rtdal009808Source0060 = "test_that(\"can be used in a data frame as the third column\", {\n  # Testing that `complex_first_pass` is reset between columns\n\n  x <- c(1L, 1L, 1L, 2L, 2L)\n\n  y <- complex(\n    real = x,\n    # This breaks one tie\n    imaginary = c(1L, 2L, 1L, 2L, 2L)\n  )\n\n  z <- complex(\n    # This breaks one tie\n    real = c(3L, 2L, 1L, 2L, 2L),\n    # This breaks one tie\n    imaginary = c(3L, 2L, 1L, 2L, 1L)\n  )\n\n  df <- data.frame(x = x, y = y, z = z)\n\n  expect_identical(vec_order_radix(df), c(3L, 1L, 2L, 5L, 4L))\n})"

const rtdal009808Source0061 = "test_that(\"all combinations of `direction` and `na_value` work\", {\n  x <- complex(real = c(3, NA, 1.5, 2, NA), imaginary = c(1, 1, 1, 1, 2))\n\n  expect_identical(\n    x[vec_order_radix(x, na_value = \"largest\", direction = \"asc\")],\n    x[order(x, na.last = TRUE, decreasing = FALSE)]\n  )\n  expect_identical(\n    x[vec_order_radix(x, na_value = \"smallest\", direction = \"asc\")],\n    x[order(x, na.last = FALSE, decreasing = FALSE)]\n  )\n\n  # In fixing #1403, we now align with base R\n  expect_identical(\n    x[vec_order_radix(x, na_value = \"largest\", direction = \"desc\")],\n    x[order(x, na.last = FALSE, decreasing = TRUE)]\n  )\n  expect_identical(\n    x[vec_order_radix(x, na_value = \"smallest\", direction = \"desc\")],\n    x[order(x, na.last = TRUE, decreasing = TRUE)]\n  )\n})"

const rtdal009808Source0062 = `test_that("full gambit of tests involving missing values are working as expected (#1403)", {
  x <- complex(
    real = c(NaN, NA, NA, NA, NaN, NaN, 1, 1, 1, 2),
    imaginary = c(NA, NA, NaN, 1, NaN, 1, NA, NaN, 1, NA)
  )

  df <- data_frame(a = rep(1L, length(x)), x = x)

  # {number}, {NaN}, {NaN + NA}, {NA + NaN}, {NA}
  expect <- c(9L, 5L, 6L, 8L, 1L, 3L, 2L, 4L, 7L, 10L)
  expect_identical(
    vec_order_radix(
      x,
      direction = "asc",
      na_value = "largest",
      nan_distinct = TRUE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      x,
      direction = "desc",
      na_value = "smallest",
      nan_distinct = TRUE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "asc",
      na_value = "largest",
      nan_distinct = TRUE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "desc",
      na_value = "smallest",
      nan_distinct = TRUE
    ),
    expect
  )

  # {NA}, {NA + NaN}, {NaN + NA}, {NaN}, {number}
  expect <- c(2L, 4L, 7L, 10L, 3L, 1L, 5L, 6L, 8L, 9L)
  expect_identical(
    vec_order_radix(
      x,
      direction = "asc",
      na_value = "smallest",
      nan_distinct = TRUE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      x,
      direction = "desc",
      na_value = "largest",
      nan_distinct = TRUE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "asc",
      na_value = "smallest",
      nan_distinct = TRUE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "desc",
      na_value = "largest",
      nan_distinct = TRUE
    ),
    expect
  )

  # {number}, {NA or NaN}
  expect <- c(9L, 1:7, 8L, 10L)
  expect_identical(
    vec_order_radix(
      x,
      direction = "asc",
      na_value = "largest",
      nan_distinct = FALSE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      x,
      direction = "desc",
      na_value = "smallest",
      nan_distinct = FALSE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "asc",
      na_value = "largest",
      nan_distinct = FALSE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "desc",
      na_value = "smallest",
      nan_distinct = FALSE
    ),
    expect
  )

  # {NA or NaN}, {number}
  expect <- c(1:8, 10L, 9L)
  expect_identical(
    vec_order_radix(
      x,
      direction = "asc",
      na_value = "smallest",
      nan_distinct = FALSE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      x,
      direction = "desc",
      na_value = "largest",
      nan_distinct = FALSE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "asc",
      na_value = "smallest",
      nan_distinct = FALSE
    ),
    expect
  )
  expect_identical(
    vec_order_radix(
      df,
      direction = "desc",
      na_value = "largest",
      nan_distinct = FALSE
    ),
    expect
  )
})`

