const rtdal009808Source0081 = "test_that(\"`NA` order defaults to last\", {\n  x <- paste0(\"x\", seq(1L, ORDER_INSERTION_BOUNDARY + 1L))\n  x <- c(x, NA_character_, \"y\")\n  expect_identical(vec_order_radix(x)[length(x)], length(x) - 1L)\n})"

