const rtdal009808Source0106 = `test_that("can order 2+ integer column chunks with counting sort", {
  half <- floor(ORDER_INSERTION_BOUNDARY / 2) + 1L
  quarter_low <- floor(half / 2)
  quarter_high <- ceiling(half / 2)

  df <- data.frame(
    x = 1L,
    y = c(rep(2L, quarter_low), rep(1L, quarter_high), rep(3L, half))
  )

  expect_identical(vec_order_radix(df), base_order(df))
})`

const rtdal009808Source0107 = `test_that("can order 2+ integer column chunks with radix sort", {
  half <- floor(ORDER_INSERTION_BOUNDARY / 2) + 1L
  quarter_low <- floor(half / 2)
  quarter_high <- ceiling(half / 2)

  df <- data.frame(
    x = 1L,
    y = c(
      rep(2L, quarter_low),
      rep(1L, quarter_high),
      rep(3L, half),
      INT_ORDER_COUNTING_RANGE_BOUNDARY + 1L
    )
  )

  expect_identical(vec_order_radix(df), base_order(df))
})`

const rtdal009808Source0108 = `test_that("can order 2+ double column chunks with radix sort", {
  half <- floor(ORDER_INSERTION_BOUNDARY / 2) + 1L
  quarter_low <- floor(half / 2)
  quarter_high <- ceiling(half / 2)

  df <- data.frame(
    x = 1,
    y = c(
      rep(2, quarter_low),
      rep(1, quarter_high),
      rep(3, half),
      INT_ORDER_COUNTING_RANGE_BOUNDARY + 1
    )
  )

  expect_identical(vec_order_radix(df), base_order(df))
})`

