const rtdal009808Source0111 = "test_that(\"`chr_proxy_collate` is validated\", {\n  expect_error(\n    vec_order_radix(\"x\", chr_proxy_collate = 1),\n    \"Can't convert `chr_proxy_collate` to a function\"\n  )\n  expect_error(\n    vec_order_radix(\"x\", chr_proxy_collate = ~ c(\"y\", \"z\")),\n    \"1, not 2\"\n  )\n  expect_error(vec_order_radix(\"x\", chr_proxy_collate = ~1), \"character vector\")\n  expect_error(vec_order_radix(\"x\", chr_proxy_collate = function() {\n    \"y\"\n  }))\n})"

const rtdal009808Source0112 = "test_that(\"`chr_proxy_collate` can return bytes-encoded strings (like `stringi::stri_sort_key()`)\", {\n  x <- c(\"A\", \"a\", \"b\", \"B\")\n\n  # Mimic stringi::stri_sort_key(x, locale = \"en\")\n  sort_key <- function(x) {\n    # dput(lapply(stringi::stri_sort_key(x, locale = \"en\"), charToRaw))\n    out <- list(\n      as.raw(c(0x2a, 0x01, 0x05, 0x01, 0xdc)),\n      as.raw(c(0x2a, 0x01, 0x05, 0x01, 0x05)),\n      as.raw(c(0x2c, 0x01, 0x05, 0x01, 0x05)),\n      as.raw(c(0x2c, 0x01, 0x05, 0x01, 0xdc))\n    )\n\n    out <- vapply(out, FUN.VALUE = character(1), function(x) {\n      # Uses native encoding\n      x <- rawToChar(x)\n      Encoding(x) <- \"bytes\"\n      x\n    })\n\n    out\n  }\n\n  expect_identical(\n    vec_order_radix(x, chr_proxy_collate = sort_key),\n    c(2L, 1L, 3L, 4L)\n  )\n})"

