const rtdal009815Source0001 = `test_that("from_as_list_of_vectors = TRUE / to_as_list_of_vectors = TRUE", {
  expect_identical(
    vec_recode_values(
      x = c(1, 2, 3),
      from = list(c(2, 3), c(4, 1)),
      to = list(
        c("a", "b", "c"),
        c("d", "e", "f")
      ),
      from_as_list_of_vectors = TRUE,
      to_as_list_of_vectors = TRUE
    ),
    c("d", "b", "c")
  )
})`

const rtdal009815Source0002 = "test_that(\"from_as_list_of_vectors = TRUE / to_as_list_of_vectors = TRUE (optimized to `from_as_list_of_vectors = FALSE`, `to_as_list_of_vectors = FALSE`)\", {\n  # First optimized to `to_as_list_of_vectors = FALSE`\n  # Then further optimized to `from_as_list_of_vectors = FALSE`\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3),\n      from = list(c(2, 3), c(4, 1)),\n      to = list(\n        \"a\",\n        \"b\"\n      ),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"b\", \"a\", \"a\")\n  )\n})"

const rtdal009815Source0003 = "test_that(\"from_as_list_of_vectors = TRUE / to_as_list_of_vectors = FALSE (always optimized to `from_as_list_of_vectors = FALSE`)\", {\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3),\n      from = list(c(2, 3), c(4, 1)),\n      to = c(\"a\", \"b\"),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = FALSE\n    ),\n    c(\"b\", \"a\", \"a\")\n  )\n})"

