const rtdal009815Source0007 = "test_that(\"can treat list input as a vector (i.e. not as a container of vectors)\", {\n  # This is why we have `from_as_list_of_vectors` and `to_as_list_of_vectors` as arguments\n  expect_identical(\n    vec_recode_values(\n      x = list(1, 2, 3),\n      from = list(2, 5, 1),\n      to = list(\"x\", 1:2, 1:3),\n    ),\n    list(1:3, \"x\", NULL)\n  )\n})"

const rtdal009815Source0008 = "test_that(\"`to` names are kept during `from_as_list_of_vectors, !to_as_list_of_vectors` optimization recycling\", {\n  expect_identical(\n    vec_recode_values(\n      x = c(2, 1, 4, 5),\n      from = list(1:2, 3:4, 5:6),\n      to = c(a = \"x\", b = \"y\", c = \"z\"),\n      from_as_list_of_vectors = TRUE\n    ),\n    c(a = \"x\", a = \"x\", b = \"y\", c = \"z\")\n  )\n})"

const rtdal009815Source0009 = "test_that(\"`to` list names are dropped with `to_as_list_of_vectors`\", {\n  # With `to_as_list_of_vectors` optimization\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 1),\n      from = 1,\n      to = list(a = \"x\"),\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"x\", \"x\")\n  )\n  # Without `to_as_list_of_vectors` optimization\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 1),\n      from = 1,\n      to = list(a = c(\"x\", \"y\")),\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"x\", \"y\")\n  )\n})"

const rtdal009815Source0010 = "test_that(\"`to` is recycled to `from_size` of `to_as_list_of_vectors`\", {\n  # With `to_as_list_of_vectors`\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3, 1, 4),\n      from = c(1, 2),\n      to = list(2),\n      to_as_list_of_vectors = TRUE\n    ),\n    c(2, 2, NA, 2, NA)\n  )\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3, 1, 4),\n      from = c(1, 2),\n      to = list(c(2, 3, 4, 5, 6)),\n      to_as_list_of_vectors = TRUE\n    ),\n    c(2, 3, NA, 5, NA)\n  )\n  # This doesn't make too much sense for a user to provide, but is consistent\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3, 1, 4),\n      from = list(c(1, 2), 4),\n      to = list(2),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    c(2, 2, NA, 2, 2)\n  )\n  # This doesn't make too much sense for a user to provide, but is consistent\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3, 1, 4),\n      from = list(c(1, 2), 4),\n      to = list(c(2, 3, 4, 5, 6)),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    c(2, 3, NA, 5, 6)\n  )\n\n  # Without `to_as_list_of_vectors`\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3, 1),\n      from = c(1, 2),\n      to = 2\n    ),\n    c(2, 2, NA, 2)\n  )\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2, 3, 1, 4),\n      from = list(c(1, 2), 4),\n      to = 2,\n      from_as_list_of_vectors = TRUE\n    ),\n    c(2, 2, NA, 2, 2)\n  )\n})"

const rtdal009815Source0011 = "test_that(\"`from` list names are dropped with `from_as_list_of_vectors`\", {\n  # With `from_as_list_of_vectors, !to_as_list_of_vectors` optimization\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2),\n      from = list(a = 1, b = c(2, 3, 4)),\n      to = c(\"x\", \"y\"),\n      from_as_list_of_vectors = TRUE\n    ),\n    c(\"x\", \"y\")\n  )\n  # Without `from_as_list_of_vectors, !to_as_list_of_vectors` optimization\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2),\n      from = list(a = 1, b = c(2, 3, 4)),\n      to = list(x = c(\"x1\", \"x2\"), y = c(\"y1\", \"y2\")),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"x1\", \"y2\")\n  )\n})"

const rtdal009815Source0012 = "test_that(\"`vec_replace_values()` retains names of `x`\", {\n  # Mimicking `[<-` and `base::replace()`.\n  # Note how `vec_recode_values()` \"creates a new vector\",\n  # so it pulls the names from `to` and `default`.\n  expect_identical(\n    vec_replace_values(\n      x = c(a = 1, b = 2, c = 0),\n      from = c(2, 1),\n      to = c(x = 3, y = 4)\n    ),\n    c(a = 4, b = 3, c = 0)\n  )\n  expect_identical(\n    vec_recode_values(\n      x = c(a = 1, b = 2, c = 0),\n      from = c(2, 1),\n      to = c(x = 3, y = 4)\n    ),\n    c(y = 4, x = 3, NA)\n  )\n})"

const rtdal009815Source0013 = "test_that(\"`unmatched` errors are correct\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(c(1, 2), from = 1, to = 0, unmatched = \"error\")\n  })\n\n  expect_snapshot(error = TRUE, {\n    # `NA` must be matched!\n    vec_recode_values(c(1, NA), from = 1, to = 0, unmatched = \"error\")\n  })\n\n  expect_snapshot(error = TRUE, {\n    # Many locations\n    vec_recode_values(1:100, from = 1, to = 0, unmatched = \"error\")\n  })\n})"

const rtdal009815Source0014 = "test_that(\"`x` and `from` common type errors are correct\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = \"a\", to = 1)\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = list(\"a\"),\n      to = 1,\n      from_as_list_of_vectors = TRUE\n    )\n  })\n})"

const rtdal009815Source0015 = "test_that(\"`to` and `default` `ptype` errors are correct when it is inferred\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1:2,\n      to = list(1, \"x\"),\n      to_as_list_of_vectors = TRUE\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1:2,\n      to = list(1, 2),\n      default = \"x\",\n      to_as_list_of_vectors = TRUE\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1:2, to = 1, default = \"x\")\n  })\n})"

const rtdal009815Source0016 = "test_that(\"`to` and `default` `ptype` errors are correct when it is user supplied\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = 1, ptype = foobar())\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = 1, ptype = character())\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1,\n      to = list(a = 1),\n      ptype = character(),\n      to_as_list_of_vectors = TRUE\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = \"x\", default = 1, ptype = character())\n  })\n})"

const rtdal009815Source0017 = "test_that(\"`to` size is validated\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1:5, from = 1, to = 2:3)\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1:5,\n      from = list(1),\n      to = 2:3,\n      from_as_list_of_vectors = TRUE\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1:5,\n      from = 1,\n      to = list(2, 3),\n      to_as_list_of_vectors = TRUE\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1:5,\n      from = list(1),\n      to = list(2, 3),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1:5,\n      from = 1,\n      to = list(a = 2:3),\n      to_as_list_of_vectors = TRUE\n    )\n  })\n})"

const rtdal009815Source0018 = "test_that(\"`default` size is validated\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1:5, from = 1, to = 2, default = 1:2)\n  })\n})"

const rtdal009815Source0019 = "test_that(\"`x` must be a vector\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(foobar(), from = 1, to = 2, x_arg = \".x\")\n  })\n})"

const rtdal009815Source0020 = "test_that(\"`from` must be a vector or list of vectors\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = foobar(), to = 2, from_arg = \".from\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1,\n      to = 2,\n      from_as_list_of_vectors = TRUE,\n      from_arg = \".from\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = list(a = foobar()),\n      to = 2,\n      from_as_list_of_vectors = TRUE,\n      from_arg = \".from\"\n    )\n  })\n})"

const rtdal009815Source0021 = "test_that(\"`to` must be a vector or list of vectors\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = foobar(), to_arg = \".to\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1,\n      to = 2,\n      to_as_list_of_vectors = TRUE,\n      to_arg = \".to\"\n    )\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1,\n      to = list(a = foobar()),\n      to_as_list_of_vectors = TRUE,\n      to_arg = \".to\"\n    )\n  })\n})"

const rtdal009815Source0022 = "test_that(\"`default` must be a vector\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(\n      1,\n      from = 1,\n      to = 2,\n      default = foobar(),\n      default_arg = \".default\"\n    )\n  })\n})"

const rtdal009815Source0023 = "test_that(\"`from_as_list_of_vectors` and `to_as_list_of_vectors` are validated\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = 1, from_as_list_of_vectors = \"x\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = 1, to_as_list_of_vectors = \"x\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_replace_values(1, from = 1, to = 1, from_as_list_of_vectors = \"x\")\n  })\n  expect_snapshot(error = TRUE, {\n    vec_replace_values(1, from = 1, to = 1, to_as_list_of_vectors = \"x\")\n  })\n})"

const rtdal009815Source0024 = "test_that(\"`unmatched` is validated\", {\n  expect_snapshot(error = TRUE, {\n    vec_recode_values(1, from = 1, to = 1, unmatched = \"e\")\n  })\n})"

const rtdal009815Source0025 = "test_that(\"proof that `ptype` finalization is important\", {\n  # Imagine you have an input logical vector you are remapping\n  # and it happens to only have `NA`s\n  x <- c(NA, NA)\n  from <- NA\n  to <- FALSE\n\n  # If no `ptype` finalization happened, then `ptype = x` would result in\n  # `unspecified` being the output type and these would error\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, default = x, ptype = x),\n    c(FALSE, FALSE)\n  )\n  expect_identical(\n    vec_replace_values(x, from = from, to = to),\n    c(FALSE, FALSE)\n  )\n})"

const rtdal009815Source0026 = "test_that(\"common `ptype` of `to` isn't finalized until `default` has been included\", {\n  # If the common type of `to` is finalized early, we get `logical`, which can't\n  # combine with `default`'s `character` type\n  expect_identical(\n    vec_recode_values(\n      x = \"a\",\n      from = \"a\",\n      to = list(NA),\n      default = \"x\",\n      to_as_list_of_vectors = TRUE\n    ),\n    NA_character_\n  )\n  expect_identical(\n    vec_recode_values(\n      x = \"a\",\n      from = \"b\",\n      to = list(NA),\n      default = \"x\",\n      to_as_list_of_vectors = TRUE\n    ),\n    \"x\"\n  )\n})"

const rtdal009815Source0027 = "test_that(\"extraneous `to` attributes don't end up on the final output\", {\n  x <- c(1, 2, 3)\n\n  # TODO: Ideally the attributes wouldn't show up on the output, but\n  # `list_combine()` doesn't clear them because `vec_ptype(to)` retains\n  # them for some reason\n  # https://github.com/r-lib/vctrs/issues/2025\n  from <- c(2, 3)\n  to <- structure(c(0, -1), foo = \"bar\")\n  expect_identical(\n    vec_recode_values(x, from = from, to = to),\n    structure(c(NA, 0, -1), foo = \"bar\")\n  )\n\n  # TODO: Ideally the attributes wouldn't show up on the output, but\n  # `list_combine()` doesn't clear them because `vec_ptype(to)` retains\n  # them for some reason\n  # https://github.com/r-lib/vctrs/issues/2025\n  from <- 2\n  to <- list(\n    structure(c(0, -1, -2), foo = \"bar\")\n  )\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, to_as_list_of_vectors = TRUE),\n    structure(c(NA, -1, NA), foo = \"bar\")\n  )\n\n  # Note that as soon as you force a `ptype2` computation, the attributes\n  # disappear anyways, suggesting an inconsistency\n\n  # `ptype2` forced by `default`\n  from <- c(2, 3)\n  to <- structure(c(0, -1), foo = \"bar\")\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, default = NA_real_),\n    c(NA, 0, -1)\n  )\n\n  # `ptype2` forced by multiple `to` values\n  from <- c(2, 3)\n  to <- list(\n    structure(c(0, -1, -2), foo = \"bar\"),\n    c(-3, -4, -5)\n  )\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, to_as_list_of_vectors = TRUE),\n    c(NA, -1, -5)\n  )\n})"

const rtdal009815Source0028 = "test_that(\"extraneous `x` attributes don't end up on the final output\", {\n  # TODO: Ideally the attributes wouldn't show up on the output, but\n  # `list_combine()` doesn't clear them because `vec_ptype(x)` retains\n  # them for some reason\n  # https://github.com/r-lib/vctrs/issues/2025\n  x <- structure(1, foo = \"bar\")\n\n  expect_identical(\n    vec_replace_values(x, from = 1, to = 2),\n    structure(2, foo = \"bar\")\n    # 2\n  )\n})"

const rtdal009815Source0029 = "test_that(\"first `from` wins when there are overlaps\", {\n  # Same as `vec_case_when()`\n  expect_identical(\n    vec_recode_values(\n      x = 1,\n      from = c(1, 1),\n      to = c(\"a\", \"b\")\n    ),\n    \"a\"\n  )\n  expect_identical(\n    vec_recode_values(\n      x = 1,\n      from = list(c(1, 3), c(1, 2)),\n      to = c(\"a\", \"b\"),\n      from_as_list_of_vectors = TRUE\n    ),\n    \"a\"\n  )\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2),\n      from = c(1, 1),\n      to = list(c(\"a\", \"b\"), c(\"c\", \"d\")),\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"a\", NA)\n  )\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2),\n      from = list(c(1, 3), c(1, 2)),\n      to = list(c(\"a\", \"b\"), c(\"c\", \"d\")),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"a\", \"d\")\n  )\n})"

const rtdal009815Source0030 = "test_that(\"works when `from` is a list of size 1 elements and `to` doesn't simplify\", {\n  # This is a case where we don't actually build the `from_map` because the\n  # `from` size doesn't change as it flattens\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2),\n      from = list(1, 2),\n      to = list(c(\"a\", \"b\"), c(\"c\", \"d\")),\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    c(\"a\", \"d\")\n  )\n})"

const rtdal009815Source0031 = "test_that(\"works when `to` is a length >1 vector and every element of `x` is matched by `from`\", {\n  # This is an optimized case where we directly use the index provided by\n  # `vec_match()` to slice `to` with\n  expect_identical(\n    vec_recode_values(\n      x = c(1, 2),\n      from = c(2, 1),\n      to = c(\"a\", \"b\")\n    ),\n    c(\"b\", \"a\")\n  )\n})"

const rtdal009815Source0032 = "test_that(\"data frames - vector `from`, vector `to`\", {\n  x <- data_frame(a = 1:3, b = 3:5)\n  from <- data_frame(a = int(3, 1), b = c(5, 3))\n\n  # Recycling\n  to <- data_frame(c = \"a\", d = \"y\")\n  expect_identical(\n    vec_recode_values(x, from = from, to = to),\n    data_frame(c = c(\"a\", NA, \"a\"), d = c(\"y\", NA, \"y\"))\n  )\n\n  to <- data_frame(c = c(\"a\", \"b\"), d = c(\"x\", \"y\"))\n  expect_identical(\n    vec_recode_values(x, from = from, to = to),\n    data_frame(c = c(\"b\", NA, \"a\"), d = c(\"y\", NA, \"x\"))\n  )\n  # List `from`, vector `to`\n\n  # List `from`, list `to`\n})"

const rtdal009815Source0033 = "test_that(\"data frames - vector `from`, list `to`\", {\n  x <- data_frame(a = 1:3, b = 3:5)\n  from <- data_frame(a = int(3, 1), b = c(5, 3))\n\n  # Recycling to `from` size and `x` size\n  to <- list(\n    data_frame(c = \"a\", d = \"y\")\n  )\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, to_as_list_of_vectors = TRUE),\n    data_frame(c = c(\"a\", NA, \"a\"), d = c(\"y\", NA, \"y\"))\n  )\n\n  # Recycling to `from` size\n  to <- list(\n    data_frame(c = c(\"a\", \"b\", \"c\"), d = c(\"x\", \"y\", \"z\"))\n  )\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, to_as_list_of_vectors = TRUE),\n    data_frame(c = c(\"a\", NA, \"c\"), d = c(\"x\", NA, \"z\"))\n  )\n\n  # Recycling to `x` size\n  to <- list(\n    data_frame(c = \"a\", d = \"x\"),\n    data_frame(c = \"b\", d = \"y\")\n  )\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, to_as_list_of_vectors = TRUE),\n    data_frame(c = c(\"b\", NA, \"a\"), d = c(\"y\", NA, \"x\"))\n  )\n})"

const rtdal009815Source0034 = "test_that(\"data frames - list `from`, vector `to`\", {\n  x <- data_frame(a = 1:3, b = 3:5)\n\n  # Recycling `to` to `from` size (this would be strange)\n  from <- list(\n    data_frame(a = 1L, b = 3L),\n    data_frame(a = 3:4, b = 5:6)\n  )\n  to <- data_frame(c = \"a\", d = \"x\")\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, from_as_list_of_vectors = TRUE),\n    data_frame(c = c(\"a\", NA, \"a\"), d = c(\"x\", NA, \"x\"))\n  )\n\n  from <- list(\n    data_frame(a = 1L, b = 3L),\n    data_frame(a = 3:4, b = 5:6)\n  )\n  to <- data_frame(c = c(\"a\", \"b\"), d = c(\"x\", \"y\"))\n  expect_identical(\n    vec_recode_values(x, from = from, to = to, from_as_list_of_vectors = TRUE),\n    data_frame(c = c(\"a\", NA, \"b\"), d = c(\"x\", NA, \"y\"))\n  )\n})"

const rtdal009815Source0035 = "test_that(\"data frames - list `from`, list `to`\", {\n  x <- data_frame(a = 1:3, b = 3:5)\n\n  # Recycling `to` to `from` size (this would be strange)\n  # Recycling `to` elements to `x` size\n  from <- list(\n    data_frame(a = 1L, b = 3L),\n    data_frame(a = 3:4, b = 5:6)\n  )\n  to <- list(\n    data_frame(c = \"a\", d = \"x\")\n  )\n  expect_identical(\n    vec_recode_values(\n      x,\n      from = from,\n      to = to,\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    data_frame(c = c(\"a\", NA, \"a\"), d = c(\"x\", NA, \"x\"))\n  )\n\n  # Recycling `to` elements to `x` size\n  from <- list(\n    data_frame(a = 1L, b = 3L),\n    data_frame(a = 3:4, b = 5:6)\n  )\n  to <- list(\n    data_frame(c = \"a\", d = \"x\"),\n    data_frame(c = \"b\", d = \"y\")\n  )\n  expect_identical(\n    vec_recode_values(\n      x,\n      from = from,\n      to = to,\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    data_frame(c = c(\"a\", NA, \"b\"), d = c(\"x\", NA, \"y\"))\n  )\n\n  from <- list(\n    data_frame(a = 1L, b = 3L),\n    data_frame(a = 3:4, b = 5:6)\n  )\n  to <- list(\n    data_frame(c = c(\"a\", \"b\", \"c\"), d = c(\"x\", \"y\", \"z\")),\n    data_frame(c = c(\"aa\", \"bb\", \"cc\"), d = c(\"xx\", \"yy\", \"zz\"))\n  )\n  expect_identical(\n    vec_recode_values(\n      x,\n      from = from,\n      to = to,\n      from_as_list_of_vectors = TRUE,\n      to_as_list_of_vectors = TRUE\n    ),\n    data_frame(c = c(\"a\", NA, \"cc\"), d = c(\"x\", NA, \"zz\"))\n  )\n})"

