const rtdal009822Source0001 = `test_that("vec_as_short_length() checks inputs", {
  expect_equal(vec_as_short_length(0), 0)
  expect_equal(vec_as_short_length(1L), 1)

  my_function <- function(my_arg) vec_as_short_length(my_arg)
  expect_snapshot({
    (expect_error(my_function(-1)))
    (expect_error(my_function(1:2)))
    (expect_error(my_function(1.5)))
    (expect_error(my_function(NA)))
    (expect_error(my_function(na_int)))
    (expect_error(my_function("foo")))
    (expect_error(my_function(foobar(1:2))))
    (expect_error(my_function(.Machine$double.xmax)))
  })
})`

const rtdal009822Source0002 = "test_that(\"vec_as_short_length() has a special error about long vector support\", {\n  # In particular, skips on 32-bit Windows where `r_ssize == int`\n  skip_if(.Machine$sizeof.pointer < 8L, message = \"No long vector support\")\n\n  my_function <- function(my_arg) vec_as_short_length(my_arg)\n  expect_snapshot({\n    (expect_error(my_function(.Machine$integer.max + 1)))\n  })\n})"

const rtdal009822Source0003 = `test_that("vec_size must be called with vector", {
  expect_error(vec_size(mean), class = "vctrs_error_scalar_type")
})`

const rtdal009822Source0004 = `test_that("length is number of rows", {
  expect_equal(vec_size(integer()), 0)
  expect_equal(vec_size(array(integer())), 0)

  expect_equal(vec_size(1:2), 2)
  expect_equal(vec_size(array(dim = 2)), 2)

  expect_equal(vec_size(matrix(nrow = 2, ncol = 3)), 2)
  expect_equal(vec_size(array(dim = c(2, 1, 5))), 2)
})`

const rtdal009822Source0005 = `test_that("length of record is number of rows, not fields", {
  r <- new_rcrd(list(x = 1:10))
  expect_equal(vec_size(r), 10)
})`

const rtdal009822Source0006 = `test_that("handles three types of data frame rownames", {
  df1 <- df2 <- df3 <- data.frame(x = 1:3)
  rownames(df1) <- NULL
  rownames(df2) <- 3:1
  rownames(df3) <- letters[1:3]

  expect_equal(vec_size(df1), 3)
  expect_equal(vec_size(df2), 3)
  expect_equal(vec_size(df3), 3)
})`

const rtdal009822Source0007 = `test_that("handles positive short row names (#220)", {
  data <- structure(mtcars, row.names = c(NA, 32))
  expect_identical(vec_size(data), 32L)
})`

const rtdal009822Source0008 = `test_that("size is proxied", {
  local_env_proxy()
  expect_size(new_proxy(1:3), 3)
  expect_size(new_proxy(list(1, 2, 3)), 3)
  expect_size(new_proxy(foobar(list(1, 2, 3))), 3)
})`

const rtdal009822Source0009 = "test_that(\"`NULL` has size zero\", {\n  expect_identical(vec_size(NULL), 0L)\n})"

const rtdal009822Source0010 = `test_that("can take the size of unspecified objects", {
  expect_size(NA, 1)
  expect_size(c(NA, NA), 2)
  expect_size(unspecified(2), 2)
})`

const rtdal009822Source0011 = `test_that("vec_size_common() checks inputs", {
  expect_snapshot({
    (expect_error(vec_size_common(.size = "foo")))
    (expect_error(vec_size_common(.size = 1:2)))
  })
})`

const rtdal009822Source0012 = "test_that(\"vec_size_common() mentions `arg` in errors\", {\n  my_function <- function(...) vec_size_common(..., .arg = \"my_arg\")\n  expect_snapshot({\n    (expect_error(my_function(this_arg = 1:2, that_arg = int())))\n  })\n})"

const rtdal009822Source0013 = "test_that(\"vec_size_common with no input is 0L unless `.absent` is provided\", {\n  expect_identical(vec_size_common(), 0L)\n  expect_identical(vec_size_common(NULL), 0L)\n  expect_equal(vec_size_common(.absent = na_int), na_int)\n})"

const rtdal009822Source0014 = "test_that(\"`.absent` must be supplied when `...` is empty\", {\n  expect_snapshot({\n    (expect_error(vec_size_common(.absent = NULL)))\n  })\n})"

const rtdal009822Source0015 = "test_that(\"`.absent` must be a length 1 integer if provided\", {\n  expect_snapshot({\n    (expect_error(vec_size_common(.absent = 1), \"must be a single integer\"))\n    (expect_error(\n      vec_size_common(.absent = c(1L, 2L)),\n      \"must be a single integer\"\n    ))\n  })\n})"

const rtdal009822Source0016 = "test_that(\"`NULL` is treated as the absence of input\", {\n  expect_equal(vec_size_common(1:5, NULL), vec_size_common(1:5))\n})"

const rtdal009822Source0017 = `test_that("size 1 is overshadowed by any other size", {
  expect_equal(vec_size_common(1, integer()), 0)
  expect_equal(vec_size_common(1, 1:5), 5)
})`

const rtdal009822Source0018 = `test_that("if not size 1, sizes must be identical", {
  expect_equal(vec_size_common(integer(), integer()), 0)
  expect_error(
    vec_size_common(1:2, integer()),
    class = "vctrs_error_incompatible_size"
  )
  expect_error(
    vec_size_common(1:2, 1:3),
    class = "vctrs_error_incompatible_size"
  )
})`

const rtdal009822Source0019 = `test_that("argument tags are forwarded", {
  expect_snapshot(error = TRUE, vec_size_common(1:2, 1, 1:4))
  expect_snapshot(error = TRUE, vec_size_common(foo = 1:2, 1, bar = 1:4))
})`

const rtdal009822Source0020 = `test_that("can pass size", {
  expect_identical(vec_size_common(1:2, 1:3, .size = 5L), 5L)
})`

const rtdal009822Source0021 = `test_that("provided size is cast to an integer", {
  expect_identical(vec_size_common(.size = 1), 1L)
})`

const rtdal009822Source0022 = `test_that("doesn't mutate the input", {
  x <- list(a = 1, b = 2:3)
  expect_identical(vec_size_common(!!!x), 2L)
  expect_identical(x, list(a = 1, b = 2:3))
})`

const rtdal009822Source0023 = `test_that("only lists are allowed", {
  expect_error(list_sizes(mtcars), "must be a list")
  expect_error(list_sizes(1), "must be a list")
})`

const rtdal009822Source0024 = `test_that("computes element sizes", {
  expect_identical(list_sizes(list(1, 1:3, c("a", "b"))), c(1L, 3L, 2L))
})`

const rtdal009822Source0025 = `test_that("retains list names", {
  x <- list(1, x = 2, a = 3)
  expect_named(list_sizes(x), c("", "x", "a"))

  x <- list_of(y = 1, x = 2, a = 3)
  expect_named(list_sizes(x), c("y", "x", "a"))
})`

const rtdal009822Source0026 = `test_that("retains names of empty lists", {
  x <- structure(list(), names = character())
  expect_named(list_sizes(x), character())
})`

const rtdal009822Source0027 = `test_that("vec_seq_along returns size-0 output for size-0 input", {
  expect_equal(vec_seq_along(character()), integer())
  expect_equal(vec_seq_along(data.frame()), integer())
})`

const rtdal009822Source0028 = `test_that("vec_init_along can be called with single argument", {
  expect_equal(vec_init_along(1:3), rep(NA_integer_, 3))
})`

const rtdal009822Source0029 = `test_that("uses y when x is empty", {
  expect_equal(1 %0% 2, 1)
  expect_equal(1[0] %0% 2, 2)
})`

