const rtdal009831Source0001 = `test_that("ptype2 base methods are not inherited", {
  ptypes <- vec_remove(base_empty_types, c("null", "dataframe"))
  for (ptype in ptypes) {
    x <- new_vctr(ptype, class = "foobar", inherit_base_type = TRUE)
    expect_s3_class(vec_ptype2(x, x), "foobar")
    expect_error(vec_ptype2(x, ptype), class = "vctrs_error_incompatible_type")
    expect_error(vec_ptype2(ptype, x), class = "vctrs_error_incompatible_type")
  }
})`

const rtdal009831Source0002 = `test_that("cast base methods are not inherited", {
  ptypes <- vec_remove(base_empty_types, c("null", "dataframe"))
  for (ptype in ptypes) {
    x <- new_vctr(ptype, class = "foobar", inherit_base_type = TRUE)
    expect_s3_class(vec_cast(ptype, x), "foobar")
    expect_error(vec_cast(x, ptype), class = "vctrs_error_incompatible_type")
  }
})`

const rtdal009831Source0003 = `test_that("default cast allows objects with the same type", {
  x <- structure(1, class = c("foo", "double"))
  expect_equal(vec_cast(x, x), x)
})`

const rtdal009831Source0004 = `test_that("array dimensions are preserved", {
  mat1 <- matrix(lgl(), nrow = 1, ncol = 1)
  mat2 <- matrix(lgl(), nrow = 2, ncol = 2)
  mat3 <- matrix(lgl(), nrow = 2, ncol = 3)

  expect_equal(vec_ptype2(mat1, mat1), matrix(lgl(), nrow = 0, ncol = 1))
  expect_equal(vec_ptype2(mat1, mat2), matrix(lgl(), nrow = 0, ncol = 2))
  expect_error(vec_ptype2(mat2, mat3), class = "vctrs_error_incompatible_type")
})`

const rtdal009831Source0005 = `test_that("vec_shaped_ptype()", {
  int <- function(...) array(NA_integer_, c(...))

  expect_identical(
    vec_shaped_ptype(integer(), int(5), int(10)),
    new_shape(integer())
  )
  expect_identical(
    vec_shaped_ptype(integer(), int(5, 1), int(10, 1)),
    new_shape(integer(), 1)
  )
  expect_identical(
    vec_shaped_ptype(integer(), int(5, 1, 2), int(10, 1, 2)),
    new_shape(integer(), 1:2)
  )
})`

const rtdal009831Source0006 = `test_that("vec_shaped_ptype() evaluates arg lazily", {
  expect_silent(vec_shaped_ptype(
    integer(),
    int(5),
    int(10),
    x_arg = print("oof")
  ))
  expect_silent(vec_shaped_ptype(
    integer(),
    int(5),
    int(10),
    y_arg = print("oof")
  ))
})`

const rtdal009831Source0007 = `test_that("NULL is idempotent", {
  expect_equal(vec_cast(NULL, NULL), NULL)
  expect_equal(vec_cast(list(1:3), NULL), list(1:3))
})`

const rtdal009831Source0008 = `test_that("safe casts work as expected", {
  exp <- lgl(TRUE, FALSE)
  expect_equal(vec_cast(NULL, logical()), NULL)
  expect_equal(vec_cast(lgl(TRUE, FALSE), logical()), exp)
  expect_equal(vec_cast(int(1L, 0L), logical()), exp)
  expect_equal(vec_cast(dbl(1, 0), logical()), exp)

  # These used to be allowed
  expect_error(
    vec_cast(chr("T", "F"), logical()),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(chr("TRUE", "FALSE"), logical()),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(chr("true", "false"), logical()),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(list(1, 0), logical()),
    class = "vctrs_error_incompatible_type"
  )
})`

const rtdal009831Source0009 = `test_that("NA casts work as expected", {
  exp <- lgl(NA)
  to <- lgl()

  expect_equal(vec_cast(lgl(NA), to), exp)
  expect_equal(vec_cast(int(NA), to), exp)
  expect_equal(vec_cast(dbl(NA), to), exp)

  # These used to be allowed
  expect_error(vec_cast(chr(NA), to), class = "vctrs_error_incompatible_type")
  expect_error(vec_cast(list(NA), to), class = "vctrs_error_incompatible_type")
})`

const rtdal009831Source0010 = `test_that("Shaped NA casts work as expected", {
  mat <- matrix
  exp_mat <- mat(lgl(NA))
  to_mat <- matrix(lgl())

  expect_equal(vec_cast(mat(lgl(NA)), to_mat), exp_mat)
  expect_equal(vec_cast(mat(int(NA)), to_mat), exp_mat)
  expect_equal(vec_cast(mat(dbl(NA)), to_mat), exp_mat)

  # These used to be allowed
  expect_error(
    vec_cast(mat(chr(NA)), to_mat),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(mat(list(NA)), to_mat),
    class = "vctrs_error_incompatible_type"
  )
})`

const rtdal009831Source0011 = `test_that("lossy casts generate warning", {
  expect_lossy(
    vec_cast(int(2L, 1L), lgl()),
    lgl(TRUE, TRUE),
    x = int(),
    to = lgl()
  )
  expect_lossy(
    vec_cast(dbl(2, 1), lgl()),
    lgl(TRUE, TRUE),
    x = dbl(),
    to = lgl()
  )

  # These used to be allowed
  expect_error(
    vec_cast(chr("x", "TRUE"), lgl()),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(chr("t", "T"), lgl()),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(chr("f", "F"), lgl()),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(list(c(TRUE, FALSE), TRUE), lgl()),
    class = "vctrs_error_incompatible_type"
  )
})`

const rtdal009831Source0012 = `test_that("invalid casts generate error", {
  expect_error(
    vec_cast(factor("a"), logical()),
    class = "vctrs_error_incompatible_type"
  )
})`

const rtdal009831Source0013 = `test_that("dimensionality matches output", {
  x1 <- matrix(TRUE, nrow = 1, ncol = 1)
  x2 <- matrix(1, nrow = 0, ncol = 2)
  expect_dim(vec_cast(x1, x2), c(1, 2))
  expect_dim(vec_cast(TRUE, x2), c(1, 2))

  x <- matrix(1, nrow = 2, ncol = 2)
  expect_error(vec_cast(x, logical()), class = "vctrs_error_incompatible_type")
})`

