const rtdal009834Source0027 = "test_that(\"vec_ptype_common() gives expected results with <POSIXlt>\", {\n  # See `vec_ptype.POSIXlt()` for details\n  x <- as.POSIXlt(\"2020-01-01\", tz = \"UTC\")\n\n  # `vec_ptype(x)` returns `<POSIXlt>`\n  exp <- x[0]\n  expect_identical(vec_ptype_common(x), exp)\n  expect_identical(vec_ptype_common(.ptype = x), exp)\n\n  # `vec_ptype2(x, x)` returns `<POSIXct>`\n  exp <- new_datetime(tzone = \"UTC\")\n  expect_identical(vec_ptype_common(x, x), exp)\n\n  # With <unspecified> input, still uses `vec_ptype(x)`, so returns `<POSIXlt>`\n  exp <- x[0]\n  expect_identical(vec_ptype_common(x, NA), exp)\n  expect_identical(vec_ptype_common(NA, x), exp)\n  expect_identical(vec_ptype_common(x, NULL), exp)\n  expect_identical(vec_ptype_common(NULL, x), exp)\n})"

const rtdal009834Source0028 = `test_that("safe casts work as expected", {
  date <- as.Date("2018-01-01")
  datetime_ct <- as.POSIXct(as.character(date))
  datetime_lt <- as.POSIXlt(datetime_ct)

  expect_identical(vec_cast(NULL, date), NULL)
  expect_identical(vec_cast(date, date), date)
  expect_identical(vec_cast(datetime_ct, date), date)
  expect_identical(vec_cast(datetime_lt, date), date)

  missing_date <- new_date(NA_real_)

  expect_identical(vec_cast(missing_date, missing_date), missing_date)
  expect_identical(
    vec_cast(as.POSIXct(missing_date), missing_date),
    missing_date
  )
  expect_identical(
    vec_cast(as.POSIXlt(missing_date), missing_date),
    missing_date
  )

  # These used to be allowed
  expect_error(vec_cast(17532, date), class = "vctrs_error_incompatible_type")
  expect_error(
    vec_cast("2018-01-01", date),
    class = "vctrs_error_incompatible_type"
  )
  expect_error(
    vec_cast(list(date), date),
    class = "vctrs_error_incompatible_type"
  )
})`

