const rtdal009835Source0002 = `test_that("grouped-df is proxied and restored", {
  gdf <- dplyr::group_by(bare_mtcars, cyl)

  expect_identical(vec_proxy(gdf), gdf)
  expect_identical(vec_restore(bare_mtcars, gdf), gdf)

  expect_identical(vec_ptype(gdf), gdf[0, ])

  gdf <- dplyr::group_by(bare_mtcars, cyl, am, vs)
  expect_identical(gdf[0, ], vec_ptype(gdf))

  out <- vec_ptype(dplyr::group_by(bare_mtcars, cyl, .drop = FALSE))
  expect_drop(out, FALSE)
})`

const rtdal009835Source0003 = `test_that("can take the common type of grouped tibbles and tibbles", {
  gdf <- dplyr::group_by(bare_mtcars, cyl)
  expect_identical(vec_ptype2(gdf, data.frame()), vec_ptype(gdf))
  expect_identical(vec_ptype2(data.frame(), gdf), vec_ptype(gdf))
  expect_identical(vec_ptype2(gdf, tibble()), vec_ptype(gdf))
  expect_identical(vec_ptype2(tibble(), gdf), vec_ptype(gdf))

  gdf_nodrop <- dplyr::group_by(bare_mtcars, cyl, .drop = FALSE)
  expect_drop(vec_ptype2(gdf, gdf_nodrop), FALSE)
  expect_drop(vec_ptype2(gdf_nodrop, gdf), FALSE)
  expect_drop(vec_ptype2(gdf_nodrop, bare_mtcars), FALSE)
  expect_drop(vec_ptype2(bare_mtcars, gdf_nodrop), FALSE)
})`

const rtdal009835Source0004 = `test_that("the common type of grouped tibbles includes the union of grouping variables", {
  gdf1 <- dplyr::group_by(bare_mtcars, cyl)
  gdf2 <- dplyr::group_by(bare_mtcars, am, vs)
  expect_identical(
    vec_ptype2(gdf1, gdf2),
    vec_ptype(dplyr::group_by(bare_mtcars, cyl, am, vs))
  )
})`

const rtdal009835Source0005 = "test_that(\"can cast to and from `grouped_df`\", {\n  gdf <- dplyr::group_by(unrownames(bare_mtcars), cyl)\n  input <- bare_mtcars[10]\n  cast_gdf <- dplyr::group_by(vec_cast(bare_mtcars[10], bare_mtcars), cyl)\n\n  expect_error(\n    vec_cast(input, dplyr::group_by(bare_mtcars[\"cyl\"], cyl)),\n    class = \"vctrs_error_cast_lossy\"\n  )\n\n  expect_identical(\n    vec_cast(input, gdf),\n    cast_gdf\n  )\n  expect_identical(\n    vec_cast(gdf, bare_mtcars),\n    unrownames(bare_mtcars)\n  )\n\n  expect_identical(\n    vec_cast(tibble::as_tibble(input), gdf),\n    unrownames(cast_gdf)\n  )\n  tib <- tibble::as_tibble(bare_mtcars)\n  expect_identical(\n    unrownames(vec_cast(gdf, tib)),\n    tib\n  )\n})"

const rtdal009835Source0006 = "test_that(\"casting to `grouped_df` doesn't require grouping variables\", {\n  expect_identical(\n    vec_cast(bare_mtcars[10], dplyr::group_by(bare_mtcars, cyl)),\n    dplyr::group_by(vec_cast(bare_mtcars[10], bare_mtcars), cyl)\n  )\n})"

const rtdal009835Source0007 = "test_that(\"casting to `grouped_df` handles `drop`\", {\n  gdf_nodrop <- dplyr::group_by(bare_mtcars, cyl, .drop = FALSE)\n  expect_identical(vec_cast(bare_mtcars, gdf_nodrop), gdf_nodrop)\n})"

const rtdal009835Source0008 = `test_that("can cbind grouped data frames", {
  gdf <- dplyr::group_by(bare_mtcars[-10], cyl)
  df <- unrownames(bare_mtcars)[10]

  expect_identical(
    unrownames(vec_cbind(gdf, df)),
    tibble::as_tibble(bare_mtcars)[c(1:9, 11, 10)]
  )

  gdf1 <- dplyr::group_by(bare_mtcars[2], cyl)
  gdf2 <- dplyr::group_by(bare_mtcars[8:9], vs, am)
  expect_identical(
    unrownames(vec_cbind(gdf1, gdf2)),
    tibble::as_tibble(bare_mtcars)[c(2, 8, 9)]
  )
})`

const rtdal009835Source0009 = `test_that("rowwise can be proxied and restored", {
  rww <- dplyr::rowwise(unrownames(bare_mtcars))

  expect_identical(vec_proxy(rww), rww)
  expect_identical(vec_restore(unrownames(bare_mtcars), rww), rww)

  expect_identical(vec_ptype(rww), rww[0, ])
})`

const rtdal009835Source0010 = `test_that("can take the common type of rowwise tibbles and tibbles", {
  rww <- dplyr::rowwise(bare_mtcars)
  expect_identical(vec_ptype2(rww, data.frame()), vec_ptype(rww))
  expect_identical(vec_ptype2(data.frame(), rww), vec_ptype(rww))
  expect_identical(vec_ptype2(rww, tibble()), vec_ptype(rww))
  expect_identical(vec_ptype2(tibble(), rww), vec_ptype(rww))
})`

const rtdal009835Source0011 = "test_that(\"can cast to and from `rowwise_df`\", {\n  rww <- unrownames(dplyr::rowwise(bare_mtcars))\n  input <- bare_mtcars[10]\n  cast_rww <- dplyr::rowwise(vec_cast(bare_mtcars[10], bare_mtcars))\n\n  expect_error(\n    vec_cast(input, dplyr::rowwise(bare_mtcars[\"cyl\"])),\n    class = \"vctrs_error_cast_lossy\"\n  )\n\n  expect_identical(\n    vec_cast(input, rww),\n    cast_rww\n  )\n  expect_identical(\n    vec_cast(rww, bare_mtcars),\n    unrownames(bare_mtcars)\n  )\n\n  expect_identical(\n    vec_cast(tibble::as_tibble(input), rww),\n    unrownames(cast_rww)\n  )\n  tib <- tibble::as_tibble(bare_mtcars)\n  expect_identical(\n    unrownames(vec_cast(rww, tib)),\n    tib\n  )\n})"

const rtdal009835Source0012 = `test_that("can cbind rowwise data frames", {
  df <- unrownames(bare_mtcars)
  rww <- dplyr::rowwise(df[-2])
  gdf <- dplyr::group_by(df[2], cyl)

  exp <- dplyr::rowwise(df[c(1, 3:11, 2)])
  expect_identical(vec_cbind(rww, df[2]), exp)

  # Suboptimal
  expect_identical(vec_cbind(rww, gdf), exp)
})`

const rtdal009835Source0013 = `test_that("common type between rowwise and grouped data frames is a bare df", {
  out <- vec_ptype_common(
    dplyr::rowwise(bare_mtcars),
    dplyr::group_by(bare_mtcars, cyl)
  )
  expect_identical(out, tibble::as_tibble(bare_mtcars[0, ]))
})`

