const rtdal009837Source0003 = `as_IDate_with_names <- function(x) {
  out <- as.IDate(x)
  names(out) <- names(x)
  out
}`

const rtdal009837Source0004 = `test_that("ptype abbr", {
  x <- as.IDate("2019-01-01")
  expect_identical(vec_ptype_abbr(x), "IDate")
})`

const rtdal009837Source0005 = `test_that("ptype full", {
  x <- as.IDate("2019-01-01")
  expect_identical(vec_ptype_full(x), "IDate")
})`

const rtdal009837Source0006 = `test_that("can get common type of IDate and IDate", {
  x <- as_IDate_with_names(c(a = "2019-01-01"))

  # It shouldn't have names, but thats a vctrs problem
  expect <- as_IDate_with_names(set_names(integer(), character()))

  expect_identical(vec_ptype2(x, x), expect)
})`

const rtdal009837Source0007 = `test_that("can't get common type of Date and IDate", {
  x <- as.Date("2019-01-01")
  y <- as.IDate("2019-01-01")

  expect_snapshot(error = TRUE, {
    vec_ptype2(x, y)
  })
  expect_snapshot(error = TRUE, {
    vec_ptype2(y, x)
  })
})`

const rtdal009837Source0008 = `test_that("can cast IDate to IDate", {
  x <- as_IDate_with_names(c(a = "2019-01-01"))
  expect_identical(vec_cast(x, x), x)
})`

const rtdal009837Source0009 = `test_that("can't cast Date to IDate", {
  x <- as.Date("2019-01-01")
  y <- as.IDate("2019-01-01")

  expect_snapshot(error = TRUE, {
    vec_cast(x, y)
  })
})`

const rtdal009837Source0010 = `test_that("can't cast IDate to Date", {
  x <- as.IDate("2019-01-01")
  y <- as.Date("2019-01-01")

  expect_snapshot(error = TRUE, {
    vec_cast(x, y)
  })
})`

const rtdal009837Source0011 = `test_that("vec_proxy", {
  # Retains integer type https://github.com/r-lib/vctrs/issues/1961
  x <- as.IDate("2019-01-01")
  expect_identical(vec_proxy(x), x)
})`

const rtdal009837Source0012 = `test_that("vec_restore", {
  x <- as.IDate("2019-01-01")
  proxy <- vec_proxy(x)
  expect_identical(vec_restore(proxy, x), x)
})`

const rtdal009837Source0013 = `test_that("proxy / restore retains names", {
  x <- as_IDate_with_names(c(a = "2019-01-01"))

  proxy <- vec_proxy(x)
  expect_named(proxy, "a")

  restored <- vec_restore(proxy, x)
  expect_named(restored, "a")
})`

const rtdal009837Source0014 = `test_that("vec_proxy_equal, vec_proxy_compare, vec_proxy_order", {
  # Doesn't change type, stays integer storage as well
  x <- as.IDate("2019-01-01")

  expect_identical(vec_proxy_equal(x), x)
  expect_identical(vec_proxy_compare(x), x)
  expect_identical(vec_proxy_order(x), x)
})`

const rtdal009837Source0015 = `test_that("ptype retains integer type", {
  x <- as.IDate(c("2019-01-01", "2019-01-02"))
  expect_identical(typeof(vec_ptype(x)), "integer")
  expect_identical(vec_ptype(x), as.IDate(integer()))
})`

const rtdal009837Source0016 = `test_that("slicing retains integer type", {
  x <- as.IDate(c("2019-01-01", "2019-01-02"))
  expect_identical(typeof(vec_slice(x, 1)), "integer")
})`

const rtdal009837Source0017 = `test_that("slicing retains names", {
  x <- as_IDate_with_names(c(a = "2019-01-01"))
  expect_identical(vec_slice(x, 1), x)
})`

