const rtdal009844Source0004 = `test_that("sf has a ptype2 method", {
  sfc1 = st_sfc(st_point(1:2), st_point(3:4))
  sfc2 = st_sfc(st_linestring(matrix(1:4, 2)))

  sf1 = st_sf(x = c(TRUE, FALSE), geo1 = sfc1)
  sf2 = st_sf(y = "", geo2 = sfc2, x = 0, stringsAsFactors = FALSE)

  out = vctrs::vec_ptype2(sf1, sf2)
  exp = st_sf(
    x = double(),
    y = character(),
    geo1 = sfc1[0],
    geo2 = sfc2[0],
    stringsAsFactors = FALSE
  )
  expect_identical(out, exp)

  out = vctrs::vec_ptype2(sf1, new_data_frame(sf2))
  expect_identical(out, exp)

  out = vctrs::vec_ptype2(new_data_frame(sf1), sf2)
  exp_rhs = st_sf(
    x = double(),
    y = character(),
    geo1 = sfc1[0],
    geo2 = sfc2[0],
    stringsAsFactors = FALSE,
    sf_column_name = "geo2"
  )
  expect_identical(out, exp_rhs)
})`

const rtdal009844Source0005 = `test_that("sf has a cast method", {
  sfc1 = st_sfc(st_point(1:2), st_point(3:4))
  sfc2 = st_sfc(st_linestring(matrix(1:4, 2)))

  sf1 = st_sf(x = c(TRUE, FALSE), geo1 = sfc1)
  sf2 = st_sf(y = "", geo2 = sfc2, x = 0, stringsAsFactors = FALSE)

  expect_error(
    vctrs::vec_cast(sf1, sf2),
    class = "vctrs_error_cast_lossy"
  )
  expect_error(
    vctrs::vec_cast(sf2, sf1),
    class = "vctrs_error_cast_lossy"
  )

  common = vec_ptype2(sf1, sf2)

  out = vctrs::vec_cast(sf1, common)
  exp = st_sf(
    x = c(1, 0),
    y = character(2)[NA],
    geo1 = sfc1,
    geo2 = sfc2[c(NA, NA) + 0L],
    stringsAsFactors = FALSE
  )
  expect_identical(out, exp)

  out = vctrs::vec_cast(new_data_frame(sf1), common)
  expect_identical(out, exp)

  out = vctrs::vec_cast(sf1, new_data_frame(common))
  expect_identical(out, new_data_frame(exp))

  out = vctrs::vec_cast(sf2, common)
  exp = st_sf(
    x = 0,
    y = "",
    geo1 = sfc1[NA + 0L],
    geo2 = sfc2,
    stringsAsFactors = FALSE
  )
  expect_identical(out, exp)
})`

const rtdal009844Source0006 = `test_that("can combine sf data frames", {
  testthat_import_from("dplyr", "bind_rows")

  sfc1 = st_sfc(st_point(1:2), st_point(3:4))
  sfc2 = st_sfc(st_linestring(matrix(1:4, 2)))

  sf1 = st_sf(x = c(TRUE, FALSE), geo1 = sfc1)
  sf2 = st_sf(y = "", geo2 = sfc2, x = 0, stringsAsFactors = FALSE)

  exp = data_frame(
    x = c(1, 0, 0),
    geo1 = sfc1[c(1:2, NA)],
    y = c(NA, NA, ""),
    geo2 = sfc2[c(NA, NA, 1)]
  )
  expect_identical(vctrs::vec_rbind(sf1, sf2), exp)
  expect_identical(bind_rows(sf1, sf2), st_as_sf(exp))

  exp = data_frame(
    y = c("", NA, NA, ""),
    x = c(0, 1, 0, 0),
    geo2 = sfc2[c(1, NA, NA, 1)],
    geo1 = sfc1[c(NA, 1:2, NA)]
  )
  expect_identical(vctrs::vec_rbind(sf2, sf1, sf2), exp)
  expect_identical(bind_rows(sf2, sf1, sf2), st_as_sf(exp))
})`

const rtdal009844Source0007 = `test_that("can combine sf and tibble", {
  sfc1 = st_sfc(st_point(1:2), st_point(3:4))
  sfc2 = st_sfc(st_linestring(matrix(1:4, 2)))

  sf1 = st_sf(x = c(TRUE, FALSE), geo1 = sfc1)
  sf2 = st_sf(y = "", geo2 = sfc2, x = 0, stringsAsFactors = FALSE)

  out = vctrs::vec_rbind(sf2, data.frame(x = 1))
  exp = data_frame(
    y = c("", NA),
    x = c(0, 1),
    geo2 = sfc2[c(1L, NA)]
  )
  expect_identical(out, exp)

  out = vctrs::vec_rbind(sf2, tibble::tibble(x = 1))
  expect_identical(out, exp)

  out = vctrs::vec_rbind(tibble::tibble(x = 1), sf2)
  exp = data_frame(
    x = c(1, 0),
    y = c(NA, ""),
    geo2 = sfc2[c(NA, 1L)]
  )
  expect_identical(out, exp)
})`

const rtdal009844Source0008 = "test_that(\"can combine sfc lists\", {\n  ls <- st_linestring(matrix(1:3, ncol = 3))\n\n  sfc <- st_sfc(ls)\n  expect_identical(vec_c(sfc, sfc), c(sfc, sfc))\n\n  sf <- st_as_sf(data.frame(id = 1, geometry = sfc))\n\n  # Currently returns a bare data frame because of the workaround for\n  # the `c()` fallback sentinels\n  expect_identical(vec_rbind(sf, sf), new_data_frame(rbind(sf, sf)))\n  expect_identical(vec_rbind(sf, sf, sf), new_data_frame(rbind(sf, sf, sf)))\n})"

const rtdal009844Source0009 = `test_that("can combine sfc lists with unspecified chunks", {
  point <- st_point(1:2)
  out <- vec_c(c(NA, NA), st_sfc(point), NA)
  expect_identical(out, st_sfc(NA, NA, point, NA))

  multipoint <- st_multipoint(matrix(1:4, 2))
  x <- st_sfc(point)
  y <- st_sfc(multipoint, multipoint)
  out <- vec_rbind(
    data_frame(x = x),
    data_frame(y = y)
  )
  expect_identical(
    out,
    data_frame(
      x = st_sfc(point, NA, NA),
      y = st_sfc(NA, multipoint, multipoint)
    )
  )
})`

