const rtdal009845Source0016 = `test_that("can cast from, but not to, unspecified", {
  x <- new_table()

  expect_error(vec_cast(x, NA), class = "vctrs_error_incompatible_type")
  expect_identical(vec_cast(NA, x), new_table(NA_integer_, dim = 1L))

  x <- new_table(dim = c(0L, 2L))

  expect_error(vec_cast(x, NA), class = "vctrs_error_incompatible_type")
  expect_identical(
    vec_cast(NA, x),
    new_table(c(NA_integer_, NA_integer_), dim = c(1L, 2L))
  )
})`

const rtdal009845Source0017 = "test_that(\"`table` delegates casting\", {\n  expect_identical(\n    vec_cast(new_table(1), new_table(FALSE)),\n    new_table(TRUE)\n  )\n  expect_error(\n    vec_cast(new_table(1), new_table(\"\")),\n    class = \"vctrs_error_incompatible_type\"\n  )\n})"

const rtdal009845Source0018 = "test_that(\"`new_table()` validates input\", {\n  expect_error(new_table(1L, 1), \"`dim` must be an integer vector\")\n  expect_error(new_table(1:2, 1L), \"must match the length of `x`\")\n})"

const rtdal009845Source0019 = `test_that("ptype is correct", {
  tab1 <- new_table(1L, dim = 1L)
  tab2 <- new_table(1:2, dim = c(1L, 2L, 1L))

  expect_identical(vec_ptype(tab1), new_table())
  expect_identical(vec_ptype(tab2), new_table(dim = c(0L, 2L, 1L)))
})`

const rtdal009845Source0020 = "test_that(\"can use a table in `vec_c()`\", {\n  expect_identical(vec_c(new_table()), new_table())\n  expect_identical(vec_c(new_table(), new_table()), new_table())\n\n  x <- new_table(1:5, 5L)\n  y <- new_table(1:4, dim = c(2L, 2L))\n\n  expect_identical(vec_c(x, x), new_table(c(1:5, 1:5), dim = 10L))\n  expect_identical(\n    vec_c(y, y),\n    new_table(c(1:2, 1:2, 3:4, 3:4), dim = c(4L, 2L))\n  )\n  expect_identical(\n    vec_c(x, y),\n    new_table(c(1:5, 1:2, 1:5, 3:4), dim = c(7L, 2L))\n  )\n})"

const rtdal009845Source0021 = "test_that(\"names of the first dimension are kept in `vec_c()`\", {\n  x <- new_table(1:4, c(2L, 2L))\n  dimnames(x) <- list(c(\"r1\", \"r2\"), c(\"c1\", \"c2\"))\n\n  xx <- vec_c(x, x)\n\n  expect_identical(dimnames(xx), list(c(\"r1\", \"r2\", \"r1\", \"r2\"), NULL))\n})"

const rtdal009845Source0022 = "test_that(\"can use a table in `list_unchop()`\", {\n  x <- new_table(1:4, dim = c(2L, 2L))\n\n  expect_identical(list_unchop(list(x)), x)\n  expect_identical(\n    list_unchop(list(x, x), indices = list(1:2, 4:3)),\n    vec_slice(x, c(1:2, 2:1))\n  )\n})"

const rtdal009845Source0023 = "test_that(\"can concatenate tables\", {\n  x <- table(1:2)\n\n  out <- vec_c(x, x)\n  exp <- new_table(rep(1L, 4), dimnames = list(c(\"1\", \"2\", \"1\", \"2\")))\n  expect_identical(out, exp)\n\n  out <- vec_rbind(x, x)\n  exp <- data_frame(`1` = new_table(c(1L, 1L)), `2` = new_table(c(1L, 1L)))\n  expect_identical(out, exp)\n\n  y <- table(list(1:2, 3:4))\n\n  # FIXME\n  out <- vec_c(y, y)\n  exp <- new_table(\n    matrix(int(1, 0, 1, 0, 0, 1, 0, 1), nrow = 4),\n    dim = c(4L, 2L),\n    dimnames = list(c(\"1\", \"2\", \"1\", \"2\"), NULL)\n  )\n  expect_identical(out, exp)\n\n  out <- vec_rbind(y, y)\n  exp <- new_data_frame(\n    list(\n      `3` = int(1, 0, 1, 0),\n      `4` = int(0, 1, 0, 1)\n    ),\n    row.names = c(\"1...1\", \"2...2\", \"1...3\", \"2...4\")\n  )\n  expect_identical(out, exp)\n\n  skip(\"FIXME: dimnames of matrices are not properly concatenated\")\n})"

const rtdal009845Source0024 = "test_that(\"can concatenate tables of type double (#1190)\", {\n  x <- table(c(1, 2)) / 2\n\n  out <- vec_c(x, x)\n  exp <- new_table(\n    c(0.5, 0.5, 0.5, 0.5),\n    dimnames = list(c(\"1\", \"2\", \"1\", \"2\"))\n  )\n  expect_identical(out, exp)\n\n  out <- vec_rbind(x, x)\n  exp <- data_frame(`1` = new_table(c(0.5, 0.5)), `2` = new_table(c(0.5, 0.5)))\n  expect_identical(out, exp)\n})"

