const rtdal009873Source0001 = `test_that("can warp_distance() by year with Date", {
  x <- as.Date("1970-01-01")
  expect_identical(warp_distance(x, "year"), 0)

  x <- as.Date("1971-01-01")
  expect_identical(warp_distance(x, "year"), 1)
})`

const rtdal009873Source0002 = `test_that("can warp_distance() by year with 'negative' Dates", {
  x <- as.Date("1969-01-01")
  expect_identical(warp_distance(x, "year"), -1)
})`

const rtdal009873Source0003 = `test_that("Date + UTC origin does not emit a warning", {
  x <- as.Date("1971-01-01")
  origin <- as.POSIXct("1971-01-01", tz = "UTC")

  expect_identical(warp_distance(x, "year", origin = origin), 0)
})`

const rtdal009873Source0004 = `test_that("Date + non-UTC origin converts with a warning", {
  x <- as.Date("1971-01-01")
  x_with_tz <- structure(
    unclass(x) * 86400,
    tzone = "America/New_York",
    class = c("POSIXct", "POSIXt")
  )
  origin <- as.POSIXct("1971-01-01", tz = "America/New_York")

  expect_snapshot({
    out <- warp_distance(x, "year", origin = origin)
  })
  expect_identical(out, warp_distance(x_with_tz, "year", origin = origin))
})`

const rtdal009873Source0005 = `test_that("can use integer Dates", {
  x <- structure(0L, class = "Date")
  expect_identical(warp_distance(x, "year"), 0)
})`

const rtdal009873Source0006 = "test_that(\"can handle `NA` dates\", {\n  x <- structure(NA_real_, class = \"Date\")\n  expect_identical(warp_distance(x, \"year\"), NA_real_)\n\n  x <- structure(NA_integer_, class = \"Date\")\n  expect_identical(warp_distance(x, \"year\"), NA_real_)\n})"

const rtdal009873Source0007 = "test_that(\"can handle `every` with default origin\", {\n  x <- as.Date(c(\n    \"1967-01-01\",\n    \"1968-01-01\",\n    \"1969-01-01\",\n    \"1970-01-01\",\n    \"1971-01-01\",\n    \"1972-01-01\",\n    \"1973-01-01\"\n  ))\n\n  expect_equal(\n    warp_distance(x, period = \"year\", every = 2L),\n    c(-2, -1, -1, 0, 0, 1, 1)\n  )\n  expect_equal(\n    warp_distance(x, period = \"year\", every = 3L),\n    c(-1, -1, -1, 0, 0, 0, 1)\n  )\n  expect_equal(\n    warp_distance(x, period = \"year\", every = 4L),\n    c(-1, -1, -1, 0, 0, 0, 0)\n  )\n})"

const rtdal009873Source0008 = "test_that(\"can handle `every` with altered origin\", {\n  x <- as.Date(c(\n    \"1967-01-01\",\n    \"1968-01-01\",\n    \"1969-01-01\",\n    \"1970-01-01\",\n    \"1971-01-01\",\n    \"1972-01-01\",\n    \"1973-01-01\"\n  ))\n\n  origin <- as.Date(\"1971-01-01\")\n\n  expect_equal(\n    warp_distance(x, period = \"year\", every = 2L, origin = origin),\n    c(-2, -2, -1, -1, 0, 0, 1)\n  )\n  expect_equal(\n    warp_distance(x, period = \"year\", every = 3L, origin = origin),\n    c(-2, -1, -1, -1, 0, 0, 0)\n  )\n  expect_equal(\n    warp_distance(x, period = \"year\", every = 4L, origin = origin),\n    c(-1, -1, -1, -1, 0, 0, 0)\n  )\n})"

