const rtdal009873Source0056 = "test_that(\"can handle `every` with altered origin\", {\n  x <- as.Date(c(\n    \"1969-12-02\",\n    \"1969-12-09\",\n    \"1969-12-16\",\n    \"1969-12-23\",\n    \"1969-12-30\",\n    \"1969-12-31\",\n    \"1970-01-01\",\n    \"1970-01-06\",\n    \"1970-01-07\",\n    \"1970-01-08\",\n    \"1970-01-15\",\n    \"1970-01-22\"\n  ))\n\n  origin <- as.Date(\"1970-01-08\")\n\n  expect_equal(\n    warp_distance(x, period = \"yweek\", every = 2L, origin = origin),\n    c(-4, -4, -3, -3, -2, -2, -2, -2, -1, 0, 0, 1)\n  )\n  expect_equal(\n    warp_distance(x, period = \"yweek\", every = 3L, origin = origin),\n    c(-3, -3, -2, -2, -2, -1, -1, -1, -1, 0, 0, 0)\n  )\n  expect_equal(\n    warp_distance(x, period = \"yweek\", every = 4L, origin = origin),\n    c(-3, -3, -2, -2, -2, -2, -2, -2, -1, 0, 0, 0)\n  )\n})"

