const rtdal009873Source0077 = "test_that(\"default `origin` results in epoch in the time zone of `x`\", {\n  x <- as.POSIXct(\"1969-12-31 23:00:00\", tz = \"America/New_York\")\n  y <- as.POSIXct(\"1969-12-31 23:00:00\", tz = \"UTC\")\n\n  expect_equal(\n    warp_distance(x, period = \"yweek\"),\n    warp_distance(y, period = \"yweek\")\n  )\n})"

const rtdal009873Source0078 = "test_that(\"`origin` value can be on the leap day\", {\n  origin <- as.POSIXct(\"2000-02-29\", \"UTC\")\n\n  # Non-leap years start that group on 02/28\n  x <- as.POSIXct(\n    c(\n      \"1999-02-27\",\n      \"1999-02-28\",\n      \"1999-03-01\",\n      \"1999-03-02\",\n      \"1999-03-07\",\n      \"1999-03-08\"\n    ),\n    \"UTC\"\n  )\n  y <- as.POSIXct(\n    c(\n      \"2000-02-27\",\n      \"2000-02-28\",\n      \"2000-02-29\",\n      \"2000-03-01\",\n      \"2000-03-02\",\n      \"2000-03-07\",\n      \"2000-03-08\"\n    ),\n    \"UTC\"\n  )\n  z <- as.POSIXct(\n    c(\n      \"2001-02-27\",\n      \"2001-02-28\",\n      \"2001-03-01\",\n      \"2001-03-02\",\n      \"2001-03-07\",\n      \"2001-03-08\"\n    ),\n    \"UTC\"\n  )\n\n  # 1998-02-28 -> 1999-02-27 = 52 full weeks\n  # [1999-02-27, 1999-02-28) = -54\n  # [1999-02-28, 1999-03-07) = -53\n  # [1999-03-07, 1999-03-15) = -52\n  expect_identical(\n    warp_distance(x, period = \"yweek\", every = 1, origin = origin),\n    c(-54, -53, -53, -53, -52, -52)\n  )\n\n  # 1999-02-28 -> 2000-02-27 = 52 full weeks\n  # [2000-02-27, 2000-02-29) = -1\n  # [2000-02-29, 2000-03-07) = 0\n  # [2000-03-07, 2000-03-15) = 1\n  expect_identical(\n    warp_distance(y, period = \"yweek\", every = 1, origin = origin),\n    c(-1, -1, 0, 0, 0, 1, 1)\n  )\n\n  # 2000-02-29 -> 2001-02-27 = 52 full weeks\n  # [2001-02-27, 2001-02-28) = 52\n  # [2001-02-28, 2001-03-07) = 53\n  # [2001-03-07, 2001-03-15) = 54\n  expect_identical(\n    warp_distance(z, period = \"yweek\", every = 1, origin = origin),\n    c(52, 53, 53, 53, 54, 54)\n  )\n})"

