const rtdal009873Source0093 = "test_that(\"can handle `every` with default origin\", {\n  x <- as.Date(c(\n    \"1968-12-31\",\n    \"1969-01-01\",\n    \"1969-11-30\",\n    \"1969-12-01\",\n    \"1969-12-28\",\n    \"1969-12-29\",\n    \"1969-12-30\",\n    \"1969-12-31\",\n    \"1970-01-01\",\n    \"1970-01-02\",\n    \"1970-01-03\"\n  ))\n\n  expect_equal(\n    warp_distance(x, period = \"mday\", every = 2L),\n    c(-187, -186, -17, -16, -3, -2, -2, -1, 0, 0, 1)\n  )\n  expect_equal(\n    warp_distance(x, period = \"mday\", every = 3L),\n    c(-128, -127, -12, -11, -2, -2, -2, -1, 0, 0, 0)\n  )\n  expect_equal(\n    warp_distance(x, period = \"mday\", every = 4L),\n    c(-96, -95, -9, -8, -2, -1, -1, -1, 0, 0, 0)\n  )\n})"

const rtdal009873Source0094 = "test_that(\"can handle `every` with altered origin\", {\n  x <- as.Date(c(\n    \"1968-12-31\",\n    \"1969-01-01\",\n    \"1969-11-30\",\n    \"1969-12-01\",\n    \"1969-12-28\",\n    \"1969-12-29\",\n    \"1969-12-30\",\n    \"1969-12-31\",\n    \"1970-01-01\",\n    \"1970-01-02\",\n    \"1970-01-03\"\n  ))\n\n  origin <- as.Date(\"1969-12-01\")\n\n  expect_equal(\n    warp_distance(x, period = \"mday\", every = 2L, origin = origin),\n    c(-171, -170, -1, 0, 13, 14, 14, 15, 16, 16, 17)\n  )\n  expect_equal(\n    warp_distance(x, period = \"mday\", every = 3L, origin = origin),\n    c(-117, -116, -1, 0, 9, 9, 9, 10, 11, 11, 11)\n  )\n  expect_equal(\n    warp_distance(x, period = \"mday\", every = 4L, origin = origin),\n    c(-88, -87, -1, 0, 6, 7, 7, 7, 8, 8, 8)\n  )\n})"

