const rtdal009873Source0140 = "test_that(\"can handle `every` with altered origin - integer POSIXct\", {\n  x <- as.POSIXct(\n    c(\n      \"1969-12-29\",\n      \"1969-12-30\",\n      \"1969-12-31\",\n      \"1970-01-01\",\n      \"1970-01-02\",\n      \"1970-01-03\",\n      \"1970-01-04\"\n    ),\n    tz = \"UTC\"\n  )\n\n  x <- structure(as.integer(unclass(x)), tzone = \"UTC\", class = class(x))\n\n  origin <- as.Date(\"1970-01-02\")\n\n  expect_equal(\n    warp_distance(x, period = \"day\", every = 2L, origin = origin),\n    c(-2, -2, -1, -1, 0, 0, 1)\n  )\n  expect_equal(\n    warp_distance(x, period = \"day\", every = 3L, origin = origin),\n    c(-2, -1, -1, -1, 0, 0, 0)\n  )\n  expect_equal(\n    warp_distance(x, period = \"day\", every = 4L, origin = origin),\n    c(-1, -1, -1, -1, 0, 0, 0)\n  )\n})"

