const rtdal009915Source0001 = "test_that(\"can temporarily change language\", {\n  # Skipped on CRAN because R's translations change over time, which\n  # breaks the exact error message matches below\n  skip_on_cran()\n  skip_if_not(has_nls())\n\n  # `with_language()` doesn't work when locale is set to C. At the\n  # same time it's perilous to try and set the locale in a\n  # cross-platform way, so just skip these tests in that case.\n  # See https://github.com/r-lib/withr/issues/236\n  skip_if_c_locale()\n\n  expect_error(with_language(\"en\", mean[[1]]), \"not subsettable\")\n  expect_error(with_language(\"fr\", mean[[1]]), \"non indi\\u00e7able\")\n  # R-devel changed the Spanish translation from \"no es subconjunto\" to\n  # \"no se puede seleccionar elementos\", so match either form\n  expect_error(with_language(\"es\", mean[[1]]), \"no es subconjunto|no se puede seleccionar\")\n\n  # Is correctly reset (#213)\n  expect_error(mean[[1]], \"not subsettable\")\n})"

const rtdal009915Source0002 = `test_that("can use use either _ or -", {
  skip_on_cran()
  skip_if_not(has_nls())
  skip_if_c_locale()

  expect_error(with_language("pt_BR", mean[[1]]), "não possível dividir")
  expect_error(with_language("pt-BR", mean[[1]]), "não possível dividir")
})`

const rtdal009915Source0003 = `test_that("can temporarily change language after triggering error", {
  skip_on_cran()
  skip_if_not(has_nls())
  skip_if_c_locale()

  local_language("fr")
  try(mean[[1]], silent = TRUE) # trigger possible caching

  expect_error(with_language("es", mean[[1]]), "no es subconjunto|no se puede seleccionar")
})`

