const rtdal009924Source0006 = "test_that(\"local_seed preserves empty seed (#286)\", {\n  rm_seed()\n  local({\n    local_seed(1)\n    runif(1)\n  })\n  # `.Random.seed` must be truly absent, not present-but-`NULL`. A `NULL`\n  # value reads as no seed to `has_seed()` (it checks `mode = \"integer\"`),\n  # but makes the next RNG draw warn that `.Random.seed` is not an integer.\n  expect_false(exists(\".Random.seed\", globalenv(), inherits = FALSE))\n  expect_no_warning(runif(1))\n})"

const rtdal009924Source0007 = `test_that("RNGkind is also respected", {
  old <- RNGkind()
  on.exit(do.call("RNGkind", as.list(old)))


  # Uniform RNG

  my_seed <- sample.int(.Machine$integer.max, 1)
  rng_kind <- "Mersenne-Twister"
  alt_rng_kind <- "L'Ecuyer-CMRG"

  RNGkind(rng_kind)
  set.seed(my_seed)
  reference <- runif(10)

  RNGkind(alt_rng_kind)
  set.seed(my_seed)
  alt_reference <- runif(10)

  RNGkind(rng_kind)
  expect_equal(
    with_seed(my_seed, {
      expect_equal(RNGkind()[[1]], rng_kind)
      runif(10)
    }),
    reference
  )
  expect_equal(RNGkind()[[1]], rng_kind)

  RNGkind(alt_rng_kind)
  expect_equal(
    with_seed(my_seed, {
      expect_equal(RNGkind()[[1]], alt_rng_kind)
      runif(10)
    }),
    alt_reference
  )
  expect_equal(RNGkind()[[1]], alt_rng_kind)

  RNGkind(rng_kind)
  expect_equal(
    with_seed(
      my_seed,
      {
        expect_equal(RNGkind()[[1]], alt_rng_kind)
        runif(10)
      },
      .rng_kind = alt_rng_kind
    ),
    alt_reference
  )
  expect_equal(RNGkind()[[1]], rng_kind)


  # Normal RNG

  rng_norm_kind <- "Box-Muller"
  alt_rng_norm_kind <- "Kinderman-Ramage"

  RNGkind(normal.kind = rng_norm_kind)
  set.seed(my_seed)
  norm_reference <- rnorm(10)

  RNGkind(normal.kind = alt_rng_norm_kind)
  set.seed(my_seed)
  alt_norm_reference <- rnorm(10)

  expect_equal(
    with_seed(my_seed, rnorm(10)),
    alt_norm_reference
  )

  expect_equal(
    with_seed(
      my_seed,
      .rng_normal_kind = alt_rng_norm_kind,
      rnorm(10)
    ),
    alt_norm_reference
  )

  expect_equal(
    with_seed(
      my_seed,
      .rng_normal_kind = rng_norm_kind,
      rnorm(10)
    ),
    norm_reference
  )

  expect_equal(
    with_preserve_seed(rnorm(10)),
    with_preserve_seed(rnorm(10))
  )

  # Beware: Box-Muller generates pairs, that state is lost across set.seed()!
  RNGkind(normal.kind = rng_norm_kind)
  rnorm(1)
  expect_failure(expect_equal(
    with_preserve_seed(rnorm(10)),
    with_preserve_seed(rnorm(10))
  ))
})`

