const rtdal009926Source0001 = `test_that("defer_parent works", {
  local_file <- function(path) {
    file.create(path)
    defer_parent(unlink(path))
  }

  # create tempfile path
  path <- tempfile()

  # use 'local_file' in a function
  local({
    local_file(path)
    stopifnot(file.exists(path))
  })

  # file is deleted as we leave 'local' scope
  expect_false(file.exists(path))
})`

const rtdal009926Source0002 = `test_that("defer()'s global env facilities work", {
  skip_if_not_installed("testthat", "3.2.0")

  expect_length(the$global_exits, 0)

  local_options(rlang_interactive = TRUE)
  Sys.setenv(abcdefg = "abcdefg")

  expect_snapshot(
    defer(print("howdy"), envir = globalenv()),
    cran = TRUE
  )
  expect_message(
    local_envvar(c(abcdefg = "tuvwxyz"), .local_envir = globalenv()),
    NA
  )

  h <- the$global_exits
  expect_length(h, 2)
  expect_equal(Sys.getenv("abcdefg"), "tuvwxyz")

  suppressMessages(
    expect_output(deferred_run(globalenv()), "howdy")
  )
  expect_equal(Sys.getenv("abcdefg"), "abcdefg")

  expect_message(defer(print("never going to happen"), envir = globalenv()))
  deferred_clear(globalenv())

  expect_length(the$global_exits, 0)
})`

const rtdal009926Source0003 = `test_that("non-top-level global env is unwound like a normal env", {
  expect_silent(
    evalq(local_options(list(opt = "foo")), globalenv())
  )

  # Check that handlers have been called
  expect_null(getOption("opt"))

  # Check that handlers were cleaned up
  expect_length(the$global_exits, 0)
})`

const rtdal009926Source0004 = `test_that("defered actions in global env are run on exit", {
  path <- local_tempfile()
  callr::r(
    function(path) {
      withr::defer(writeLines("a", path), env = globalenv())
    },
    list(path = path)
  )
  expect_equal(readLines(path), "a")
})`

const rtdal009926Source0005 = "test_that(\"defered actions in Rmd are run on exit\", {\n  skip_if_cannot_knit()\n\n  rmd <- local_tempfile(fileext = \".Rmd\")\n  path <- local_tempfile()\n  writeLines(rmd, text = c(\n    \"---\",\n    \"title: test\",\n    \"---\",\n    \"```{r}\",\n    paste0(\"withr::defer(writeLines('a', \", encodeString(path, quote = \"'\"), \"))\"),\n    \"```\"\n  ))\n  callr::r(function(path) rmarkdown::render(path), list(path = rmd))\n  expect_equal(readLines(path), \"a\")\n\n  # And check when run from globalenv\n  unlink(path)\n  callr::r(function(path) rmarkdown::render(path, envir = globalenv()), list(path = rmd))\n  expect_equal(readLines(path), \"a\")\n\n})"

const rtdal009926Source0006 = `test_that("defer executes all handlers even if there is an error in one of them", {

  old <- options("test_option" = 1)
  on.exit(options(old), add = TRUE)

  f <- function() {
    defer(stop("hi"))
    defer(options("test_option" = 2))
  }

  expect_equal(getOption("test_option"), 1)

  err <- tryCatch(f(), error = identity)

  expect_equal(conditionMessage(err), "hi")

  expect_equal(getOption("test_option"), 2)
})`

const rtdal009926Source0007 = `test_that("defer works within source()", {
  local_options(withr.hook_source = TRUE)

  file <- local_tempfile()
  out <- NULL

  local_defer <- function(frame = parent.frame()) {
    defer(out <<- c(out, "local_defer"), envir = frame)
  }

  cat(file = file, "
    out <<- c(out, '1')
    defer(out <<- c(out, 'defer'))
    out <<- c(out, '2')
    identity(defer(out <<- c(out, 'identity(defer)')))
    out <<- c(out, '3')
    local_defer()
    out <<- c(out, '4')
    evalq(defer(out <<- c(out, 'evalq(defer)')))
    out <<- c(out, '5')
  ")
  local(
    source(file, local = TRUE)
  )

  expect_equal(out, c(
    "1",
    "2",
    "3",
    "4",
    "evalq(defer)",
    "5",
    "local_defer",
    "identity(defer)",
    "defer"
  ))
})`

const rtdal009926Source0008 = `test_that("defer works within source()", {
  local_options(withr.hook_source = TRUE)

  out <- NULL

  file1 <- local_tempfile()
  file2 <- local_tempfile()

  cat(file = file1, "
    out <<- c(out, 'outer-1')
    defer(out <<- c(out, 'outer-before'))
    out <<- c(out, 'outer-2')
    local(source(file2, local = TRUE))
    defer(out <<- c(out, 'outer-after'))
    out <<- c(out, 'outer-3')
  ")
  cat(file = file2, "
    out <<- c(out, '1')
    defer(out <<- c(out, 'defer'))
    out <<- c(out, '2')
  ")

  local(
    source(file1, local = TRUE)
  )

  expect_equal(out, c(
    "outer-1",
    "outer-2",
    "1",
    "2",
    "defer",
    "outer-3",
    "outer-after",
    "outer-before"
  ))
})`

const rtdal009926Source0009 = `test_that("don't need to enable source for the global env", {
  local_options(withr.hook_source = NULL)

  file <- local_tempfile()

  cat(file = file, "
    writeLines('1')
    withr::defer(writeLines('deferred'))
    writeLines('2')
  ")

  expect_snapshot({
    source(file, local = globalenv())
  })
})`

const rtdal009926Source0010 = "test_that(\"defer works within knitr::knit()\", {\n  skip_if_not_installed(\"knitr\")\n  out <- NULL\n  evalq({\n    defer(out <- c(out, \"first\"))\n    rmd <- \"\n      ```{r}\n      defer(out <- c(out, 'defer 1'))\n      out <- c(out, '1')\n      local({\n        withr::defer(out <<- c(out, 'local 1'))\n      })\n      ```\n      ```{r}\n      defer(out <- c(out, 'defer 2'))\n      out <- c(out, '2')\n      local({\n        withr::defer(out <<- c(out, 'local 2'))\n      })\n      ```\n    \"\n    knitr::knit(text = rmd, quiet = TRUE)\n    defer(out <- c(out, \"last\"))\n  })\n  expect_equal(out, c(\n    \"1\",\n    \"local 1\",\n    \"2\",\n    \"local 2\",\n    \"defer 2\",\n    \"defer 1\",\n    \"last\",\n    \"first\"\n  ))\n})"

const rtdal009926Source0011 = `test_that("defer() and on.exit() handlers can be meshed", {
  out <- list()

  local({
    on.exit(out <<- append(out, 1), add = TRUE)
    defer(out <<- append(out, 2))
    on.exit(out <<- append(out, 3), add = TRUE)
    on.exit(out <<- append(out, 4), add = TRUE, after = FALSE)
    defer(out <<- append(out, 5), priority = "last")
  })

  expect_equal(out, list(4, 2, 1, 3, 5))
})`

