const rtdal009949Source0001 = `grd <- function(bbox = NULL, nx = NULL, ny = NULL, dx = NULL, dy = NULL,
                type = c("polygons", "corners", "centers")) {
  if (is.null(bbox)) {
    bbox <- NULL
  } else if (inherits(bbox, "wk_rct")) {
    bbox
  } else {
    wk_bbox(bbox)
  }
  type <- match.arg(type)

  if (is.null(nx) && is.null(ny) && !is.null(dx) && !is.null(dy) && !is.null(bbox)) {
    rct <- unclass(bbox)
    width <- rct$xmax - rct$xmin
    height <- rct$ymax - rct$ymin

    if (type == "polygons") {
      nx <- width / dx
      ny <- height / dy
    } else if (type == "corners") {
      nx <- width / dx + 1
      ny <- height / dy + 1
    } else if (type == "centers") {
      nx <- width / dx
      ny <- height / dy
      bbox <- rct(
        rct$xmin + dx / 2,
        rct$ymin + dy / 2,
        rct$xmax - dx / 2,
        rct$ymax - dy / 2,
        crs = wk_crs(bbox)
      )
    }
  } else if (is.null(dx) && is.null(dy) && !is.null(nx) && !is.null(ny)) {
    if (is.null(bbox)) {
      bbox <- rct(0, 0, nx, ny)
    }

    nx <- nx
    ny <- ny

    if (type == "centers") {
      rct <- unclass(bbox)
      width <- rct$xmax - rct$xmin
      height <- rct$ymax - rct$ymin
      dx <- width / nx
      dy <- height / ny

      bbox <- rct(
        rct$xmin + dx / 2,
        rct$ymin + dy / 2,
        rct$xmax - dx / 2,
        rct$ymax - dy / 2,
        crs = wk_crs(bbox)
      )
    } else if (type == "corners") {
      nx <- nx + 1
      ny <- ny + 1
    }
  } else {
    stop(
      "Must specify dx, dy, and bbox OR nx and ny.",
      call. = FALSE
    )
  }

  # use a length-zero logical() with correct x and y dims
  data <- array(dim = c(ny, nx, 0))

  if (type == "polygons") {
    grd_rct(data, bbox)
  } else {
    grd_xy(data, bbox)
  }
}`

const rtdal009949Source0002 = `grd_rct <- function(data, bbox = rct(0, 0, dim(data)[2], dim(data)[1])) {
  bbox <- if (inherits(bbox, "wk_rct")) bbox else wk_bbox(bbox)

  # normalize data and bbox so that max > min
  normalized <- grd_internal_normalize(data, bbox)
  data <- normalized[[1]]
  bbox <- normalized[[2]]

  # with zero values, bbox in that direction is empty
  rct <- unclass(bbox)
  if (dim(data)[2] == 0) {
    rct$xmin <- Inf
    rct$xmax <- -Inf
  }

  if (dim(data)[1] == 0) {
    rct$ymin <- Inf
    rct$ymax <- -Inf
  }

  bbox <- new_wk_rct(rct, crs = wk_crs(bbox))

  new_wk_grd(list(data = data, bbox = bbox), "wk_grd_rct")
}`

const rtdal009949Source0003 = `grd_xy <- function(data, bbox = rct(0, 0, dim(data)[2] - 1, dim(data)[1] - 1)) {
  bbox <- if (inherits(bbox, "wk_rct")) bbox else wk_bbox(bbox)

  # normalize data and bbox so that max > min
  normalized <- grd_internal_normalize(data, bbox)
  data <- normalized[[1]]
  bbox <- normalized[[2]]

  # with zero values, bbox in that direction is empty
  rct <- unclass(bbox)
  if (dim(data)[2] == 0) {
    rct$xmin <- Inf
    rct$xmax <- -Inf
  }

  if (dim(data)[1] == 0) {
    rct$ymin <- Inf
    rct$ymax <- -Inf
  }

  bbox <- new_wk_rct(rct, crs = wk_crs(bbox))

  # with one value in the x dimension, we need a zero width bbox
  if (dim(data)[2] == 1) {
    stopifnot(
      unclass(bbox)$xmax == unclass(bbox)$xmin
    )
  }

  # with one value in the y dimension, we need a zero height bbox
  if (dim(data)[1] == 1) {
    stopifnot(
      unclass(bbox)$ymax == unclass(bbox)$ymin
    )
  }

  new_wk_grd(list(data = data, bbox = bbox), "wk_grd_xy")
}`

const rtdal009949Source0004 = `as_grd_rct <- function(x, ...) {
  UseMethod("as_grd_rct")
}`

const rtdal009949Source0005 = `as_grd_rct.wk_grd_rct <- function(x, ...) {
  x
}`

const rtdal009949Source0006 = `as_grd_rct.wk_grd_xy <- function(x, ...) {
  # from a grd_xy, we assume these were the centres
  s <- grd_summary(x)

  bbox <- rct(
    s$xmin - s$dx / 2,
    s$ymin - s$dy / 2,
    s$xmax + s$dx / 2,
    s$ymax + s$dy / 2,
    crs = wk_crs(x$bbox)
  )

  grd_rct(x$data, bbox = bbox)
}`

const rtdal009949Source0007 = `as_grd_xy <- function(x, ...) {
  UseMethod("as_grd_xy")
}`

const rtdal009949Source0008 = `as_grd_xy.wk_grd_xy <- function(x, ...) {
  x
}`

const rtdal009949Source0009 = `as_grd_xy.wk_grd_rct <- function(x, ...) {
  # from a grid_rct() we take the centers
  s <- grd_summary(x)

  bbox <- rct(
    s$xmin + s$dx / 2,
    s$ymin + s$dy / 2,
    s$xmax - s$dx / 2,
    s$ymax - s$dy / 2,
    crs = wk_crs(x$bbox)
  )

  grd_xy(x$data, bbox = bbox)
}`

const rtdal009949Source0013 = `grd_summary.wk_grd_xy <- function(grid) {
  nx <- dim(grid$data)[2]
  ny <- dim(grid$data)[1]
  rct <- unclass(grid$bbox)
  width <- rct$xmax - rct$xmin
  height <- rct$ymax - rct$ymin
  dx <- if (nx > 1) width / (nx - 1) else 0
  dy <- if (ny > 1) height / (ny - 1) else 0

  list(
    xmin = rct$xmin,
    ymin = rct$ymin,
    xmax = rct$xmax,
    ymax = rct$ymax,
    nx = nx,
    ny = ny,
    dx = dx,
    dy = dy,
    width = width,
    height = height
  )
}`

const rtdal009949Source0014 = `wk_bbox.wk_grd <- function(handleable, ...) {
  handleable$bbox
}`

const rtdal009949Source0017 = "`[[<-.wk_grd` <- function(x, i, value) {\n  x_bare <- unclass(x)\n  if (identical(i, \"data\")) {\n    stopifnot(length(dim(value)) >= 2)\n    x_bare$data <- value\n  } else if (identical(i, \"bbox\")) {\n    if (inherits(value, \"wk_rct\")) {\n      # normalize so that max > min, but empty (Inf -Inf) is OK\n      rct <- unclass(value)\n\n      # missings make no sense in this context\n      if (any(vapply(rct, is.na, logical(1)))) {\n        stop(\"Can't set missing bounding box for grd objects\", call. = FALSE)\n      }\n\n      if ((rct$xmin > rct$xmax) && (rct$xmin != Inf) && (rct$xmax != -Inf)) {\n        rct[c(\"xmin\", \"xmax\")] <- rct[c(\"xmax\", \"xmin\")]\n      }\n      if ((rct$ymin > rct$ymax) && (rct$ymin != Inf) && (rct$ymax != -Inf)) {\n        rct[c(\"ymin\", \"ymax\")] <- rct[c(\"ymax\", \"ymin\")]\n      }\n\n      value <- new_wk_rct(rct, crs = wk_crs(value))\n    } else {\n      value <- wk_bbox(value)\n    }\n\n    x_bare$bbox <- value\n  } else {\n    stop(\"Can't set element of a grd that is not 'data' or 'bbox'\", call. = FALSE)\n  }\n\n  class(x_bare) <- class(x)\n  x_bare\n}"

const rtdal009949Source0020 = "`[.wk_grd` <- function(x, i, j, ..., drop = FALSE) {\n  # for this method we never drop dimensions (can use $data[] to do this)\n  stopifnot(identical(drop, FALSE))\n\n  bbox <- NULL\n\n  if (missing(i)) {\n    i <- NULL\n  }\n\n  if (missing(j)) {\n    j <- NULL\n  }\n\n  # allow combination of i, j to be a rct() instead\n  if (inherits(i, \"wk_rct\") && is.null(j)) {\n    result_xy <- grd_crop(x, bbox = i)\n    if (length(dim(x$data)) > 2) {\n      result_xy$data <- result_xy$data[, , , ..., drop = FALSE]\n    } else {\n      result_xy$data <- result_xy$data[, , ..., drop = FALSE]\n    }\n  } else if (inherits(i, \"wk_rct\")) {\n    result_xy <- grd_crop(x, bbox = i)\n    result_xy$data <- result_xy$data[, , j, ..., drop = FALSE]\n  } else {\n    result_xy <- grd_subset(x, i = i, j = j)\n    result_xy$data <- result_xy$data[, , ..., drop = FALSE]\n  }\n\n  result_xy\n}"

const rtdal009949Source0021 = `format.wk_grd <- function(x, ...) {
  crs <- wk_crs(x)
  sprintf(
    "<%s [%s] => %s%s>",
    class(x)[1],
    paste0(dim(x$data), collapse = " x "),
    wk_bbox(x),
    if (is.null(crs)) "" else paste0(" with crs=", format(crs))
  )
}`

const rtdal009949Source0022 = `print.wk_grd <- function(x, ...) {
  cat(paste0(format(x), "\n"))
  utils::str(x)
  invisible(x)
}`

const rtdal009949Source0023 = `grd_internal_normalize <- function(x, bbox) {
  rct <- unclass(bbox)
  new_rct <- rct

  if ((rct$ymin > rct$ymax) && (dim(x)[1] > 0)) {
    new_rct$ymin <- rct$ymax
    new_rct$ymax <- rct$ymin

    if (inherits(x, "nativeRaster")) {
      # the dimensions of a nativeRaster are lying in the sense that
      # they are row-major but are being stored column-major in the way
      # that R's indexing functions work
      attrs <- attributes(x)
      dim(x) <- rev(dim(x))
      x <- x[, ncol(x):1, drop = FALSE]
      attributes(x) <- attrs
    } else {
      x <- x[nrow(x):1, , drop = FALSE]
    }
  }

  if ((rct$xmin > rct$xmax) && (dim(x)[2] > 0)) {
    new_rct$xmin <- rct$xmax
    new_rct$xmax <- rct$xmin

    if (inherits(x, "nativeRaster")) {
      attrs <- attributes(x)
      dim(x) <- rev(dim(x))
      x <- x[nrow(x):1, , drop = FALSE]
      attributes(x) <- attrs
    } else {
      x <- x[, ncol(x):1, drop = FALSE]
    }
  }

  list(x = x, bbox = new_wk_rct(new_rct, crs = wk_crs(bbox)))
}`

