const rtdal009975Source0029 = "geodesic_attr <- function(geodesic) {\n  if (!is.logical(geodesic) || (length(geodesic) != 1L)) {\n    stop(\"`geodesic` must be TRUE, FALSE, or NA\", call. = FALSE)\n  }\n\n  if (identical(geodesic, FALSE)) {\n    NULL\n  } else {\n    geodesic\n  }\n}"

